/// The decisive M4 round-trip: a monomorphized generic CALL CHAIN through trust-cg.
/// `quad__i64` calls `double__i64` twice via real intra-module `call` edges, so
/// this exercises trust-cg's CALL lowering (arg in X0, link via BL, return in X0,
/// result threaded to the next call) on a FRONTEND-EMITTED artifact — not just
/// straight-line arithmetic. quad(x) = double(double(x)) = 4*x (wrapping).
#[test]
fn frontend_quad_i64_callchain_triple_oracle() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M4_CALLCHAIN_TRUST_IR)
        .expect("frontend M4 call-chain trust-ir text must parse");

    for x in [
        0i64,
        1,
        -1,
        3,
        -7,
        1_000_000,
        i64::MAX,
        i64::MIN,
        -123456789,
    ] {
        let d = x.wrapping_add(x);
        let native = d.wrapping_add(d); // 4*x, wrapping
        let interp = interp_unary(&module, "quad__i64", x);
        let jit = jit_call_unary(&module, "quad__i64", x);
        assert_eq!(native, interp, "interpreter disagrees on quad({x})");
        assert_eq!(
            native, jit,
            "JIT machine code (call chain) disagrees on quad({x}): native={native} jit={jit}"
        );
    }
}

/// M5.2 round-trip: `let`-bindings through trust-cg JIT. `poly` (= 3x via two
/// sequential lets) and `quad_let` (= 4x via a let-bound call result feeding a
/// second call). Confirms the let-threaded SSA values survive trust-cg codegen.
#[test]
fn frontend_let_bindings_triple_oracle() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_LET_TRUST_IR)
        .expect("frontend M5 let trust-ir text must parse");

    for x in [0i64, 1, -1, 5, -3, 7, 1_000_000, i64::MAX, i64::MIN] {
        // poly(x) = (x+x)+x, wrapping at i64.
        let poly_native = x.wrapping_add(x).wrapping_add(x);
        assert_eq!(
            poly_native,
            interp_unary(&module, "poly__i64", x),
            "interp poly({x})"
        );
        assert_eq!(
            poly_native,
            jit_call_unary(&module, "poly__i64", x),
            "JIT poly({x})"
        );
        // quad_let(x) = { let d = x+x; d+d }, wrapping at i64.
        let d = x.wrapping_add(x);
        let ql_native = d.wrapping_add(d);
        assert_eq!(
            ql_native,
            interp_unary(&module, "quad_let__i64", x),
            "interp quad_let({x})"
        );
        assert_eq!(
            ql_native,
            jit_call_unary(&module, "quad_let__i64", x),
            "JIT quad_let({x})"
        );
    }
}

/// M5.3 round-trip: `match`-as-value over a scalar through trust-cg JIT. `classify`
/// (a 4-way Switch into a join) and `step` (binding catch-all whose arms call a
/// helper). Exercises trust-cg's Switch lowering + join block-param on frontend
/// output.
#[test]
fn frontend_scalar_match_triple_oracle() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_MATCH_TRUST_IR)
        .expect("frontend M5 match trust-ir text must parse");

    let classify_native = |x: i64| -> i64 {
        match x {
            0 => 100,
            1 => 200,
            7 => 700,
            _ => 999,
        }
    };
    let step_native = |x: i64| -> i64 {
        match x {
            0 => (x + 1).wrapping_add(x + 1),
            n => n.wrapping_add(n),
        }
    };

    for x in [0i64, 1, 2, 7, -5, 100, i64::MAX, i64::MIN] {
        let cn = classify_native(x);
        assert_eq!(
            cn,
            interp_unary(&module, "classify__i64", x),
            "interp classify({x})"
        );
        assert_eq!(
            cn,
            jit_call_unary(&module, "classify__i64", x),
            "JIT classify({x})"
        );
        let sn = step_native(x);
        assert_eq!(
            sn,
            interp_unary(&module, "step__i64", x),
            "interp step({x})"
        );
        assert_eq!(sn, jit_call_unary(&module, "step__i64", x), "JIT step({x})");
    }
}

// Heap-graph builders for Level (leak the boxes — fine for a short test).
fn lvl(tag: i64, a: *const LevelNode, b: *const LevelNode) -> *const LevelNode {
    Box::into_raw(Box::new(LevelNode { tag, a, b })) as *const LevelNode
}
fn nul() -> *const LevelNode {
    std::ptr::null()
}
// tag mapping: Zero=0, Succ=1, Max=2, IMax=3, Param=4.
fn zero() -> *const LevelNode {
    lvl(0, nul(), nul())
}
fn succ(x: *const LevelNode) -> *const LevelNode {
    lvl(1, x, nul())
}
fn max(a: *const LevelNode, b: *const LevelNode) -> *const LevelNode {
    lvl(2, a, b)
}
fn imax(a: *const LevelNode, b: *const LevelNode) -> *const LevelNode {
    lvl(3, a, b)
}
fn param() -> *const LevelNode {
    lvl(4, nul(), nul())
}

/// Native oracle: count the Succ (tag 1) nodes in a Level heap graph.
unsafe fn count_succ_native(p: *const LevelNode) -> i64 {
    unsafe {
        let n = &*p;
        match n.tag {
            0 | 4 => 0,                                               // Zero / Param
            1 => 1 + count_succ_native(n.a),                          // Succ
            2 | 3 => count_succ_native(n.a) + count_succ_native(n.b), // Max / IMax
            _ => unreachable!("bad tag {}", n.tag),
        }
    }
}

/// M5.4 round-trip: a recursive ADT-matching, heap-walking, self-recursive
/// function through trust-cg JIT. Builds real `Level` heap graphs in Rust, JITs
/// `count_succ`, and asserts native == JIT machine code. This exercises trust-cg's
/// GEP+Load (tag + payload pointers), Switch on a loaded value, intra-module
/// SELF-recursion, and the join block-param — all on frontend-emitted code, on a
/// genuine heap. (The trust-ir interpreter already cross-checks this frontend-side
/// over the same shapes via the M5.4 differential; here we add executed machine
/// code over a real heap graph.)
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn frontend_count_succ_recursive_adt_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "frontend_count_succ_recursive_adt_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_ADT_TRUST_IR)
        .expect("frontend M5.4 ADT-match trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of count_succ failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("count_succ__i64")
        .expect("JIT symbol count_succ__i64 not found")
        .as_ptr();
    // SAFETY: machine code for a `(*const Level) -> i64` fn; buffer held live.
    let f: CountFn = unsafe { std::mem::transmute(raw) };

    // A spread of heap graphs incl. leaves, deep chains, and binary-recursive arms.
    let graphs: Vec<(*const LevelNode, &str)> = vec![
        (zero(), "Zero"),
        (param(), "Param"),
        (succ(zero()), "Succ Zero"),
        (succ(succ(succ(zero()))), "Succ^3 Zero"),
        (max(succ(zero()), succ(succ(zero()))), "Max(S,S^2)"),
        (imax(param(), succ(zero())), "IMax(Param,S)"),
        (max(param(), succ(max(succ(zero()), zero()))), "nested"),
    ];
    for (g, label) in graphs {
        let native = unsafe { count_succ_native(g) };
        let jit = f(g);
        assert_eq!(
            native, jit,
            "JIT machine code (recursive heap-walk) disagrees on {label}: native={native} jit={jit}"
        );
    }
}

/// Native oracles mirroring the corpus predicate arms (is_zero != !is_nonzero in
/// general — Param is neither, by the corpus semantics).
unsafe fn is_zero_native(p: *const LevelNode) -> bool {
    unsafe {
        let n = &*p;
        match n.tag {
            0 => true,                                       // Zero
            2 => is_zero_native(n.a) && is_zero_native(n.b), // Max
            3 => is_zero_native(n.b),                        // IMax
            1 | 4 => false,                                  // Succ / Param
            _ => unreachable!(),
        }
    }
}
unsafe fn is_nonzero_native(p: *const LevelNode) -> bool {
    unsafe {
        let n = &*p;
        match n.tag {
            1 => true,                                             // Succ
            2 => is_nonzero_native(n.a) || is_nonzero_native(n.b), // Max
            3 => is_nonzero_native(n.b),                           // IMax
            0 | 4 => false,                                        // Zero / Param
            _ => unreachable!(),
        }
    }
}

/// M5.6 CAPSTONE round-trip: the REAL clean-kernel `is_zero`/`is_nonzero`
/// predicates — match over the recursive Level ADT, `&&`/`||` short-circuit, and
/// self-recursion, all through the unified MonoCx — JIT-compiled and executed on
/// real heap graphs, native == JIT machine code. This is the same leaf class
/// LowerCx (M1/M2) hand-targeted, now end-to-end through the unified path.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn frontend_is_zero_predicate_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("frontend_is_zero_predicate_roundtrip");
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_PRED_TRUST_IR)
        .expect("frontend M5.6 predicate trust-ir text must parse");
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of predicates failed")
        .buffer;
    let raw_z = buffer
        .get_fn_ptr_bound("is_zero__i64")
        .expect("is_zero symbol")
        .as_ptr();
    let raw_nz = buffer
        .get_fn_ptr_bound("is_nonzero__i64")
        .expect("is_nonzero symbol")
        .as_ptr();
    // SAFETY: machine code for `(*const Level) -> bool` fns; buffer held live.
    let is_zero: PredFn = unsafe { std::mem::transmute(raw_z) };
    let is_nonzero: PredFn = unsafe { std::mem::transmute(raw_nz) };

    let graphs: Vec<(*const LevelNode, &str)> = vec![
        (zero(), "Zero"),
        (succ(zero()), "Succ Zero"),
        (param(), "Param"),
        (max(zero(), zero()), "Max(Z,Z)"),
        (max(zero(), succ(zero())), "Max(Z,S)"),
        (imax(succ(zero()), zero()), "IMax(S,Z)"),
        (imax(zero(), succ(zero())), "IMax(Z,S)"),
        (
            max(imax(param(), zero()), max(zero(), zero())),
            "nested all-zero",
        ),
        (max(zero(), imax(zero(), succ(zero()))), "nested with succ"),
    ];
    for (g, label) in graphs {
        let (zn, nzn) = unsafe { (is_zero_native(g), is_nonzero_native(g)) };
        assert_eq!(zn, is_zero(g), "JIT is_zero disagrees on {label}");
        assert_eq!(nzn, is_nonzero(g), "JIT is_nonzero disagrees on {label}");
    }
}

#[test]
fn frontend_m5_if_parses_with_join_block() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_IF_TRUST_IR)
        .expect("frontend M5 if/join trust-ir text must parse");
    let names: Vec<&str> = module.functions.iter().map(|f| f.name.as_str()).collect();
    assert!(
        names.contains(&"pick__i64") && names.contains(&"select__i64"),
        "got {names:?}"
    );
}

/// M5.1 round-trip: control flow (`if`/`else` → CondBr + join) through trust-cg.
/// `pick`/`select` lower to a CondBr, two branch blocks, and a join block carrying
/// the result as a block param — so this exercises trust-cg's branch + block-param
/// (phi-like) lowering and the bool+i64+i64 C ABI on a FRONTEND-EMITTED artifact.
#[test]
fn frontend_pick_select_if_triple_oracle() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M5_IF_TRUST_IR)
        .expect("frontend M5 if/join trust-ir text must parse");

    for &name in &["pick__i64", "select__i64"] {
        for (c, a, b) in [
            (true, 7i64, 9i64),
            (false, 7, 9),
            (true, i64::MIN, i64::MAX),
            (false, i64::MIN, i64::MAX),
            (true, -123, 456),
            (false, -123, 456),
        ] {
            let native = if c { a } else { b };
            let interp = interp_select(&module, name, c, a, b);
            let jit = jit_call_select(&module, name, c, a, b);
            assert_eq!(
                native, interp,
                "interpreter disagrees on {name}({c},{a},{b})"
            );
            assert_eq!(
                native, jit,
                "JIT machine code (if/join) disagrees on {name}({c},{a},{b}): native={native} jit={jit}"
            );
        }
    }
}

