/// M5.7c round-trip: unary `-` and the integer binops (And/Or/Xor, signed
/// Div/Rem, Shl + signed AShr) through trust-cg JIT. Builds the frontend-emitted
/// ops module, then for each fn cross-checks native Rust oracle == trust-cg IR
/// interpreter == JIT machine code over a spread of inputs incl. negatives and a
/// signed-shift case. Divisors are non-zero and shift amounts are in [0,64) so
/// neither the interpreter nor the JIT hits defined UB. This exercises trust-cg's
/// `neg`/`and`/`or`/`xor`/`sdiv`/`srem`/`shl`/`ashr` lowering on real machine code.
#[test]
fn frontend_m5g_ops_triple_oracle() {
    let module = emitted_fixture::parse_emitted(FRONTEND_M5G_OPS_TRUST_IR)
        .expect("frontend M5.7c ops trust-ir text must parse");

    // negate(x) = -x (wrapping, so -i64::MIN == i64::MIN).
    for x in [0i64, 7, -7, 123456, -123456, i64::MAX, i64::MIN] {
        let native = x.wrapping_neg();
        assert_eq!(
            native,
            interp_unary(&module, "negate__i64", x),
            "interp negate({x})"
        );
        assert_eq!(
            native,
            jit_call_unary_op(&module, "negate__i64", x),
            "JIT negate({x})"
        );
    }

    // bitops(a,b) = (a & b) | (a ^ b).
    for (a, b) in [
        (0i64, 0i64),
        (12, 10),
        (-1, 5),
        (-8, -3),
        (i64::MAX, 1),
        (-123, 456),
    ] {
        let native = (a & b) | (a ^ b);
        assert_eq!(
            native,
            interp_bin(&module, "bitops__i64", a, b),
            "interp bitops({a},{b})"
        );
        assert_eq!(
            native,
            jit_call_bin_op(&module, "bitops__i64", a, b),
            "JIT bitops({a},{b})"
        );
    }

    // divrem(a,b) = a/b + a%b (signed; b != 0).
    for (a, b) in [
        (7i64, 2i64),
        (-7, 2),
        (7, -2),
        (-7, -3),
        (100, 9),
        (i64::MAX, 3),
    ] {
        let native = (a / b).wrapping_add(a % b);
        assert_eq!(
            native,
            interp_bin(&module, "divrem__i64", a, b),
            "interp divrem({a},{b})"
        );
        assert_eq!(
            native,
            jit_call_bin_op(&module, "divrem__i64", a, b),
            "JIT divrem({a},{b})"
        );
    }

    // shifts(a,n) = (a << n) >> n (signed AShr; 0 <= n < 64).
    for (a, n) in [
        (1i64, 0i64),
        (1, 3),
        (-1, 5),
        (255, 8),
        (-1024, 4),
        (i64::MIN, 1),
    ] {
        let native = a.wrapping_shl(n as u32).wrapping_shr(n as u32);
        assert_eq!(
            native,
            interp_bin(&module, "shifts__i64", a, n),
            "interp shifts({a},{n})"
        );
        assert_eq!(
            native,
            jit_call_bin_op(&module, "shifts__i64", a, n),
            "JIT shifts({a},{n})"
        );
    }
}

