/// The native `T` heap-node layout, byte-for-byte as rustc lays out the niche enum
/// `T { L(i64), N(Box<T>, Box<T>) }` (16 bytes, align 8; probed against real rustc
/// memory): two 8-byte words. `T::L(n)` = `{ w0 = 0, w1 = n as u64 }` (the niche tag
/// 0 at @0 selects L; the i64 payload is at @8). `T::N(a,b)` = `{ w0 = a_ptr, w1 =
/// b_ptr }` (the non-null child pointer at @0 selects N). `#[repr(C)]` fixes both
/// words at @0/@8 so the IR's `load @0` (tag) / `gep @8` (field b) offsets are exact.
#[repr(C)]
struct SzNode {
    w0: u64,
    w1: u64,
}

/// `(*const SzNode) -> i64` as the AAPCS64 C ABI sees it. The MIR `&T` param is passed
/// by value as the thin node pointer (spilled to a slot inside the callee).
type SzFn = extern "C" fn(*const SzNode) -> i64;

// Heap-graph builders for `T` (leak the boxes — fine for a short test).
fn sz_leaf(n: i64) -> *const SzNode {
    Box::into_raw(Box::new(SzNode {
        w0: 0,
        w1: n as u64,
    })) as *const SzNode
}
fn sz_node(a: *const SzNode, b: *const SzNode) -> *const SzNode {
    Box::into_raw(Box::new(SzNode {
        w0: a as u64,
        w1: b as u64,
    })) as *const SzNode
}

/// Native oracle: `sz` counts leaves. `L(_) => 1`, `N(a,b) => sz(a) + sz(b)`. Reads
/// the niche the SAME way the IR does (w0 == 0 -> leaf).
unsafe fn sz_native(p: *const SzNode) -> i64 {
    unsafe {
        let n = &*p;
        if n.w0 == 0 {
            1 // T::L
        } else {
            // T::N: w0 / w1 are the two child Box pointers.
            sz_native(n.w0 as *const SzNode) + sz_native(n.w1 as *const SzNode)
        }
    }
}

/// END-TO-END MIR-PATH VERIFICATION: Rust `sz` -> MIR -> trust-ir (stage1 `--mir-emit`)
/// -> trust-cg JIT -> machine code == native Rust, over real `T` heap graphs. This is
/// the first MIR-lowered function verified by executed machine code (not just valid
/// IR). It exercises, on MIR-emitted code: the niche discriminant read (`load @0` +
/// `select`), Box-child binding through stack slots (`alloca`/`store`/`load`), the
/// `ptrtoint` align check (identity on a real pointer), `add.overflow` + its
/// `Assert(!overflow)` (the debug `+`), and intra-module SELF-recursion (`@func.0`).
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_sz_recursive_box_adt_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_sz_recursive_box_adt_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_SZ_TRUST_IR)
        .expect("MIR-emitted `sz` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `sz` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("sz")
        .expect("JIT symbol `sz` not found")
        .as_ptr();
    // SAFETY: machine code for a `(*const SzNode) -> i64` fn; buffer held live.
    let f: SzFn = unsafe { std::mem::transmute(raw) };

    // A spread of `T` heap graphs: bare leaves, single N, left/right chains, and
    // balanced/unbalanced nests. sz(g) == leaf count of g.
    let graphs: Vec<(*const SzNode, &str, i64)> = vec![
        (sz_leaf(0), "L(0)", 1),
        (sz_leaf(42), "L(42)", 1),
        (sz_node(sz_leaf(1), sz_leaf(2)), "N(L,L)", 2),
        (
            sz_node(sz_node(sz_leaf(1), sz_leaf(2)), sz_leaf(3)),
            "N(N(L,L),L)",
            3,
        ),
        (
            sz_node(sz_leaf(1), sz_node(sz_leaf(2), sz_leaf(3))),
            "N(L,N(L,L))",
            3,
        ),
        (
            sz_node(
                sz_node(sz_leaf(1), sz_leaf(2)),
                sz_node(sz_leaf(3), sz_node(sz_leaf(4), sz_leaf(5))),
            ),
            "balanced-ish 5-leaf",
            5,
        ),
        // A deep left-spine of N nodes (6 leaves).
        (
            sz_node(
                sz_node(
                    sz_node(
                        sz_node(sz_node(sz_leaf(1), sz_leaf(2)), sz_leaf(3)),
                        sz_leaf(4),
                    ),
                    sz_leaf(5),
                ),
                sz_leaf(6),
            ),
            "left-spine 6-leaf",
            6,
        ),
    ];

    let mut pass = 0usize;
    for (g, label, expect_leaves) in &graphs {
        // The JIT takes the node pointer BY VALUE (the MIR `&T` thin-pointer param).
        let native = unsafe { sz_native(*g) };
        let jit = f(*g);
        assert_eq!(
            native, *expect_leaves,
            "native sz disagrees with hand-computed leaf count on {label}"
        );
        assert_eq!(
            native, jit,
            "MIR-emitted JIT machine code disagrees with native Rust on {label}: \
             native={native} jit={jit}"
        );
        pass += 1;
    }
    assert_eq!(pass, graphs.len(), "all sz graphs must agree native == JIT");
}

