const EXT_LEVEL_EQ: &str = "_RNvMCs6Y9QqGG6mLd_11micro_sliceNtB2_10MicroLevel8level_eq";

// The SAME `MicroExpr`/`MicroLevel`/`MicroLiteral`/`MicroChecker` shapes the slice
// compiled (so stock rustc lays out the identical niche-free enums the JIT reads;
// probed against real memory: MicroExpr = 32 bytes/align 8, disc i32 @0, BVar u32 @4,
// App/Lam/Pi children Arc @8/@16, Proj idx @4 + Arc @8, ArcInner data @16). Arc layout
// matches the stage1 emit — same rustc family, as the M6 niche cross-check established.
use std::sync::Arc as MeArc;

#[derive(PartialEq, Eq, Clone)]
#[allow(dead_code)]
enum MicroLevel {
    Zero,
    Succ(MeArc<MicroLevel>),
    Max(MeArc<MicroLevel>, MeArc<MicroLevel>),
    IMax(MeArc<MicroLevel>, MeArc<MicroLevel>),
}

#[derive(PartialEq, Eq, Clone)]
#[allow(dead_code)]
enum MicroLiteral {
    Nat(u64),
    String(MeArc<str>),
}

#[derive(PartialEq, Eq, Clone)]
#[allow(dead_code)]
enum MicroExpr {
    BVar(u32),
    Sort(MicroLevel),
    App(MeArc<MicroExpr>, MeArc<MicroExpr>),
    Lam(MeArc<MicroExpr>, MeArc<MicroExpr>),
    Pi(MeArc<MicroExpr>, MeArc<MicroExpr>),
    Let(MeArc<MicroExpr>, MeArc<MicroExpr>, MeArc<MicroExpr>),
    Opaque(MeArc<MicroExpr>),
    Lit(MicroLiteral),
    Proj(u32, MeArc<MicroExpr>),
    Const(MeArc<str>),
}

/// The slice's `MicroChecker` (only `universe_blind` is read — in the Sort arm).
#[repr(C)]
struct MicroChecker {
    universe_blind: bool,
}

impl MicroChecker {
    /// VERBATIM native oracle: the clean-kernel `structural_eq_impl` body.
    fn structural_eq_impl(&self, a: &MicroExpr, b: &MicroExpr) -> bool {
        match (a, b) {
            (MicroExpr::BVar(i), MicroExpr::BVar(j)) => i == j,
            (MicroExpr::Sort(l1), MicroExpr::Sort(l2)) => self.universe_blind || l1 == l2,
            (MicroExpr::Const(n1), MicroExpr::Const(n2)) => n1 == n2,
            (MicroExpr::App(f1, a1), MicroExpr::App(f2, a2)) => {
                self.structural_eq_impl(f1, f2) && self.structural_eq_impl(a1, a2)
            }
            (MicroExpr::Lam(ty1, b1), MicroExpr::Lam(ty2, b2))
            | (MicroExpr::Pi(ty1, b1), MicroExpr::Pi(ty2, b2)) => {
                self.structural_eq_impl(ty1, ty2) && self.structural_eq_impl(b1, b2)
            }
            (MicroExpr::Let(ty1, v1, b1), MicroExpr::Let(ty2, v2, b2)) => {
                self.structural_eq_impl(ty1, ty2)
                    && self.structural_eq_impl(v1, v2)
                    && self.structural_eq_impl(b1, b2)
            }
            (MicroExpr::Opaque(t1), MicroExpr::Opaque(t2)) => self.structural_eq_impl(t1, t2),
            (MicroExpr::Lit(l1), MicroExpr::Lit(l2)) => l1 == l2,
            (MicroExpr::Proj(i1, e1), MicroExpr::Proj(i2, e2)) => {
                i1 == i2 && self.structural_eq_impl(e1, e2)
            }
            _ => false,
        }
    }
}

// ---- the four native leaf-comparison shims (the JIT analog of linked symbols) ----
// All take the trust-ir ABI: a `(ptr, ptr)` where each `ptr` is the ADDRESS of the
// `&`-arg the MIR `<.. as PartialEq>::eq` / `level_eq` call receives (so a `&u32` arm
// passes `&&u32`, an `&Arc<str>` arm passes `&&Arc<str>`; the `MicroLiteral`/`MicroLevel`
// arms pass `&MicroLiteral` / `&MicroLevel` directly).

/// `<&u32 as PartialEq>::eq(self: &&u32, other: &&u32)` — BVar / Proj index `i == j`.
extern "C" fn shim_u32_eq(a: *const *const u32, b: *const *const u32) -> bool {
    // SAFETY: the JIT passes `&&u32` for both args (addresses holding `&u32`).
    unsafe { **a == **b }
}

/// `<&MicroLiteral as PartialEq>::eq(self: &&MicroLiteral, other: &&MicroLiteral)` —
/// the Lit arm `l1 == l2`. The derived `PartialEq` is the blanket `&T` impl, so the
/// call (like the `&u32` / `&Arc<str>` arms) receives DOUBLE references.
extern "C" fn shim_lit_eq(a: *const *const MicroLiteral, b: *const *const MicroLiteral) -> bool {
    // SAFETY: the JIT passes `&&MicroLiteral` for both args.
    unsafe { **a == **b }
}

/// `<&Arc<str> as PartialEq>::eq(self: &&Arc<str>, other: &&Arc<str>)` — Const `n1 == n2`.
extern "C" fn shim_const_eq(a: *const *const MeArc<str>, b: *const *const MeArc<str>) -> bool {
    // SAFETY: the JIT passes `&&Arc<str>` for both args.
    unsafe { **a == **b }
}

/// `MicroLevel::level_eq(self: &MicroLevel, other: &MicroLevel)` — Sort (`self == other`).
extern "C" fn shim_level_eq(a: *const MicroLevel, b: *const MicroLevel) -> bool {
    // SAFETY: the JIT passes `&MicroLevel` for both args.
    unsafe { *a == *b }
}

/// `(*const MicroChecker, *const MicroExpr, *const MicroExpr) -> bool` — the C ABI of
/// the MIR-emitted `structural_eq_impl`: `&self` + the two `&MicroExpr` operands.
type StructuralEqFn =
    extern "C" fn(*const MicroChecker, *const MicroExpr, *const MicroExpr) -> bool;

/// END-TO-END MIR-PATH VERIFICATION: the FIRST verified micro-checker function.
/// Rust `MicroChecker::structural_eq_impl` -> MIR -> trust-ir (stage1 `--mir-emit`,
/// Arc-deref INLINED) -> trust-cg JIT -> machine code == native Rust, over real
/// `Arc<MicroExpr>` heap graphs. Exercises, on MIR-emitted code: the niche-free i32
/// discriminant read + nested `switch`, the INLINED `Arc<MicroExpr>` child deref
/// (`load + gep <ArcInner-data-off=16>`), the 9-way intra-module SELF-recursion
/// (`@func.4`), and the four bound leaf-comparison shims (BVar/Proj `u32`, Lit, Const,
/// Sort).
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_structural_eq_impl_micro_checker_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "mir_structural_eq_impl_micro_checker_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(MIR_STRUCTURAL_EQ_TRUST_IR)
        .expect("MIR-emitted `structural_eq_impl` trust-ir text must parse");
    // Bind the four leaf-comparison externs the body CALLs to native shims.
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_U32_EQ.to_string(), shim_u32_eq as *const u8);
    externs.insert(EXT_LIT_EQ.to_string(), shim_lit_eq as *const u8);
    externs.insert(EXT_CONST_EQ.to_string(), shim_const_eq as *const u8);
    externs.insert(EXT_LEVEL_EQ.to_string(), shim_level_eq as *const u8);

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted `structural_eq_impl` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("MicroChecker__structural_eq_impl")
        .expect("JIT symbol `MicroChecker__structural_eq_impl` not found")
        .as_ptr();
    // SAFETY: machine code for the `(&self, &MicroExpr, &MicroExpr) -> bool` ABI;
    // buffer held live for all calls below.
    let f: StructuralEqFn = unsafe { std::mem::transmute(raw) };

    // The checker the native oracle uses (universe_blind = false, the env-less
    // back-compat ctor; with two equal Sorts the `||` short-circuits to `level_eq`).
    let chk = MicroChecker {
        universe_blind: false,
    };
    let chk_ptr: *const MicroChecker = &chk as *const MicroChecker;

    // Builders for real `Arc<MicroExpr>` graphs.
    let bv = |i: u32| MicroExpr::BVar(i);
    let sort0 = || MicroExpr::Sort(MicroLevel::Zero);
    let sort1 = || MicroExpr::Sort(MicroLevel::Succ(MeArc::new(MicroLevel::Zero)));
    let app = |x: MicroExpr, y: MicroExpr| MicroExpr::App(MeArc::new(x), MeArc::new(y));
    let lam = |t: MicroExpr, b: MicroExpr| MicroExpr::Lam(MeArc::new(t), MeArc::new(b));
    let pi = |t: MicroExpr, b: MicroExpr| MicroExpr::Pi(MeArc::new(t), MeArc::new(b));
    let lett = |t: MicroExpr, v: MicroExpr, b: MicroExpr| {
        MicroExpr::Let(MeArc::new(t), MeArc::new(v), MeArc::new(b))
    };
    let opaque = |t: MicroExpr| MicroExpr::Opaque(MeArc::new(t));
    let proj = |i: u32, e: MicroExpr| MicroExpr::Proj(i, MeArc::new(e));
    let konst = |s: &str| MicroExpr::Const(MeArc::from(s));
    let litn = |n: u64| MicroExpr::Lit(MicroLiteral::Nat(n));

    // A spread of (a, b) pairs across EVERY variant + nesting: equal AND unequal,
    // including leaf-mismatch, structure-mismatch, and deep nested agreement.
    let pairs: Vec<(MicroExpr, MicroExpr, &str)> = vec![
        // --- leaves, equal ---
        (bv(0), bv(0), "BVar eq"),
        (bv(7), bv(7), "BVar eq nonzero"),
        (sort0(), sort0(), "Sort(0) eq"),
        (sort1(), sort1(), "Sort(succ 0) eq"),
        (konst("Nat"), konst("Nat"), "Const eq"),
        (litn(42), litn(42), "Lit eq"),
        // --- leaves, unequal ---
        (bv(1), bv(2), "BVar neq"),
        (sort0(), sort1(), "Sort level neq"),
        (konst("Nat"), konst("Bool"), "Const neq"),
        (litn(1), litn(2), "Lit neq"),
        // --- cross-variant (the `_ => false` arm) ---
        (bv(0), sort0(), "BVar vs Sort"),
        (app(bv(0), bv(1)), lam(bv(0), bv(1)), "App vs Lam"),
        (konst("x"), bv(0), "Const vs BVar"),
        // --- App, nested ---
        (app(bv(0), bv(1)), app(bv(0), bv(1)), "App eq"),
        (app(bv(0), bv(1)), app(bv(0), bv(2)), "App arg neq"),
        (app(bv(9), bv(1)), app(bv(0), bv(1)), "App fn neq"),
        (
            app(app(bv(0), bv(1)), bv(2)),
            app(app(bv(0), bv(1)), bv(2)),
            "App nested eq",
        ),
        (
            app(app(bv(0), bv(1)), bv(2)),
            app(app(bv(0), bv(9)), bv(2)),
            "App nested deep neq",
        ),
        // --- Lam / Pi (share an arm) ---
        (lam(sort0(), bv(0)), lam(sort0(), bv(0)), "Lam eq"),
        (lam(sort0(), bv(0)), lam(sort1(), bv(0)), "Lam ty neq"),
        (pi(sort0(), bv(0)), pi(sort0(), bv(0)), "Pi eq"),
        (pi(sort0(), bv(1)), pi(sort0(), bv(0)), "Pi body neq"),
        (lam(sort0(), bv(0)), pi(sort0(), bv(0)), "Lam vs Pi (cross)"),
        // --- Let (3 children) ---
        (
            lett(sort0(), bv(0), bv(1)),
            lett(sort0(), bv(0), bv(1)),
            "Let eq",
        ),
        (
            lett(sort0(), bv(0), bv(1)),
            lett(sort0(), bv(9), bv(1)),
            "Let val neq",
        ),
        // --- Opaque (single child) ---
        (opaque(bv(3)), opaque(bv(3)), "Opaque eq"),
        (opaque(bv(3)), opaque(bv(4)), "Opaque neq"),
        (
            opaque(app(bv(0), bv(1))),
            opaque(app(bv(0), bv(1))),
            "Opaque nested eq",
        ),
        // --- Proj (idx + child) ---
        (proj(0, bv(5)), proj(0, bv(5)), "Proj eq"),
        (proj(0, bv(5)), proj(1, bv(5)), "Proj idx neq"),
        (proj(2, bv(5)), proj(2, bv(6)), "Proj child neq"),
        // --- a big mixed nest (deep agreement) ---
        (
            lam(pi(sort0(), bv(0)), app(opaque(konst("f")), proj(1, bv(2)))),
            lam(pi(sort0(), bv(0)), app(opaque(konst("f")), proj(1, bv(2)))),
            "deep mixed eq",
        ),
        (
            lam(pi(sort0(), bv(0)), app(opaque(konst("f")), proj(1, bv(2)))),
            lam(pi(sort0(), bv(0)), app(opaque(konst("g")), proj(1, bv(2)))),
            "deep mixed neq (Const deep)",
        ),
    ];

    let mut pass = 0usize;
    for (a, b, label) in &pairs {
        let native = chk.structural_eq_impl(a, b);
        let ap: *const MicroExpr = a as *const MicroExpr;
        let bp: *const MicroExpr = b as *const MicroExpr;
        let jit = f(chk_ptr, ap, bp);
        assert_eq!(
            native, jit,
            "MIR-emitted JIT machine code disagrees with native Rust on `{label}`: \
             native={native} jit={jit}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        pairs.len(),
        "all structural_eq pairs must agree native == JIT"
    );
    // Keep the JIT buffer alive until all calls complete.
    drop(buffer);
}

