// ---- the whnf-core's native checker (env slice) + the verbatim reduction body ----
// The slice's `MicroChecker` holds `env: &[(Arc<str>, Option<MicroExpr>)]` (a fat
// slice ref = 16 bytes). The body's `&self` (a thin pointer to this struct) reaches
// the env for DELTA. We reproduce the EXACT struct so `&self.env` reads correctly.
struct WhnfChecker<'e> {
    env: &'e [(MeArc<str>, Option<MicroExpr>)],
}

// The verbatim reuse fns (lift/subst/instantiate) over the file's `MicroExpr`,
// byte-identical to the slice — the native `instantiate` shim and the oracle use them.
impl MicroExpr {
    fn wh_lift(&self, cutoff: u32, amount: u32) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                if *idx >= cutoff {
                    MicroExpr::BVar(idx.saturating_add(amount))
                } else {
                    self.clone()
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.wh_lift(cutoff, amount)),
                MeArc::new(a.wh_lift(cutoff, amount)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.wh_lift(cutoff, amount)),
                MeArc::new(body.wh_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.wh_lift(cutoff, amount)),
                MeArc::new(body.wh_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Let(ty, val, body) => MicroExpr::Let(
                MeArc::new(ty.wh_lift(cutoff, amount)),
                MeArc::new(val.wh_lift(cutoff, amount)),
                MeArc::new(body.wh_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.wh_lift(cutoff, amount))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.wh_lift(cutoff, amount))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn wh_subst(&self, depth: u32, val: &MicroExpr) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                use std::cmp::Ordering;
                match idx.cmp(&depth) {
                    Ordering::Equal => val.wh_lift(0, depth),
                    Ordering::Greater => MicroExpr::BVar(idx - 1),
                    Ordering::Less => self.clone(),
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.wh_subst(depth, val)),
                MeArc::new(a.wh_subst(depth, val)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.wh_subst(depth, val)),
                MeArc::new(body.wh_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.wh_subst(depth, val)),
                MeArc::new(body.wh_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Let(ty, v, body) => MicroExpr::Let(
                MeArc::new(ty.wh_subst(depth, val)),
                MeArc::new(v.wh_subst(depth, val)),
                MeArc::new(body.wh_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.wh_subst(depth, val))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.wh_subst(depth, val))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn wh_instantiate(&self, arg: &MicroExpr) -> MicroExpr {
        self.wh_subst(0, arg)
    }
}

impl<'e> WhnfChecker<'e> {
    fn wh_env_get(&self, name: &MeArc<str>) -> Option<&MicroExpr> {
        let mut i: usize = 0;
        let n = self.env.len();
        while i < n {
            let entry = &self.env[i];
            if entry.0 == *name {
                return entry.1.as_ref();
            }
            i += 1;
        }
        None
    }
    // VERBATIM BETA/DELTA/SPINE/ZETA control flow (the native oracle).
    fn wh_whnf(&self, e: &MicroExpr) -> MicroExpr {
        match e {
            MicroExpr::Const(name) => {
                if wh_is_native_op(name) {
                    return e.clone();
                }
                if let Some(body) = self.wh_env_get(name) {
                    return self.wh_whnf(body);
                }
                e.clone()
            }
            MicroExpr::App(f, a) => {
                let f_whnf = self.wh_whnf(f);
                match &f_whnf {
                    MicroExpr::Lam(_, body) => {
                        let reduced = body.wh_instantiate(a);
                        self.wh_whnf(&reduced)
                    }
                    _ => {
                        let mut head = f_whnf;
                        let mut args: Vec<MicroExpr> = vec![a.as_ref().clone()];
                        while let MicroExpr::App(hf, ha) = &head {
                            args.push(ha.as_ref().clone());
                            head = self.wh_whnf(hf);
                        }
                        args.reverse();
                        if let MicroExpr::Const(name) = &head
                            && !wh_is_native_op(name)
                            && let Some(body) = self.wh_env_get(name)
                        {
                            let mut applied = body.clone();
                            for arg in &args {
                                applied =
                                    MicroExpr::App(MeArc::new(applied), MeArc::new(arg.clone()));
                            }
                            return self.wh_whnf(&applied);
                        }
                        let mut rebuilt = head;
                        for arg in args {
                            rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                        }
                        rebuilt
                    }
                }
            }
            MicroExpr::Let(_, val, body) => {
                let reduced = body.wh_instantiate(val);
                self.wh_whnf(&reduced)
            }
            _ => e.clone(),
        }
    }
}

// is_native_op SHIM: always false in the slice (so DELTA/stuck run verbatim).
fn wh_is_native_op(_name: &MeArc<str>) -> bool {
    false
}

// ---- the whnf-core's native leaf shims (the JIT analog of linked symbols) ----

/// `<MicroExpr as Clone>::clone(&self) -> MicroExpr` (sret).
extern "C" fn wh_shim_clone(sret: *mut MicroExpr, this: *const MicroExpr) {
    // SAFETY: 32-byte uninit sret slot + a valid `&MicroExpr`.
    unsafe {
        let cloned = (*this).clone();
        std::ptr::write(sret, cloned);
    }
}

/// `is_native_op(&Arc<str>) -> bool` — the slice's `false` stub.
extern "C" fn wh_shim_is_native_op(_name: *const MeArc<str>) -> bool {
    false
}

/// `MicroChecker::env_get(&self, &Arc<str>) -> Option<&MicroExpr>` (sret). The JIT
/// passes a sret slot for the 8-byte `Option<&MicroExpr>`, then `&self` + `&name`.
extern "C" fn wh_shim_env_get(
    sret: *mut Option<std::ptr::NonNull<MicroExpr>>,
    this: *const WhnfChecker,
    name: *const MeArc<str>,
) {
    // SAFETY: valid `&self`/`&name`; `sret` an 8-byte slot. We write the result as a
    // niche-encoded `Option<NonNull<MicroExpr>>` (None = null), the SAME 8-byte niche
    // layout as `Option<&MicroExpr>` the body's `discriminant`/`switchInt` reads —
    // using raw pointers sidesteps the `&MicroExpr` lifetime variance through `*mut`.
    unsafe {
        let r: Option<std::ptr::NonNull<MicroExpr>> =
            (*this).wh_env_get(&*name).map(std::ptr::NonNull::from);
        std::ptr::write(sret, r);
    }
}

/// `MicroExpr::instantiate(&self, &arg) -> MicroExpr` (sret) = `subst(0, arg)`.
extern "C" fn wh_shim_instantiate(
    sret: *mut MicroExpr,
    this: *const MicroExpr,
    arg: *const MicroExpr,
) {
    // SAFETY: 32-byte sret slot + valid `&self`/`&arg`.
    unsafe {
        let r = (*this).wh_instantiate(&*arg);
        std::ptr::write(sret, r);
    }
}

/// `<Arc<MicroExpr> as AsRef<MicroExpr>>::as_ref(&self) -> &MicroExpr` (+16).
extern "C" fn wh_shim_as_ref(arc_ref: *const *const u8) -> *const MicroExpr {
    // SAFETY: `arc_ref` is `&Arc<MicroExpr>` (the address of a thin Arc pointer);
    // ArcInner `data` is at byte offset 16 (2 usize counters).
    unsafe { (*arc_ref).add(16) as *const MicroExpr }
}

/// `Vec::<MicroExpr>::push(&mut self, value: MicroExpr)` (value passed by-ref).
extern "C" fn wh_shim_push(vec: *mut Vec<MicroExpr>, value: *const MicroExpr) {
    // SAFETY: valid `&mut Vec`; `value` an initialized by-value `MicroExpr` handoff.
    unsafe {
        let v = std::ptr::read(value);
        (*vec).push(v);
    }
}

/// `<Vec<MicroExpr> as DerefMut>::deref_mut(&mut self) -> &mut [MicroExpr]` (sret).
extern "C" fn wh_shim_deref_mut(sret: *mut (*mut MicroExpr, usize), vec: *mut Vec<MicroExpr>) {
    // SAFETY: 2-word sret slot; valid `&mut Vec`.
    unsafe {
        let s: &mut [MicroExpr] = (*vec).as_mut_slice();
        std::ptr::write(sret, (s.as_mut_ptr(), s.len()));
    }
}

/// `<[MicroExpr]>::reverse(&mut self)` — fat slice passed by-ref.
extern "C" fn wh_shim_reverse(slice_ref: *const (*mut MicroExpr, usize)) {
    // SAFETY: `slice_ref` points at a valid `(ptr, len)` fat slice.
    unsafe {
        let (ptr, len) = *slice_ref;
        let s: &mut [MicroExpr] = std::slice::from_raw_parts_mut(ptr, len);
        s.reverse();
    }
}

/// `(*mut MicroExpr /*sret*/, *const WhnfChecker, *const MicroExpr)` — the C ABI of
/// the MIR-emitted `whnf`: sret result, `&self`, `&e`.
type WhnfFn = extern "C" fn(*mut MicroExpr, *const WhnfChecker, *const MicroExpr);

/// END-TO-END MIR-PATH CAPSTONE: the JIT-EXECUTED verified whnf-CORE. Rust `whnf`
/// (the verbatim BETA/DELTA/SPINE/ZETA reduction) -> MIR -> trust-ir (stage1
/// `--mir-emit`, with the `for`-loop iterators / `vec!` / drop-glue INLINED) ->
/// trust-cg JIT -> machine code == native Rust, over real `Arc<MicroExpr>` heap
/// graphs and a DELTA env. Compares the resulting `MicroExpr` trees structurally.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_whnf_core_micro_checker_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_whnf_core_micro_checker_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_WHNF_CORE_TRUST_IR)
        .expect("MIR-emitted `whnf` trust-ir text must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_WH_CLONE.to_string(), wh_shim_clone as *const u8);
    externs.insert(
        EXT_WH_IS_NATIVE.to_string(),
        wh_shim_is_native_op as *const u8,
    );
    externs.insert(EXT_WH_ENV_GET.to_string(), wh_shim_env_get as *const u8);
    externs.insert(
        EXT_WH_INSTANTIATE.to_string(),
        wh_shim_instantiate as *const u8,
    );
    externs.insert(EXT_WH_AS_REF.to_string(), wh_shim_as_ref as *const u8);
    externs.insert(EXT_WH_PUSH.to_string(), wh_shim_push as *const u8);
    externs.insert(EXT_WH_DEREF_MUT.to_string(), wh_shim_deref_mut as *const u8);
    externs.insert(EXT_WH_REVERSE.to_string(), wh_shim_reverse as *const u8);
    // The INLINED `Arc::new` / `Box::new_uninit` / vec-buffer allocations lower to
    // `heap_alloc` -> a `__rust_alloc` call; bind the same allocator shim the other
    // MIR round-trips use (the JIT analog of the AOT linked allocator). The freshly
    // allocated tree nodes leak (no dealloc), which the drop-no-op model owns.
    externs.insert("__rust_alloc".to_string(), rust_alloc_shim as *const u8);

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted `whnf` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("MicroChecker____e___whnf")
        .expect("JIT symbol `MicroChecker____e___whnf` not found")
        .as_ptr();
    // SAFETY: machine code for the `(sret, &self, &e)` ABI; buffer held live.
    let f: WhnfFn = unsafe { std::mem::transmute(raw) };

    // Builders.
    let bv = |i: u32| MicroExpr::BVar(i);
    let app = |x: MicroExpr, y: MicroExpr| MicroExpr::App(MeArc::new(x), MeArc::new(y));
    let lam = |t: MicroExpr, b: MicroExpr| MicroExpr::Lam(MeArc::new(t), MeArc::new(b));
    let let_ = |t: MicroExpr, v: MicroExpr, b: MicroExpr| {
        MicroExpr::Let(MeArc::new(t), MeArc::new(v), MeArc::new(b))
    };
    let konst = |s: &str| MicroExpr::Const(MeArc::from(s));
    let sort0 = || MicroExpr::Sort(MicroLevel::Zero);

    // A DELTA env: `f := Lam(Sort, BVar0)` (the identity), `g := Const("g")` (a stuck
    // alias chain head). The SPINE-DELTA case applies a Const head with an env body.
    let env: Vec<(MeArc<str>, Option<MicroExpr>)> = vec![
        (MeArc::from("f"), Some(lam(sort0(), bv(0)))),
        (MeArc::from("id"), Some(lam(sort0(), bv(0)))),
        (MeArc::from("undef"), None),
    ];
    let checker = WhnfChecker { env: &env };

    // Cases hitting BETA / DELTA / SPINE / ZETA / nested / leaves.
    let cases: Vec<(MicroExpr, &str)> = vec![
        // leaves: return-as-is.
        (bv(3), "BVar leaf (return-as-is)"),
        (sort0(), "Sort leaf (return-as-is)"),
        (konst("stuck"), "Const with no env body (stuck)"),
        // DELTA: Const("f") unfolds to its env body (a Lam), then whnf of the Lam = Lam.
        (konst("f"), "DELTA: Const f -> Lam body"),
        // BETA: App(Lam(BVar0), arg) -> arg.
        (
            app(lam(sort0(), bv(0)), konst("arg")),
            "BETA: (\\.0) arg -> arg",
        ),
        // BETA via DELTA head: App(Const f, x) -> f unfolds to Lam, beta -> x.
        (app(konst("f"), konst("x")), "BETA+DELTA: f x -> x"),
        // ZETA: Let(_, val, BVar0) -> val.
        (let_(sort0(), konst("v"), bv(0)), "ZETA: let v in 0 -> v"),
        // nested beta: App(Lam(App(BVar0, c)), Lam(BVar0)) -> (\.0) c -> c.
        (
            app(lam(sort0(), app(bv(0), konst("c"))), lam(sort0(), bv(0))),
            "nested: (\\.(0 c)) (\\.0) -> c",
        ),
        // SPINE (stuck head): App(App(Const stuck, x), y) -> flatten+reverse+rebuild.
        (
            app(app(konst("stuck"), konst("x")), konst("y")),
            "SPINE: (stuck x) y -> stuck x y",
        ),
        // SPINE depth-3 stuck: App(App(App(stuck,a),b),c).
        (
            app(app(app(konst("stuck"), bv(1)), bv(2)), bv(3)),
            "SPINE depth-3 stuck rebuild",
        ),
        // SPINE-DELTA: App(App(Const g-unknown, x), y) with stuck head (no env) rebuilds.
        (
            app(app(konst("h"), sort0()), konst("z")),
            "SPINE: (h Sort) z -> h Sort z",
        ),
    ];

    let mut pass = 0usize;
    for (e, label) in &cases {
        let native = checker.wh_whnf(e);
        let mut jit_out = std::mem::MaybeUninit::<MicroExpr>::uninit();
        let cp: *const WhnfChecker = &checker as *const WhnfChecker;
        let ep: *const MicroExpr = e as *const MicroExpr;
        // SAFETY: `f` fully writes the sret result; `assume_init` is then sound.
        let jit = unsafe {
            f(jit_out.as_mut_ptr(), cp, ep);
            jit_out.assume_init()
        };
        assert!(
            native == jit,
            "MIR-emitted `whnf` JIT result disagrees with native on `{label}`"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all whnf-core cases must agree native == JIT"
    );
    drop(buffer);
}

// ============================================================================
// MIR-PATH CAPSTONE #2: the JIT-EXECUTED verified def_eq — the SECOND headline
// micro-checker pillar (definitional equality). Unlike every prior MIR round-trip
// (each a SINGLE fn with its callees as extern stubs), this is a MULTI-FUNCTION
// MODULE: the stage1 `--mir-emit-closure def_eq` lowering computes the call-graph
// CLOSURE over the crate's OWN fns and emits EVERY member into ONE module with
// cross-member `Call`s wired to the IN-MODULE body `FuncId`s. So `def_eq` composes
// the REAL in-module `whnf` + `structural_eq` (+ whnf's callees instantiate -> subst
// -> lift, env_get, is_native_op, the derived MicroExpr/Level/Literal clones) —
// NOT shims. The 11 closure members have real bodies; only the TRUE leaves remain
// 0-block externs (Arc::as_ref / Vec push+deref_mut / slice::reverse / the
// PartialEq::eq impls / Arc clones / Option::as_ref / Ord::cmp / Sub::sub /
// saturating_add / __rust_alloc), bound below.
//
// We run native `def_eq` == JIT machine code (bool result) over cases exercising
// EACH def_eq path:
//   - structurally-equal-after-whnf TRUE: `(\.0) c` vs `c` (both whnf to `c`);
//   - DELTA-then-equal TRUE: `Const f` vs its env body (a Lam);
//   - congruence TRUE: `App (Const f) x` vs `App (\.0) x` (heads ≡ only after whnf);
//   - Pi / Lam congruence TRUE;
//   - reflexive stuck App TRUE; identical Const TRUE; identical BVar TRUE;
//   - FALSE: Sort vs Const; App heads differ; a stuck pair; BVar i != j; Const n1!=n2.
