/// The def_eq slice's `MicroChecker`: `env` fat slice (offset 0, 16 bytes) then
/// `universe_blind` (offset 16). The in-module `env_get` reads `&self.env`; the
/// in-module `structural_eq` Sort arm reads `&self.universe_blind`. `#[repr(C)]`
/// pins the layout the MIR-emitted bodies assume.
#[repr(C)]
struct DeChecker<'e> {
    env: &'e [(MeArc<str>, Option<MicroExpr>)],
    universe_blind: bool,
}

impl<'e> DeChecker<'e> {
    fn de_env_get(&self, name: &MeArc<str>) -> Option<&MicroExpr> {
        let mut i: usize = 0;
        let n = self.env.len();
        while i < n {
            let entry = &self.env[i];
            if entry.0 == *name {
                return entry.1.as_ref();
            }
            i += 1;
        }
        None
    }
    // VERBATIM whnf (the env-aware reduction) — reuses `wh_instantiate` (= subst(0,_)).
    fn de_whnf(&self, e: &MicroExpr) -> MicroExpr {
        match e {
            MicroExpr::Const(name) => {
                if wh_is_native_op(name) {
                    return e.clone();
                }
                if let Some(body) = self.de_env_get(name) {
                    return self.de_whnf(body);
                }
                e.clone()
            }
            MicroExpr::App(f, a) => {
                let f_whnf = self.de_whnf(f);
                match &f_whnf {
                    MicroExpr::Lam(_, body) => {
                        let reduced = body.wh_instantiate(a);
                        self.de_whnf(&reduced)
                    }
                    _ => {
                        let mut head = f_whnf;
                        let mut args: Vec<MicroExpr> = vec![a.as_ref().clone()];
                        while let MicroExpr::App(hf, ha) = &head {
                            args.push(ha.as_ref().clone());
                            head = self.de_whnf(hf);
                        }
                        args.reverse();
                        if let MicroExpr::Const(name) = &head
                            && !wh_is_native_op(name)
                            && let Some(body) = self.de_env_get(name)
                        {
                            let mut applied = body.clone();
                            for arg in &args {
                                applied =
                                    MicroExpr::App(MeArc::new(applied), MeArc::new(arg.clone()));
                            }
                            return self.de_whnf(&applied);
                        }
                        let mut rebuilt = head;
                        for arg in args {
                            rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                        }
                        rebuilt
                    }
                }
            }
            MicroExpr::Let(_, val, body) => {
                let reduced = body.wh_instantiate(val);
                self.de_whnf(&reduced)
            }
            _ => e.clone(),
        }
    }
    // VERBATIM structural_eq (the Sort arm reads universe_blind || l1 == l2).
    fn de_structural_eq(&self, a: &MicroExpr, b: &MicroExpr) -> bool {
        match (a, b) {
            (MicroExpr::BVar(i), MicroExpr::BVar(j)) => i == j,
            (MicroExpr::Sort(l1), MicroExpr::Sort(l2)) => self.universe_blind || l1 == l2,
            (MicroExpr::Const(n1), MicroExpr::Const(n2)) => n1 == n2,
            (MicroExpr::App(f1, a1), MicroExpr::App(f2, a2)) => {
                self.de_structural_eq(f1, f2) && self.de_structural_eq(a1, a2)
            }
            (MicroExpr::Lam(ty1, b1), MicroExpr::Lam(ty2, b2))
            | (MicroExpr::Pi(ty1, b1), MicroExpr::Pi(ty2, b2)) => {
                self.de_structural_eq(ty1, ty2) && self.de_structural_eq(b1, b2)
            }
            (MicroExpr::Let(ty1, v1, b1), MicroExpr::Let(ty2, v2, b2)) => {
                self.de_structural_eq(ty1, ty2)
                    && self.de_structural_eq(v1, v2)
                    && self.de_structural_eq(b1, b2)
            }
            (MicroExpr::Opaque(t1), MicroExpr::Opaque(t2)) => self.de_structural_eq(t1, t2),
            (MicroExpr::Lit(l1), MicroExpr::Lit(l2)) => l1 == l2,
            (MicroExpr::Proj(i1, e1), MicroExpr::Proj(i2, e2)) => {
                i1 == i2 && self.de_structural_eq(e1, e2)
            }
            _ => false,
        }
    }
    // VERBATIM def_eq (checker.rs:832-849), the native oracle.
    fn de_def_eq(&self, a: &MicroExpr, b: &MicroExpr) -> bool {
        let a_whnf = self.de_whnf(a);
        let b_whnf = self.de_whnf(b);
        if self.de_structural_eq(&a_whnf, &b_whnf) {
            return true;
        }
        if let (MicroExpr::App(f1, a1), MicroExpr::App(f2, a2)) = (&a_whnf, &b_whnf) {
            return self.de_def_eq(f1, f2) && self.de_def_eq(a1, a2);
        }
        if let (MicroExpr::Pi(t1, b1), MicroExpr::Pi(t2, b2))
        | (MicroExpr::Lam(t1, b1), MicroExpr::Lam(t2, b2)) = (&a_whnf, &b_whnf)
        {
            return self.de_def_eq(t1, t2) && self.de_def_eq(b1, b2);
        }
        false
    }
}

// ---- the def_eq closure's leaf shims (the JIT analog of linked symbols) ----
// whnf's SPINE leaves (Arc::as_ref / Vec push+deref_mut / slice::reverse) reuse the
// whnf-test shims' exact ABIs.

/// `<Arc<MicroExpr> as AsRef<MicroExpr>>::as_ref(&self) -> &MicroExpr` (+16).
extern "C" fn de_shim_as_ref(arc_ref: *const *const u8) -> *const MicroExpr {
    unsafe { (*arc_ref).add(16) as *const MicroExpr }
}
/// `Vec::<MicroExpr>::push(&mut self, value)` (value by-ref handoff).
extern "C" fn de_shim_push(vec: *mut Vec<MicroExpr>, value: *const MicroExpr) {
    unsafe {
        let v = std::ptr::read(value);
        (*vec).push(v);
    }
}
/// `<Vec<MicroExpr> as DerefMut>::deref_mut(&mut self) -> &mut [MicroExpr]` (sret 2-word).
extern "C" fn de_shim_deref_mut(sret: *mut (*mut MicroExpr, usize), vec: *mut Vec<MicroExpr>) {
    unsafe {
        let s: &mut [MicroExpr] = (*vec).as_mut_slice();
        std::ptr::write(sret, (s.as_mut_ptr(), s.len()));
    }
}
/// `<[MicroExpr]>::reverse(&mut self)` (fat slice by-ref).
extern "C" fn de_shim_reverse(slice_ref: *const (*mut MicroExpr, usize)) {
    unsafe {
        let (ptr, len) = *slice_ref;
        let s: &mut [MicroExpr] = std::slice::from_raw_parts_mut(ptr, len);
        s.reverse();
    }
}
/// `<&u32 as PartialEq>::eq(&&u32, &&u32)` — BVar / Proj index (double ref).
extern "C" fn de_shim_u32_eq(a: *const *const u32, b: *const *const u32) -> bool {
    unsafe { **a == **b }
}
/// `<&MicroLiteral as PartialEq>::eq(&&MicroLiteral, &&MicroLiteral)` (double ref).
extern "C" fn de_shim_lit_eq(a: *const *const MicroLiteral, b: *const *const MicroLiteral) -> bool {
    unsafe { **a == **b }
}
/// `<&Arc<str> as PartialEq>::eq(&&Arc<str>, &&Arc<str>)` — Const arm (double ref).
extern "C" fn de_shim_const_eq(a: *const *const MeArc<str>, b: *const *const MeArc<str>) -> bool {
    unsafe { **a == **b }
}
/// `<&MicroLevel as PartialEq>::eq(&&MicroLevel, &&MicroLevel)` — Sort arm (double ref).
extern "C" fn de_shim_level_eq(a: *const *const MicroLevel, b: *const *const MicroLevel) -> bool {
    unsafe { **a == **b }
}
/// `<Arc<str> as Clone>::clone(sret, &self)` — `Arc<str>` is a FAT pointer (data ptr
/// + length = 16 bytes), so the clone copies BOTH words (the leak model owns the
///   missing refcount bump). Copying only the first word would leave the length garbage
///   and corrupt the cloned `Const` name (the original failure this fixes).
extern "C" fn de_shim_arcstr_clone(sret: *mut [usize; 2], this: *const [usize; 2]) {
    unsafe { std::ptr::write(sret, *this) }
}
/// `<Arc<MicroExpr> as Clone>::clone(sret, &self)`.
extern "C" fn de_shim_arcexpr_clone(sret: *mut usize, this: *const usize) {
    unsafe { std::ptr::write(sret, *this) }
}
/// `<Arc<MicroLevel> as Clone>::clone(sret, &self)`.
extern "C" fn de_shim_arclevel_clone(sret: *mut usize, this: *const usize) {
    unsafe { std::ptr::write(sret, *this) }
}
/// `<Arc<str> as PartialEq>::eq(&self: &Arc<str>, &other: &Arc<str>)` — env_get name
/// compare (single ref).
extern "C" fn de_shim_name_eq(a: *const MeArc<str>, b: *const MeArc<str>) -> bool {
    unsafe { *a == *b }
}
/// `Option::<MicroExpr>::as_ref(&self) -> Option<&MicroExpr>` (sret 8-byte niche).
extern "C" fn de_shim_opt_as_ref(
    sret: *mut Option<std::ptr::NonNull<MicroExpr>>,
    this: *const Option<MicroExpr>,
) {
    unsafe {
        let r: Option<std::ptr::NonNull<MicroExpr>> = (*this).as_ref().map(std::ptr::NonNull::from);
        std::ptr::write(sret, r);
    }
}
/// `<u32 as Ord>::cmp(sret Ordering, &a, &b)` — subst BVar idx.cmp(&depth). Ordering
/// is `i8` { Less=-1, Equal=0, Greater=1 }.
extern "C" fn de_shim_ord_cmp(sret: *mut i8, a: *const u32, b: *const u32) {
    unsafe {
        let o = (*a).cmp(&*b);
        std::ptr::write(sret, o as i8);
    }
}
/// `<&u32 as Sub<u32>>::sub(self: &u32, rhs: u32) -> u32` — subst `idx - 1`.
extern "C" fn de_shim_sub(a: *const u32, b: u32) -> u32 {
    unsafe { *a - b }
}
/// `u32::saturating_add(self: u32, rhs: u32) -> u32` — lift idx + amount.
extern "C" fn de_shim_sat_add(a: u32, b: u32) -> u32 {
    a.saturating_add(b)
}

/// `(*const DeChecker, *const MicroExpr, *const MicroExpr) -> bool` — the C ABI of the
/// MIR-emitted `def_eq`: `&self` + the two `&MicroExpr` operands.
type DefEqFn = extern "C" fn(*const DeChecker, *const MicroExpr, *const MicroExpr) -> bool;

/// END-TO-END MIR-PATH CAPSTONE #2: the JIT-EXECUTED verified def_eq composing the
/// REAL in-module whnf + structural_eq (the SECOND verified micro-checker pillar).
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_def_eq_micro_checker_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_def_eq_micro_checker_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_DEF_EQ_CLOSURE_TRUST_IR)
        .expect("MIR-emitted def_eq closure trust-ir text must parse");
    // CONFIRM the call graph is genuinely IN-MODULE (not extern stubs): whnf,
    // structural_eq, instantiate, subst, lift, env_get all have non-empty bodies.
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("MicroChecker____e___def_eq"),
        "def_eq must be in-module"
    );
    assert!(
        bodied("MicroChecker____e___whnf"),
        "whnf must be IN-MODULE (not a shim)"
    );
    assert!(
        bodied("MicroChecker____e___structural_eq"),
        "structural_eq must be IN-MODULE (not a shim)"
    );
    assert!(
        bodied("MicroExpr__instantiate"),
        "instantiate must be IN-MODULE"
    );
    assert!(bodied("MicroExpr__subst"), "subst must be IN-MODULE");
    assert!(bodied("MicroExpr__lift"), "lift must be IN-MODULE");
    assert!(
        bodied("MicroChecker____e___env_get"),
        "env_get must be IN-MODULE"
    );

    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_DE_AS_REF.to_string(), de_shim_as_ref as *const u8);
    externs.insert(EXT_DE_PUSH.to_string(), de_shim_push as *const u8);
    externs.insert(EXT_DE_DEREF_MUT.to_string(), de_shim_deref_mut as *const u8);
    externs.insert(EXT_DE_REVERSE.to_string(), de_shim_reverse as *const u8);
    externs.insert(EXT_DE_U32_EQ.to_string(), de_shim_u32_eq as *const u8);
    externs.insert(EXT_DE_LIT_EQ.to_string(), de_shim_lit_eq as *const u8);
    externs.insert(EXT_DE_CONST_EQ.to_string(), de_shim_const_eq as *const u8);
    externs.insert(EXT_DE_LEVEL_EQ.to_string(), de_shim_level_eq as *const u8);
    externs.insert(
        EXT_DE_ARCSTR_CLONE.to_string(),
        de_shim_arcstr_clone as *const u8,
    );
    externs.insert(
        EXT_DE_ARCEXPR_CLONE.to_string(),
        de_shim_arcexpr_clone as *const u8,
    );
    externs.insert(
        EXT_DE_ARCLEVEL_CLONE.to_string(),
        de_shim_arclevel_clone as *const u8,
    );
    externs.insert(EXT_DE_NAME_EQ.to_string(), de_shim_name_eq as *const u8);
    externs.insert(
        EXT_DE_OPT_AS_REF.to_string(),
        de_shim_opt_as_ref as *const u8,
    );
    externs.insert(EXT_DE_ORD_CMP.to_string(), de_shim_ord_cmp as *const u8);
    externs.insert(EXT_DE_SUB.to_string(), de_shim_sub as *const u8);
    externs.insert(EXT_DE_SAT_ADD.to_string(), de_shim_sat_add as *const u8);
    externs.insert("__rust_alloc".to_string(), rust_alloc_shim as *const u8);

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted def_eq closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("MicroChecker____e___def_eq")
        .expect("JIT symbol `MicroChecker____e___def_eq` not found")
        .as_ptr();
    let f: DefEqFn = unsafe { std::mem::transmute(raw) };

    // Builders.
    let bv = |i: u32| MicroExpr::BVar(i);
    let app = |x: MicroExpr, y: MicroExpr| MicroExpr::App(MeArc::new(x), MeArc::new(y));
    let lam = |t: MicroExpr, b: MicroExpr| MicroExpr::Lam(MeArc::new(t), MeArc::new(b));
    let pi = |t: MicroExpr, b: MicroExpr| MicroExpr::Pi(MeArc::new(t), MeArc::new(b));
    let konst = |s: &str| MicroExpr::Const(MeArc::from(s));
    let sort0 = || MicroExpr::Sort(MicroLevel::Zero);

    // env: `f := \.0` (identity). The DELTA / congruence cases unfold it.
    let env: Vec<(MeArc<str>, Option<MicroExpr>)> = vec![
        (MeArc::from("f"), Some(lam(sort0(), bv(0)))),
        (MeArc::from("undef"), None),
    ];
    let checker = DeChecker {
        env: &env,
        universe_blind: false,
    };

    // (a, b, expected, label) over EACH def_eq path.
    let cases: Vec<(MicroExpr, MicroExpr, &str)> = vec![
        // structurally-equal-after-whnf TRUE: (\.0) c  vs  c  -> both whnf to c.
        (
            app(lam(sort0(), bv(0)), konst("c")),
            konst("c"),
            "beta-then-equal: (\\.0) c == c",
        ),
        // DELTA-then-equal TRUE: Const f vs its env body (\.0).
        (konst("f"), lam(sort0(), bv(0)), "delta: f == (\\.0)"),
        // congruence TRUE: App (Const f) x vs App (\.0) x — heads ≡ only via whnf-delta.
        (
            app(konst("f"), konst("x")),
            app(lam(sort0(), bv(0)), konst("x")),
            "congruence-App: (f x) == ((\\.0) x)",
        ),
        // Pi congruence TRUE: Pi(f, c) vs Pi((\.0), c) — domain ≡ by delta.
        (
            pi(konst("f"), konst("c")),
            pi(lam(sort0(), bv(0)), konst("c")),
            "congruence-Pi",
        ),
        // Lam congruence TRUE.
        (
            lam(konst("f"), konst("c")),
            lam(lam(sort0(), bv(0)), konst("c")),
            "congruence-Lam",
        ),
        // reflexive stuck App TRUE.
        (
            app(konst("stuck"), konst("y")),
            app(konst("stuck"), konst("y")),
            "reflexive stuck App",
        ),
        // identical Const / BVar TRUE.
        (konst("k"), konst("k"), "identical Const"),
        (bv(2), bv(2), "identical BVar"),
        // FALSE: Sort vs Const.
        (sort0(), konst("k"), "FALSE: Sort vs Const"),
        // FALSE: App heads differ (stuck g x vs stuck h x).
        (
            app(konst("g"), konst("x")),
            app(konst("h"), konst("x")),
            "FALSE: App heads differ",
        ),
        // FALSE: a stuck pair (different constants).
        (konst("a"), konst("b"), "FALSE: Const a vs Const b"),
        // FALSE: BVar i != j.
        (bv(1), bv(2), "FALSE: BVar 1 vs 2"),
        // FALSE: App vs Const (no congruence path).
        (
            app(konst("g"), konst("x")),
            konst("g"),
            "FALSE: App vs Const",
        ),
    ];

    let mut pass = 0usize;
    for (a, b, label) in &cases {
        let native = checker.de_def_eq(a, b);
        let ap: *const MicroExpr = a as *const MicroExpr;
        let bp: *const MicroExpr = b as *const MicroExpr;
        let cp: *const DeChecker = &checker as *const DeChecker;
        let jit = f(cp, ap, bp);
        assert_eq!(
            native, jit,
            "MIR-emitted def_eq JIT disagrees with native on `{label}` (native={native}, jit={jit})"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all def_eq cases must agree native == JIT"
    );
    drop(buffer);
}

