// MODULE: the stage1 `--mir-emit-closure verify_impl` lowering emits EVERY member of
// the call-graph closure of `verify_impl` into ONE module with cross-member `Call`s
// wired to the in-module body `FuncId`s. So the JIT-executed `verify_impl` COMPOSES
// the REAL in-module `def_eq_impl` + `whnf_impl` (+ their callees structural_eq /
// instantiate / subst / lift / env_get / level_eq / succ / imax) — NOT shims — and
// SELF-RECURSES over the (MicroCert, MicroExpr) tree. Only the TRUE leaves remain
// 0-block externs (the context `Vec` len/index/pop/push/deref_mut/reverse, the
// `Box`/`Arc`/`Option` reads, the derived clones / PartialEq impls, `Ord::cmp`,
// `Sub::sub`, `saturating_add`, and the `?`-operator `Try::branch` /
// `FromResidual::from_residual` on `Result<_, MicroError>`), bound below.
//
// We run native `verify_impl` == JIT machine code over (cert, expr) pairs hitting
// EACH core CIC typing rule:
//   - Sort  (-> Sort(succ(l)))
//   - Const (env-covered -> cert ty)
//   - BVar  (context lookup + lift + def_eq -> ty)        [context Vec INDEX + len]
//   - Opaque(def_eq -> ty)
//   - App   (f:Pi, arg matches, result_ty def_eq -> result_ty)   [whnf + def_eq]
//   - Lam   (push arg_ty / verify body / pop -> Pi)        [context Vec push/pop]
//   - Pi    (push / verify body / pop -> Sort(imax))       [context Vec push/pop]
//   - nested Lam(Lam(..)) threading the context DEPTH across binders
//   - Lit / Proj
// plus FAILURE cases: def_eq-mismatch -> Err TypeMismatch; wrong BVar idx -> Err
// InvalidBVar; a Const not in env -> Err Unsupported (discriminant only). We compare
// the Result: Ok -> the returned TYPE MicroExpr structurally; Err -> the discriminant.
//
// REGEN: `trust_ir_mir verify_impl_slice.rs --crate-type=lib --mir-emit-closure
//   verify_impl <out>`. Refresh MIR_VERIFY_IMPL_CLOSURE_TRUST_IR AND the EXT_VI_*
//   symbol constants together (the crate-disambiguator hash is embedded in both).

// ---- the certificate AST + error type (parallel to MicroExpr; same rustc layout) --
#[derive(PartialEq, Clone)]
#[allow(dead_code)]
enum MicroCert {
    Sort {
        level: MicroLevel,
    },
    BVar {
        idx: u32,
        ty: Box<MicroExpr>,
    },
    Opaque {
        ty: Box<MicroExpr>,
    },
    Const {
        name: MeArc<str>,
        ty: Box<MicroExpr>,
    },
    App {
        fn_cert: Box<MicroCert>,
        arg_cert: Box<MicroCert>,
        result_ty: Box<MicroExpr>,
    },
    Lam {
        arg_ty_cert: Box<MicroCert>,
        body_cert: Box<MicroCert>,
        result_ty: Box<MicroExpr>,
    },
    Pi {
        arg_ty_cert: Box<MicroCert>,
        arg_level: MicroLevel,
        body_ty_cert: Box<MicroCert>,
        body_level: MicroLevel,
    },
    Let {
        ty_cert: Box<MicroCert>,
        val_cert: Box<MicroCert>,
        body_cert: Box<MicroCert>,
        result_ty: Box<MicroExpr>,
    },
    Lit {
        lit: MicroLiteral,
        ty: Box<MicroExpr>,
    },
    Proj {
        idx: u32,
        expr_cert: Box<MicroCert>,
        field_ty: Box<MicroExpr>,
    },
}

#[derive(Clone)]
#[allow(dead_code)]
enum MicroError {
    TypeMismatch {
        expected: MicroExpr,
        actual: MicroExpr,
    },
    InvalidBVar(u32),
    ExpectedSort(MicroExpr),
    ExpectedPi(MicroExpr),
    LevelMismatch {
        expected: MicroLevel,
        actual: MicroLevel,
    },
    StructureMismatch,
    Unsupported(MeArc<str>),
}

impl MicroError {
    /// The Result/MicroError discriminant comparison key (the variant index the
    /// niche read decodes / the native enum produces). Used to compare Err arms.
    fn disc(&self) -> u32 {
        match self {
            MicroError::TypeMismatch { .. } => 0,
            MicroError::InvalidBVar(_) => 1,
            MicroError::ExpectedSort(_) => 2,
            MicroError::ExpectedPi(_) => 3,
            MicroError::LevelMismatch { .. } => 4,
            MicroError::StructureMismatch => 5,
            MicroError::Unsupported(_) => 6,
        }
    }
}

impl MicroLevel {
    fn ve_succ(l: MicroLevel) -> MicroLevel {
        MicroLevel::Succ(MeArc::new(l))
    }
    fn ve_imax(a: MicroLevel, b: MicroLevel) -> MicroLevel {
        MicroLevel::IMax(MeArc::new(a), MeArc::new(b))
    }
    fn ve_level_eq(&self, other: &MicroLevel) -> bool {
        self == other
    }
}

// The not-in-env Unsupported leaf (no format!/String) — the Const env-coverage gate.
fn ve_unsupported_const(name: &MeArc<str>) -> MicroError {
    MicroError::Unsupported(name.clone())
}

impl MicroExpr {
    fn ve_lift(&self, cutoff: u32, amount: u32) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                if *idx >= cutoff {
                    MicroExpr::BVar(idx.saturating_add(amount))
                } else {
                    self.clone()
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.ve_lift(cutoff, amount)),
                MeArc::new(a.ve_lift(cutoff, amount)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.ve_lift(cutoff, amount)),
                MeArc::new(body.ve_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.ve_lift(cutoff, amount)),
                MeArc::new(body.ve_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Let(ty, val, body) => MicroExpr::Let(
                MeArc::new(ty.ve_lift(cutoff, amount)),
                MeArc::new(val.ve_lift(cutoff, amount)),
                MeArc::new(body.ve_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.ve_lift(cutoff, amount))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.ve_lift(cutoff, amount))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn ve_subst(&self, depth: u32, val: &MicroExpr) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                use std::cmp::Ordering;
                match idx.cmp(&depth) {
                    Ordering::Equal => val.ve_lift(0, depth),
                    Ordering::Greater => MicroExpr::BVar(idx - 1),
                    Ordering::Less => self.clone(),
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.ve_subst(depth, val)),
                MeArc::new(a.ve_subst(depth, val)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.ve_subst(depth, val)),
                MeArc::new(body.ve_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.ve_subst(depth, val)),
                MeArc::new(body.ve_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Let(ty, v, body) => MicroExpr::Let(
                MeArc::new(ty.ve_subst(depth, val)),
                MeArc::new(v.ve_subst(depth, val)),
                MeArc::new(body.ve_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.ve_subst(depth, val))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.ve_subst(depth, val))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn ve_instantiate(&self, arg: &MicroExpr) -> MicroExpr {
        self.ve_subst(0, arg)
    }
}

/// The verify_impl slice's `MicroChecker`: `context` Vec (offset 0, 24 bytes:
/// {cap,ptr,len}), `env` fat slice (offset 24, 16 bytes), `universe_blind` (offset
/// 40). `#[repr(C)]` pins the layout the MIR-emitted bodies assume.
#[repr(C)]
struct VeChecker<'e> {
    context: Vec<MicroExpr>,
    env: &'e [(MeArc<str>, Option<MicroExpr>)],
    universe_blind: bool,
}

impl<'e> VeChecker<'e> {
    fn ve_env_get(&self, name: &MeArc<str>) -> Option<&MicroExpr> {
        let mut i: usize = 0;
        let n = self.env.len();
        while i < n {
            let entry = &self.env[i];
            if entry.0 == *name {
                return entry.1.as_ref();
            }
            i += 1;
        }
        None
    }
    fn ve_whnf(&self, e: &MicroExpr) -> MicroExpr {
        match e {
            MicroExpr::Const(name) => {
                if ve_is_native_op(name) {
                    return e.clone();
                }
                if let Some(body) = self.ve_env_get(name) {
                    return self.ve_whnf(body);
                }
                e.clone()
            }
            MicroExpr::App(f, a) => {
                let f_whnf = self.ve_whnf(f);
                match &f_whnf {
                    MicroExpr::Lam(_, body) => {
                        let reduced = body.ve_instantiate(a);
                        self.ve_whnf(&reduced)
                    }
                    _ => {
                        let mut head = f_whnf;
                        let mut args: Vec<MicroExpr> = vec![a.as_ref().clone()];
                        while let MicroExpr::App(hf, ha) = &head {
                            args.push(ha.as_ref().clone());
                            head = self.ve_whnf(hf);
                        }
                        args.reverse();
                        if let MicroExpr::Const(name) = &head
                            && !ve_is_native_op(name)
                            && let Some(body) = self.ve_env_get(name)
                        {
                            let mut applied = body.clone();
                            for arg in &args {
                                applied =
                                    MicroExpr::App(MeArc::new(applied), MeArc::new(arg.clone()));
                            }
                            return self.ve_whnf(&applied);
                        }
                        let mut rebuilt = head;
                        for arg in args {
                            rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                        }
                        rebuilt
                    }
                }
            }
            MicroExpr::Let(_, val, body) => {
                let reduced = body.ve_instantiate(val);
                self.ve_whnf(&reduced)
            }
            _ => e.clone(),
        }
    }
    fn ve_structural_eq(&self, a: &MicroExpr, b: &MicroExpr) -> bool {
        match (a, b) {
            (MicroExpr::BVar(i), MicroExpr::BVar(j)) => i == j,
            (MicroExpr::Sort(l1), MicroExpr::Sort(l2)) => self.universe_blind || l1 == l2,
            (MicroExpr::Const(n1), MicroExpr::Const(n2)) => n1 == n2,
            (MicroExpr::App(f1, a1), MicroExpr::App(f2, a2)) => {
                self.ve_structural_eq(f1, f2) && self.ve_structural_eq(a1, a2)
            }
            (MicroExpr::Lam(ty1, b1), MicroExpr::Lam(ty2, b2))
            | (MicroExpr::Pi(ty1, b1), MicroExpr::Pi(ty2, b2)) => {
                self.ve_structural_eq(ty1, ty2) && self.ve_structural_eq(b1, b2)
            }
            (MicroExpr::Let(ty1, v1, b1), MicroExpr::Let(ty2, v2, b2)) => {
                self.ve_structural_eq(ty1, ty2)
                    && self.ve_structural_eq(v1, v2)
                    && self.ve_structural_eq(b1, b2)
            }
            (MicroExpr::Opaque(t1), MicroExpr::Opaque(t2)) => self.ve_structural_eq(t1, t2),
            (MicroExpr::Lit(l1), MicroExpr::Lit(l2)) => l1 == l2,
            (MicroExpr::Proj(i1, e1), MicroExpr::Proj(i2, e2)) => {
                i1 == i2 && self.ve_structural_eq(e1, e2)
            }
            _ => false,
        }
    }
    fn ve_def_eq_impl(&self, a: &MicroExpr, b: &MicroExpr) -> Result<bool, MicroError> {
        let a_whnf = self.ve_whnf(a);
        let b_whnf = self.ve_whnf(b);
        if self.ve_structural_eq(&a_whnf, &b_whnf) {
            return Ok(true);
        }
        if let (MicroExpr::App(f1, a1), MicroExpr::App(f2, a2)) = (&a_whnf, &b_whnf) {
            return Ok(self.ve_def_eq_impl(f1, f2)? && self.ve_def_eq_impl(a1, a2)?);
        }
        if let (MicroExpr::Pi(t1, b1), MicroExpr::Pi(t2, b2))
        | (MicroExpr::Lam(t1, b1), MicroExpr::Lam(t2, b2)) = (&a_whnf, &b_whnf)
        {
            return Ok(self.ve_def_eq_impl(t1, t2)? && self.ve_def_eq_impl(b1, b2)?);
        }
        Ok(false)
    }
    fn ve_whnf_impl(&self, e: &MicroExpr) -> Result<MicroExpr, MicroError> {
        Ok(self.ve_whnf(e))
    }
    // VERBATIM verify_impl native oracle (clean-kernel checker.rs:294-544 core rules).
    fn ve_verify_impl(
        &mut self,
        cert: &MicroCert,
        expr: &MicroExpr,
    ) -> Result<MicroExpr, MicroError> {
        match (cert, expr) {
            (MicroCert::Sort { level }, MicroExpr::Sort(l)) => {
                if !level.ve_level_eq(l) {
                    return Err(MicroError::LevelMismatch {
                        expected: level.clone(),
                        actual: l.clone(),
                    });
                }
                Ok(MicroExpr::Sort(MicroLevel::ve_succ(level.clone())))
            }
            (MicroCert::Const { name, ty }, MicroExpr::Const(n)) => {
                if name != n {
                    return Err(MicroError::StructureMismatch);
                }
                if self.ve_env_get(name).is_none() {
                    return Err(ve_unsupported_const(name));
                }
                Ok(ty.as_ref().clone())
            }
            (MicroCert::BVar { idx, ty }, MicroExpr::BVar(i)) => {
                if *idx != *i {
                    return Err(MicroError::InvalidBVar(*i));
                }
                let depth = self.context.len();
                if (*idx as usize) >= depth {
                    return Err(MicroError::InvalidBVar(*idx));
                }
                let ctx_pos = depth - 1 - *idx as usize;
                let ctx_ty = &self.context[ctx_pos];
                let lifted_ctx_ty = ctx_ty.ve_lift(0, (depth - ctx_pos) as u32);
                if !self.ve_def_eq_impl(ty.as_ref(), &lifted_ctx_ty)? {
                    return Err(MicroError::TypeMismatch {
                        expected: lifted_ctx_ty,
                        actual: ty.as_ref().clone(),
                    });
                }
                Ok(ty.as_ref().clone())
            }
            (MicroCert::Opaque { ty }, MicroExpr::Opaque(t)) => {
                if !self.ve_def_eq_impl(ty.as_ref(), t.as_ref())? {
                    return Err(MicroError::TypeMismatch {
                        expected: ty.as_ref().clone(),
                        actual: t.as_ref().clone(),
                    });
                }
                Ok(ty.as_ref().clone())
            }
            (
                MicroCert::App {
                    fn_cert,
                    arg_cert,
                    result_ty,
                },
                MicroExpr::App(f, a),
            ) => {
                let fn_ty = self.ve_verify_impl(fn_cert, f)?;
                let fn_ty_whnf = self.ve_whnf_impl(&fn_ty)?;
                let (expected_arg_ty, body_ty) = match &fn_ty_whnf {
                    MicroExpr::Pi(arg_ty, body) => (arg_ty.as_ref(), body.as_ref()),
                    _ => return Err(MicroError::ExpectedPi(fn_ty_whnf)),
                };
                let arg_ty = self.ve_verify_impl(arg_cert, a)?;
                if !self.ve_def_eq_impl(&arg_ty, expected_arg_ty)? {
                    return Err(MicroError::TypeMismatch {
                        expected: expected_arg_ty.clone(),
                        actual: arg_ty,
                    });
                }
                let expected_result = body_ty.ve_instantiate(a);
                if !self.ve_def_eq_impl(result_ty.as_ref(), &expected_result)? {
                    return Err(MicroError::TypeMismatch {
                        expected: expected_result,
                        actual: result_ty.as_ref().clone(),
                    });
                }
                Ok(result_ty.as_ref().clone())
            }
            (
                MicroCert::Lam {
                    arg_ty_cert,
                    body_cert,
                    result_ty,
                },
                MicroExpr::Lam(arg_ty, body),
            ) => {
                let arg_sort = self.ve_verify_impl(arg_ty_cert, arg_ty)?;
                let arg_sort_whnf = self.ve_whnf_impl(&arg_sort)?;
                if !matches!(arg_sort_whnf, MicroExpr::Sort(_)) {
                    return Err(MicroError::ExpectedSort(arg_sort_whnf));
                }
                self.context.push(arg_ty.as_ref().clone());
                let body_ty = self.ve_verify_impl(body_cert, body);
                self.context.pop();
                let body_ty = body_ty?;
                let expected_pi = MicroExpr::Pi(arg_ty.clone(), MeArc::new(body_ty));
                if !self.ve_def_eq_impl(result_ty.as_ref(), &expected_pi)? {
                    return Err(MicroError::TypeMismatch {
                        expected: expected_pi,
                        actual: result_ty.as_ref().clone(),
                    });
                }
                Ok(result_ty.as_ref().clone())
            }
            (
                MicroCert::Pi {
                    arg_ty_cert,
                    arg_level,
                    body_ty_cert,
                    body_level,
                },
                MicroExpr::Pi(arg_ty, body_ty),
            ) => {
                let arg_sort = self.ve_verify_impl(arg_ty_cert, arg_ty)?;
                let l1 = match self.ve_whnf_impl(&arg_sort)? {
                    MicroExpr::Sort(l) => l,
                    other => return Err(MicroError::ExpectedSort(other)),
                };
                if !self.universe_blind && !l1.ve_level_eq(arg_level) {
                    return Err(MicroError::LevelMismatch {
                        expected: arg_level.clone(),
                        actual: l1,
                    });
                }
                self.context.push(arg_ty.as_ref().clone());
                let body_sort = self.ve_verify_impl(body_ty_cert, body_ty);
                self.context.pop();
                let body_sort = body_sort?;
                let l2 = match self.ve_whnf_impl(&body_sort)? {
                    MicroExpr::Sort(l) => l,
                    other => return Err(MicroError::ExpectedSort(other)),
                };
                if !self.universe_blind && !l2.ve_level_eq(body_level) {
                    return Err(MicroError::LevelMismatch {
                        expected: body_level.clone(),
                        actual: l2,
                    });
                }
                Ok(MicroExpr::Sort(MicroLevel::ve_imax(
                    arg_level.clone(),
                    body_level.clone(),
                )))
            }
            (
                MicroCert::Let {
                    ty_cert,
                    val_cert,
                    body_cert,
                    result_ty,
                },
                MicroExpr::Let(ty, val, body),
            ) => {
                let ty_sort = self.ve_verify_impl(ty_cert, ty)?;
                let ty_sort_whnf = self.ve_whnf_impl(&ty_sort)?;
                if !matches!(ty_sort_whnf, MicroExpr::Sort(_)) {
                    return Err(MicroError::ExpectedSort(ty_sort_whnf));
                }
                let val_ty = self.ve_verify_impl(val_cert, val)?;
                if !self.ve_def_eq_impl(&val_ty, ty)? {
                    return Err(MicroError::TypeMismatch {
                        expected: ty.as_ref().clone(),
                        actual: val_ty,
                    });
                }
                self.context.push(ty.as_ref().clone());
                let body_ty = self.ve_verify_impl(body_cert, body);
                self.context.pop();
                let body_ty = body_ty?;
                let expected_result = body_ty.ve_instantiate(val);
                if !self.ve_def_eq_impl(result_ty.as_ref(), &expected_result)? {
                    return Err(MicroError::TypeMismatch {
                        expected: expected_result,
                        actual: result_ty.as_ref().clone(),
                    });
                }
                Ok(result_ty.as_ref().clone())
            }
            (MicroCert::Lit { lit, ty }, MicroExpr::Lit(l)) => {
                if lit != l {
                    return Err(MicroError::StructureMismatch);
                }
                Ok(ty.as_ref().clone())
            }
            (
                MicroCert::Proj {
                    idx,
                    expr_cert,
                    field_ty,
                },
                MicroExpr::Proj(i, e),
            ) => {
                if *idx != *i {
                    return Err(MicroError::StructureMismatch);
                }
                let _expr_ty = self.ve_verify_impl(expr_cert, e)?;
                Ok(field_ty.as_ref().clone())
            }
            _ => Err(MicroError::StructureMismatch),
        }
    }
}

fn ve_is_native_op(_name: &MeArc<str>) -> bool {
    false
}

// ---- the verify_impl closure's leaf shims (the JIT analog of linked symbols) ----
// The context-Vec / Arc / Box / Option / clone / PartialEq / Ord / Sub / saturating
// leaves reuse the def_eq/whnf shim ABIs; the NEW leaves are the context `Vec`
// len/index/pop and the `?`-operator `Try::branch` / `FromResidual::from_residual`
// over `Result<MicroExpr|bool, MicroError>` (which round-trip through the SAME std
// `ControlFlow`/`Result`/`Infallible` layouts the JIT reads — same rustc family).

use std::convert::Infallible;
use std::ops::ControlFlow;

// --- context Vec<MicroExpr> ops (cap@0, ptr@8, len@16) ---
/// `Vec::<MicroExpr>::len(&self) -> usize`.
extern "C" fn ve_shim_vec_len(vec: *const Vec<MicroExpr>) -> u64 {
    unsafe { (*vec).len() as u64 }
}
/// `<Vec<MicroExpr> as Index<usize>>::index(&self, i) -> &MicroExpr`.
extern "C" fn ve_shim_vec_index(vec: *const Vec<MicroExpr>, idx: u64) -> *const MicroExpr {
    // Address the element via the slice's data pointer (avoids an implicit autoref of
    // a raw-pointer deref). Bounds-checked like `Index`.
    unsafe {
        let s: &[MicroExpr] = (*vec).as_slice();
        assert!((idx as usize) < s.len(), "vec_index out of bounds");
        s.as_ptr().add(idx as usize)
    }
}
/// `Vec::<MicroExpr>::pop(&mut self) -> Option<MicroExpr>` (sret 32-byte niche-Option,
/// disc i32 @0 == Some(0..9)/None==16-ish; the verify_impl body DISCARDS the pop
/// result, so only the side effect — len-- + drop the last elt — matters).
extern "C" fn ve_shim_vec_pop(sret: *mut Option<MicroExpr>, vec: *mut Vec<MicroExpr>) {
    unsafe {
        let v = (*vec).pop();
        std::ptr::write(sret, v);
    }
}
/// `Vec::<MicroExpr>::push(&mut self, value)` (value by-ref handoff).
extern "C" fn ve_shim_vec_push(vec: *mut Vec<MicroExpr>, value: *const MicroExpr) {
    unsafe {
        let v = std::ptr::read(value);
        (*vec).push(v);
    }
}
/// `<Vec<MicroExpr> as DerefMut>::deref_mut(&mut self) -> &mut [MicroExpr]` (sret 2-word).
extern "C" fn ve_shim_vec_deref_mut(sret: *mut (*mut MicroExpr, usize), vec: *mut Vec<MicroExpr>) {
    unsafe {
        let s: &mut [MicroExpr] = (*vec).as_mut_slice();
        std::ptr::write(sret, (s.as_mut_ptr(), s.len()));
    }
}
/// `<[MicroExpr]>::reverse(&mut self)` (fat slice by-ref).
extern "C" fn ve_shim_reverse(slice_ref: *const (*mut MicroExpr, usize)) {
    unsafe {
        let (ptr, len) = *slice_ref;
        let s: &mut [MicroExpr] = std::slice::from_raw_parts_mut(ptr, len);
        s.reverse();
    }
}

// --- Arc / Box / Option reads ---
/// `<Arc<MicroExpr> as AsRef<MicroExpr>>::as_ref(&self) -> &MicroExpr` (ArcInner data +16).
extern "C" fn ve_shim_arc_as_ref(arc_ref: *const *const u8) -> *const MicroExpr {
    unsafe { (*arc_ref).add(16) as *const MicroExpr }
}
/// `<Box<MicroExpr> as AsRef<MicroExpr>>::as_ref(&self) -> &MicroExpr` (Box is a thin
/// pointer — the boxed `MicroExpr` is at the pointee, offset 0).
extern "C" fn ve_shim_box_as_ref(box_ref: *const *const MicroExpr) -> *const MicroExpr {
    unsafe { *box_ref }
}
/// `Option::<MicroExpr>::as_ref(&self) -> Option<&MicroExpr>` (sret 8-byte niche).
extern "C" fn ve_shim_opt_as_ref(
    sret: *mut Option<std::ptr::NonNull<MicroExpr>>,
    this: *const Option<MicroExpr>,
) {
    unsafe {
        let r: Option<std::ptr::NonNull<MicroExpr>> = (*this).as_ref().map(std::ptr::NonNull::from);
        std::ptr::write(sret, r);
    }
}
/// Register-return `Option::<MicroExpr>::as_ref(&self) -> Option<&MicroExpr>` — the
/// pinned-1.97 ABI: `Option<&MicroExpr>` is a pointer-sized null-niche value, so the
/// current frontend emits `(this) -> ptr` (null == None) rather than the frozen
/// fixture's `(sret, this) -> ()`.
extern "C" fn ve_shim_opt_as_ref_reg(this: *const Option<MicroExpr>) -> *const MicroExpr {
    unsafe {
        match (*this).as_ref() {
            Some(r) => r as *const MicroExpr,
            None => std::ptr::null(),
        }
    }
}
/// `Option::<&MicroExpr>::is_none(&self) -> bool` — the Const env-coverage gate. The
/// receiver is `&Option<&MicroExpr>` (an 8-byte niche; null == None).
extern "C" fn ve_shim_opt_is_none(this: *const *const MicroExpr) -> bool {
    unsafe { (*this).is_null() }
}

// --- clones ---
// These shims must perform real `Arc::clone` operations.  A bitwise copy appears
// to work while the JIT call is executing, but the returned Rust value is dropped
// by this harness.  Without the strong-count increment that drop can free storage
// still owned by the oracle inputs, poisoning subsequent JIT tests.
/// `<Arc<str> as Clone>::clone(sret, &self)` — fat pointer (data + len = 16 bytes).
extern "C" fn ve_shim_arcstr_clone(sret: *mut MeArc<str>, this: *const MeArc<str>) {
    unsafe { std::ptr::write(sret, MeArc::clone(&*this)) }
}
/// `<Arc<MicroExpr> as Clone>::clone(sret, &self)`.
extern "C" fn ve_shim_arcexpr_clone(sret: *mut MeArc<MicroExpr>, this: *const MeArc<MicroExpr>) {
    unsafe { std::ptr::write(sret, MeArc::clone(&*this)) }
}
/// `<Arc<MicroLevel> as Clone>::clone(sret, &self)`.
extern "C" fn ve_shim_arclevel_clone(sret: *mut MeArc<MicroLevel>, this: *const MeArc<MicroLevel>) {
    unsafe { std::ptr::write(sret, MeArc::clone(&*this)) }
}
// --- register-return clone shims (the pinned-1.97 ABI: the current frontend emits
// pointer-sized `Arc<T>::clone` as `(this) -> ptr` rather than the frozen fixture's
// `(sret, this) -> ()`). The returned raw pointer is the Arc value = ArcInner base =
// data_ptr - 16 on this std. Selected by exact fixture identity below. ---
/// `<Arc<MicroExpr> as Clone>::clone(&self) -> Arc<MicroExpr>` (register-return).
extern "C" fn ve_shim_arcexpr_clone_reg(this: *const MeArc<MicroExpr>) -> *const u8 {
    unsafe {
        let d = MeArc::into_raw(MeArc::clone(&*this)) as *const u8;
        d.sub(16)
    }
}
/// `<Arc<MicroLevel> as Clone>::clone(&self) -> Arc<MicroLevel>` (register-return).
extern "C" fn ve_shim_arclevel_clone_reg(this: *const MeArc<MicroLevel>) -> *const u8 {
    unsafe {
        let d = MeArc::into_raw(MeArc::clone(&*this)) as *const u8;
        d.sub(16)
    }
}

// --- PartialEq leaves (double-ref for the `&T` blanket impls; single for Arc<str>) ---
/// `<&u32 as PartialEq>::eq(&&u32, &&u32)` — BVar/Proj idx (double ref).
extern "C" fn ve_shim_u32_eq(a: *const *const u32, b: *const *const u32) -> bool {
    unsafe { **a == **b }
}
/// `<&MicroLiteral as PartialEq>::eq` (double ref).
extern "C" fn ve_shim_lit_eq(a: *const *const MicroLiteral, b: *const *const MicroLiteral) -> bool {
    unsafe { **a == **b }
}
/// `<&MicroLiteral as PartialEq>::ne` (double ref) — the Lit-rule `lit != l`.
extern "C" fn ve_shim_lit_ne(a: *const *const MicroLiteral, b: *const *const MicroLiteral) -> bool {
    unsafe { **a != **b }
}
/// `<&Arc<str> as PartialEq>::eq` — Const arm (double ref).
extern "C" fn ve_shim_const_eq(a: *const *const MeArc<str>, b: *const *const MeArc<str>) -> bool {
    unsafe { **a == **b }
}
/// `<&Arc<str> as PartialEq>::ne` — the Const-rule `name != n` (double ref).
extern "C" fn ve_shim_const_ne(a: *const *const MeArc<str>, b: *const *const MeArc<str>) -> bool {
    unsafe { **a != **b }
}
/// `<&MicroLevel as PartialEq>::eq` — Sort arm + level_eq (double ref).
extern "C" fn ve_shim_level_eq(a: *const *const MicroLevel, b: *const *const MicroLevel) -> bool {
    unsafe { **a == **b }
}
/// `<Arc<str> as PartialEq>::eq(&self, &other)` — env_get name compare (single ref).
extern "C" fn ve_shim_name_eq(a: *const MeArc<str>, b: *const MeArc<str>) -> bool {
    unsafe { *a == *b }
}

// --- subst/lift arithmetic leaves ---
/// `<u32 as Ord>::cmp(sret Ordering, &a, &b)` (Ordering is i8 {Less=-1,Equal=0,Greater=1}).
extern "C" fn ve_shim_ord_cmp(sret: *mut i8, a: *const u32, b: *const u32) {
    unsafe {
        let o = (*a).cmp(&*b);
        std::ptr::write(sret, o as i8);
    }
}
/// `<&u32 as Sub<u32>>::sub(&u32, u32) -> u32` — subst `idx - 1`.
extern "C" fn ve_shim_sub(a: *const u32, b: u32) -> u32 {
    unsafe { *a - b }
}
/// `u32::saturating_add(u32, u32) -> u32` — lift idx + amount.
extern "C" fn ve_shim_sat_add(a: u32, b: u32) -> u32 {
    a.saturating_add(b)
}

// --- the `?`-operator try-trait leaves (the load-bearing NEW shims) ---
// `?` on `Result<C, MicroError>` desugars to `Try::branch` then (on the Break path)
// `FromResidual::from_residual`. We replicate the std impls EXACTLY, round-tripping
// through the real `ControlFlow<Result<Infallible, MicroError>, C>` / `Result<C,
// MicroError>` layouts the JIT-emitted code reads (same-rustc layout, the M6 niche
// cross-check principle). `branch`: Ok(c)->Continue(c), Err(e)->Break(Err(e)).
// `from_residual`: the residual is always `Err(e)` -> `Result::Err(e)`.

/// `<Result<MicroExpr, MicroError> as Try>::branch(self) -> ControlFlow<Result<Infallible, MicroError>, MicroExpr>`.
extern "C" fn ve_shim_branch_expr(
    sret: *mut ControlFlow<Result<Infallible, MicroError>, MicroExpr>,
    arg: *const Result<MicroExpr, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(arg);
        let cf = match r {
            Ok(v) => ControlFlow::Continue(v),
            Err(e) => ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
/// `<Result<bool, MicroError> as Try>::branch(self) -> ControlFlow<Result<Infallible, MicroError>, bool>`.
extern "C" fn ve_shim_branch_bool(
    sret: *mut ControlFlow<Result<Infallible, MicroError>, bool>,
    arg: *const Result<bool, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(arg);
        let cf = match r {
            Ok(v) => ControlFlow::Continue(v),
            Err(e) => ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
/// `<Result<MicroExpr, MicroError> as FromResidual<Result<Infallible, MicroError>>>::from_residual(r) -> Result<MicroExpr, MicroError>`.
extern "C" fn ve_shim_from_residual_expr(
    sret: *mut Result<MicroExpr, MicroError>,
    residual: *const Result<Infallible, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(residual);
        let out: Result<MicroExpr, MicroError> = match r {
            Err(e) => Err(e),
            Ok(_inf) => unreachable!("Infallible Ok in a residual"),
        };
        std::ptr::write(sret, out);
    }
}
/// `<Result<bool, MicroError> as FromResidual<Result<Infallible, MicroError>>>::from_residual(r) -> Result<bool, MicroError>`.
extern "C" fn ve_shim_from_residual_bool(
    sret: *mut Result<bool, MicroError>,
    residual: *const Result<Infallible, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(residual);
        let out: Result<bool, MicroError> = match r {
            Err(e) => Err(e),
            Ok(_inf) => unreachable!("Infallible Ok in a residual"),
        };
        std::ptr::write(sret, out);
    }
}

/// `(*mut Result<MicroExpr,MicroError>, *mut VeChecker, *const MicroCert, *const MicroExpr)`
