/// END-TO-END MIR-PATH CAPSTONE: the JIT-EXECUTED verified `verify_impl` — the
/// certificate TYPE-CHECKER, composing the REAL in-module `def_eq_impl` + `whnf_impl`
/// (both verified pillars) and SELF-RECURSING over (MicroCert, MicroExpr) with a
/// threaded context `Vec`. native `verify_impl` == JIT machine code over each CIC
/// typing rule + the failure arms.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_verify_impl_capstone_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_verify_impl_capstone_roundtrip");
    let module = emitted_fixture::parse_emitted(VERIFY_IMPL_TIR)
        .expect("MIR-emitted verify_impl closure trust-ir text must parse");

    // CONFIRM the call graph is genuinely IN-MODULE: verify_impl composes the REAL
    // def_eq_impl + whnf_impl + their callees (not extern shims), and self-recurses.
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("MicroChecker____e___verify_impl"),
        "verify_impl must be in-module"
    );
    assert!(
        bodied("MicroChecker____e___def_eq_impl"),
        "def_eq_impl must be IN-MODULE (not a shim)"
    );
    assert!(
        bodied("MicroChecker____e___whnf_impl"),
        "whnf_impl must be IN-MODULE (not a shim)"
    );
    assert!(bodied("MicroChecker____e___whnf"), "whnf must be IN-MODULE");
    assert!(
        bodied("MicroChecker____e___structural_eq"),
        "structural_eq must be IN-MODULE"
    );
    assert!(
        bodied("MicroChecker____e___env_get"),
        "env_get must be IN-MODULE"
    );
    assert!(
        bodied("MicroExpr__instantiate"),
        "instantiate must be IN-MODULE"
    );
    assert!(bodied("MicroExpr__subst"), "subst must be IN-MODULE");
    assert!(bodied("MicroExpr__lift"), "lift must be IN-MODULE");

    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_VI_REVERSE.to_string(), ve_shim_reverse as *const u8);
    // `Option::<MicroExpr>::as_ref` returns the pointer-sized `Option<&MicroExpr>`,
    // which flips sret -> register-return in the trust re-emit. Selected by the gate.
    #[cfg(kernel_fixture_layout_matches)]
    let opt_as_ref_p = ve_shim_opt_as_ref as *const u8;
    #[cfg(not(kernel_fixture_layout_matches))]
    let opt_as_ref_p = ve_shim_opt_as_ref_reg as *const u8;
    externs.insert(EXT_VI_OPT_AS_REF.to_string(), opt_as_ref_p);
    externs.insert(
        EXT_VI_OPT_IS_NONE.to_string(),
        ve_shim_opt_is_none as *const u8,
    );
    externs.insert(EXT_VI_VEC_LEN.to_string(), ve_shim_vec_len as *const u8);
    externs.insert(EXT_VI_VEC_POP.to_string(), ve_shim_vec_pop as *const u8);
    externs.insert(EXT_VI_SAT_ADD.to_string(), ve_shim_sat_add as *const u8);
    externs.insert(EXT_VI_VEC_PUSH.to_string(), ve_shim_vec_push as *const u8);
    externs.insert(EXT_VI_ORD_CMP.to_string(), ve_shim_ord_cmp as *const u8);
    externs.insert(
        EXT_VI_ARC_AS_REF.to_string(),
        ve_shim_arc_as_ref as *const u8,
    );
    externs.insert(EXT_VI_SUB.to_string(), ve_shim_sub as *const u8);
    externs.insert(
        EXT_VI_ARCSTR_EQ_R.to_string(),
        ve_shim_const_eq as *const u8,
    );
    externs.insert(
        EXT_VI_ARCSTR_NE_R.to_string(),
        ve_shim_const_ne as *const u8,
    );
    externs.insert(EXT_VI_U32_EQ.to_string(), ve_shim_u32_eq as *const u8);
    externs.insert(EXT_VI_LEVEL_EQ.to_string(), ve_shim_level_eq as *const u8);
    externs.insert(EXT_VI_LIT_EQ.to_string(), ve_shim_lit_eq as *const u8);
    externs.insert(EXT_VI_LIT_NE.to_string(), ve_shim_lit_ne as *const u8);
    externs.insert(
        EXT_VI_VEC_DEREF_MUT.to_string(),
        ve_shim_vec_deref_mut as *const u8,
    );
    externs.insert(EXT_VI_VEC_INDEX.to_string(), ve_shim_vec_index as *const u8);
    externs.insert(
        EXT_VI_BOX_AS_REF.to_string(),
        ve_shim_box_as_ref as *const u8,
    );
    externs.insert(
        EXT_VI_BRANCH_BOOL.to_string(),
        ve_shim_branch_bool as *const u8,
    );
    externs.insert(
        EXT_VI_BRANCH_EXPR.to_string(),
        ve_shim_branch_expr as *const u8,
    );
    externs.insert(
        EXT_VI_FROMRES_BOOL.to_string(),
        ve_shim_from_residual_bool as *const u8,
    );
    externs.insert(
        EXT_VI_FROMRES_EXPR.to_string(),
        ve_shim_from_residual_expr as *const u8,
    );
    externs.insert(EXT_VI_NAME_EQ.to_string(), ve_shim_name_eq as *const u8);
    externs.insert(
        EXT_VI_ARCSTR_CLONE.to_string(),
        ve_shim_arcstr_clone as *const u8,
    );
    // The two pointer-sized `Arc<T>::clone` leaves flip sret -> register-return in the
    // re-emitted trust fixture (bind the `_reg` shims); the stable frozen fixture keeps
    // the shared sret shims. Selected by exact fixture identity.
    #[cfg(kernel_fixture_layout_matches)]
    let (arcexpr_clone_p, arclevel_clone_p) = (
        ve_shim_arcexpr_clone as *const u8,
        ve_shim_arclevel_clone as *const u8,
    );
    #[cfg(not(kernel_fixture_layout_matches))]
    let (arcexpr_clone_p, arclevel_clone_p) = (
        ve_shim_arcexpr_clone_reg as *const u8,
        ve_shim_arclevel_clone_reg as *const u8,
    );
    externs.insert(EXT_VI_ARCLEVEL_CLONE.to_string(), arclevel_clone_p);
    externs.insert(EXT_VI_ARCEXPR_CLONE.to_string(), arcexpr_clone_p);
    externs.insert("__rust_alloc".to_string(), rust_alloc_shim as *const u8);
    // The `Result<MicroExpr, MicroError>` `?`-op from_residual leaf carries a v0
    // BACKREF (`B1s_` in the trust re-emit vs `B1t_` in the frozen fixture) that
    // norm_extern copies verbatim, so the two mangled forms do not normalize equal.
    // Bind the pinned-1.97 form explicitly (harmless/unused on exact 1.95).
    externs.insert("_RNvXsq_NtCs6aeJlRfwW9l_4core6resultINtB5_6ResultNtCsGNRRxFUq6L_17verify_impl_slice9MicroExprNtBM_10MicroErrorEINtNtNtB7_3ops9try_trait12FromResidualIBy_NtNtB7_7convert10InfallibleB1s_EE13from_residualBM_".to_string(), ve_shim_from_residual_expr as *const u8);

    let externs = resolve_externs(&module, &externs);
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted verify_impl closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("MicroChecker____e___verify_impl")
        .expect("JIT symbol `MicroChecker____e___verify_impl` not found")
        .as_ptr();
    let f: VerifyImplFn = unsafe { std::mem::transmute(raw) };

    // Builders.
    let bv = |i: u32| MicroExpr::BVar(i);
    let sort0 = || MicroExpr::Sort(MicroLevel::Zero);
    let sort1 = || MicroExpr::Sort(MicroLevel::Succ(MeArc::new(MicroLevel::Zero)));
    let app = |x: MicroExpr, y: MicroExpr| MicroExpr::App(MeArc::new(x), MeArc::new(y));
    let lam = |t: MicroExpr, b: MicroExpr| MicroExpr::Lam(MeArc::new(t), MeArc::new(b));
    let pi = |t: MicroExpr, b: MicroExpr| MicroExpr::Pi(MeArc::new(t), MeArc::new(b));
    let konst = |s: &str| MicroExpr::Const(MeArc::from(s));
    let lvl0 = || MicroLevel::Zero;

    // env: `c := Sort0` (a reducible const used by the App/def_eq cases), `nat` opaque.
    let env: Vec<(MeArc<str>, Option<MicroExpr>)> = vec![
        (MeArc::from("c"), Some(sort0())),
        (MeArc::from("nat"), None),
    ];

    // Each case: a (cert, expr) pair + a label. We build a FRESH VeChecker per case
    // (the context Vec must start empty; the Lam/Pi rules push/pop across it). We run
    // the native oracle and the JIT over the SAME inputs, comparing the Result.
    enum Expect {
        OkTy(MicroExpr),
        ErrDisc(u32),
    }
    use Expect::*;

    // --- Sort: Sort(0) : Sort(succ 0) = Sort1 ---
    // --- nested Lam(Lam(BVar)) to thread context depth across binders ---
    // Inner body BVar(0) : sort0 (the inner binder's type); cert result types are the
    // Pi shapes. Outer: λ(x:Sort0). λ(y:Sort0). y  :  Pi(Sort0, Pi(Sort0, Sort0)).
    let inner_lam_expr = lam(sort0(), bv(0));
    let inner_lam_cert = MicroCert::Lam {
        arg_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
        body_cert: Box::new(MicroCert::BVar {
            idx: 0,
            ty: Box::new(sort0()),
        }),
        result_ty: Box::new(pi(sort0(), sort0())),
    };
    let outer_lam_expr = lam(sort0(), inner_lam_expr.clone());
    let outer_lam_cert = MicroCert::Lam {
        arg_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
        body_cert: Box::new(inner_lam_cert.clone()),
        result_ty: Box::new(pi(sort0(), pi(sort0(), sort0()))),
    };

    let cases: Vec<(MicroCert, MicroExpr, Expect, &str)> = vec![
        // Sort rule.
        (
            MicroCert::Sort { level: lvl0() },
            sort0(),
            OkTy(sort1()),
            "Sort: Sort0 : Sort(succ 0)",
        ),
        // Const rule (env-covered -> cert ty).
        (
            MicroCert::Const {
                name: MeArc::from("c"),
                ty: Box::new(sort1()),
            },
            konst("c"),
            OkTy(sort1()),
            "Const: c (env-covered) : carried ty",
        ),
        // Const FAILURE: not in env -> Unsupported (disc 6).
        (
            MicroCert::Const {
                name: MeArc::from("zzz"),
                ty: Box::new(sort1()),
            },
            konst("zzz"),
            ErrDisc(6),
            "Const FAIL: zzz not in env -> Unsupported",
        ),
        // Const FAILURE: name mismatch -> StructureMismatch (disc 5).
        (
            MicroCert::Const {
                name: MeArc::from("c"),
                ty: Box::new(sort1()),
            },
            konst("d"),
            ErrDisc(5),
            "Const FAIL: cert/expr name mismatch -> StructureMismatch",
        ),
        // BVar rule (single binder via a Lam wrapper would be needed for context;
        // here exercise it through the nested-Lam case below). A bare BVar with empty
        // context -> InvalidBVar (disc 1).
        (
            MicroCert::BVar {
                idx: 0,
                ty: Box::new(sort0()),
            },
            bv(0),
            ErrDisc(1),
            "BVar FAIL: idx 0 in empty context -> InvalidBVar",
        ),
        // BVar FAILURE: cert idx != expr idx -> InvalidBVar (disc 1).
        (
            MicroCert::BVar {
                idx: 0,
                ty: Box::new(sort0()),
            },
            bv(1),
            ErrDisc(1),
            "BVar FAIL: cert/expr idx mismatch -> InvalidBVar",
        ),
        // Opaque rule (def_eq self -> ty).
        (
            MicroCert::Opaque {
                ty: Box::new(sort0()),
            },
            MicroExpr::Opaque(MeArc::new(sort0())),
            OkTy(sort0()),
            "Opaque: def_eq(ty,ty) -> ty",
        ),
        // Opaque FAILURE: cert ty != expr ty -> TypeMismatch (disc 0). Use genuinely
        // distinct HEADS (Sort0 vs Const "nat"), since under `universe_blind` two
        // Sorts of different levels are def-equal (Sort arm: `universe_blind || ..`).
        (
            MicroCert::Opaque {
                ty: Box::new(sort0()),
            },
            MicroExpr::Opaque(MeArc::new(konst("nat"))),
            ErrDisc(0),
            "Opaque FAIL: ty mismatch (Sort vs Const) -> TypeMismatch",
        ),
        // Pi rule: (x:Sort0) -> Sort0  :  Sort(imax 0 0). Universe-blind (env), so the
        // level checks are skipped; body verified under the pushed context.
        (
            MicroCert::Pi {
                arg_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                arg_level: lvl0(),
                body_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                body_level: lvl0(),
            },
            pi(sort0(), sort0()),
            OkTy(MicroExpr::Sort(MicroLevel::IMax(
                MeArc::new(lvl0()),
                MeArc::new(lvl0()),
            ))),
            "Pi: (Sort0)->Sort0 : Sort(imax 0 0)  [context push/pop]",
        ),
        // Lam rule: λ(x:Sort0). Sort0  :  Pi(Sort0, Sort0). The body Sort0 verified
        // under the pushed context; result_ty def_eq the synthesized Pi.
        (
            MicroCert::Lam {
                arg_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                body_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                result_ty: Box::new(pi(sort0(), sort1())),
            },
            lam(sort0(), sort0()),
            OkTy(pi(sort0(), sort1())),
            "Lam: λ(Sort0).Sort0 : Pi(Sort0,Sort1)  [context push/pop]",
        ),
        // Nested Lam(Lam(BVar)): threads the context to DEPTH 2; the inner BVar(0)
        // looks up the inner binder's type (Sort0) at ctx_pos = depth-1-idx.
        (
            outer_lam_cert.clone(),
            outer_lam_expr.clone(),
            OkTy(pi(sort0(), pi(sort0(), sort0()))),
            "Lam(Lam(BVar)): nested binders thread context depth=2",
        ),
        // App rule: (λ(x:Sort0). x) applied to `c`. fn_ty = Pi(Sort0,Sort0) (via the
        // Lam sub-cert); arg `c` : Sort0; result_ty = Sort0 (= body[c]). f:Pi, arg
        // matches, result_ty def_eq -> result_ty. Composes whnf + def_eq.
        (
            MicroCert::App {
                fn_cert: Box::new(MicroCert::Lam {
                    arg_ty_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                    body_cert: Box::new(MicroCert::BVar {
                        idx: 0,
                        ty: Box::new(sort0()),
                    }),
                    result_ty: Box::new(pi(sort0(), sort0())),
                }),
                arg_cert: Box::new(MicroCert::Const {
                    name: MeArc::from("c"),
                    ty: Box::new(sort0()),
                }),
                result_ty: Box::new(sort0()),
            },
            app(lam(sort0(), bv(0)), konst("c")),
            OkTy(sort0()),
            "App: (λ.0) c : Sort0  [whnf Pi + def_eq arg/result]",
        ),
        // App FAILURE: function type not a Pi (apply a Sort) -> ExpectedPi (disc 3).
        (
            MicroCert::App {
                fn_cert: Box::new(MicroCert::Sort { level: lvl0() }),
                arg_cert: Box::new(MicroCert::Const {
                    name: MeArc::from("c"),
                    ty: Box::new(sort0()),
                }),
                result_ty: Box::new(sort0()),
            },
            app(sort0(), konst("c")),
            ErrDisc(3),
            "App FAIL: fn not Pi -> ExpectedPi",
        ),
        // Lit rule: Lit(Nat 7) : nat (carried). lit == l -> ty.
        (
            MicroCert::Lit {
                lit: MicroLiteral::Nat(7),
                ty: Box::new(konst("nat")),
            },
            MicroExpr::Lit(MicroLiteral::Nat(7)),
            OkTy(konst("nat")),
            "Lit: Lit(7) : nat",
        ),
        // Lit FAILURE: lit != l -> StructureMismatch (disc 5).
        (
            MicroCert::Lit {
                lit: MicroLiteral::Nat(7),
                ty: Box::new(konst("nat")),
            },
            MicroExpr::Lit(MicroLiteral::Nat(8)),
            ErrDisc(5),
            "Lit FAIL: lit mismatch -> StructureMismatch",
        ),
        // Proj rule: proj(0, Opaque(Sort0)) : field_ty (carried). idx == i, sub-cert
        // verifies -> field_ty.
        (
            MicroCert::Proj {
                idx: 0,
                expr_cert: Box::new(MicroCert::Opaque {
                    ty: Box::new(sort0()),
                }),
                field_ty: Box::new(konst("nat")),
            },
            MicroExpr::Proj(0, MeArc::new(MicroExpr::Opaque(MeArc::new(sort0())))),
            OkTy(konst("nat")),
            "Proj: proj(0, Opaque) : field_ty",
        ),
        // Structure mismatch: cert/expr shapes disagree (Sort cert vs Const expr).
        (
            MicroCert::Sort { level: lvl0() },
            konst("c"),
            ErrDisc(5),
            "shape mismatch: Sort cert vs Const expr -> StructureMismatch",
        ),
    ];

    let mut pass = 0usize;
    for (cert, expr, expect, label) in &cases {
        // Native oracle (fresh empty context).
        let mut native_chk = VeChecker {
            context: Vec::new(),
            env: &env,
            universe_blind: true,
        };
        let native = native_chk.ve_verify_impl(cert, expr);

        // JIT (fresh empty context). The ABI is (sret, &mut self, &cert, &expr).
        let mut jit_chk = VeChecker {
            context: Vec::new(),
            env: &env,
            universe_blind: true,
        };
        let mut out: std::mem::MaybeUninit<Result<MicroExpr, MicroError>> =
            std::mem::MaybeUninit::uninit();
        f(
            out.as_mut_ptr(),
            &mut jit_chk as *mut VeChecker,
            cert as *const MicroCert,
            expr as *const MicroExpr,
        );
        let jit = unsafe { out.assume_init() };

        // Compare native vs JIT first (the core oracle), THEN both vs Expect.
        match (&native, &jit) {
            (Ok(nt), Ok(jt)) => {
                let cmp = VeChecker {
                    context: Vec::new(),
                    env: &env,
                    universe_blind: true,
                };
                assert!(
                    cmp.ve_structural_eq(nt, jt),
                    "verify_impl native/JIT Ok-type disagree on `{label}`"
                );
            }
            (Err(ne), Err(je)) => {
                assert_eq!(
                    ne.disc(),
                    je.disc(),
                    "verify_impl native/JIT Err-discriminant disagree on `{label}`"
                );
            }
            _ => panic!(
                "verify_impl native/JIT Ok/Err shape disagree on `{label}` (native_ok={}, jit_ok={})",
                native.is_ok(),
                jit.is_ok()
            ),
        }
        // And both must match the documented Expect.
        match (expect, &native) {
            (OkTy(want), Ok(got)) => {
                let cmp = VeChecker {
                    context: Vec::new(),
                    env: &env,
                    universe_blind: true,
                };
                assert!(
                    cmp.ve_structural_eq(want, got),
                    "verify_impl Ok-type != expected on `{label}`"
                );
            }
            (ErrDisc(d), Err(e)) => {
                assert_eq!(
                    *d,
                    e.disc(),
                    "verify_impl Err-discriminant != expected on `{label}`"
                );
            }
            (OkTy(_), Err(e)) => panic!("expected Ok on `{label}`, got Err disc {}", e.disc()),
            (ErrDisc(d), Ok(_)) => panic!("expected Err disc {d} on `{label}`, got Ok"),
        }
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all verify_impl cases must agree native == JIT"
    );
    drop(buffer);
}

// ============================================================================
// MIR-PATH CAPSTONE: the JIT-EXECUTED verified `whnf_impl` WITH ITS IOTA RECURSOR
// ENGINE — the micro-checker's `reduce_recursor` (Bool.rec / Nat.rec) WIRED INTO
// whnf_impl via a NON-EMPTY RECURSORS gate, so whnf's recursor-reduction leaf is
// now FAITHFUL (no longer cut by an empty RECURSORS set).
//
// `--mir-emit-closure whnf_impl` over `reduce_recursor_slice.rs` lowers the
// call-graph closure: whnf_impl -> reduce_recursor -> { whnf_impl (back-edge),
// as_bool, nat_constructor } -> instantiate -> subst -> lift -> env_get -> burn.
// All of whnf_impl / reduce_recursor / as_bool / nat_constructor are REAL
// IN-MODULE bodies (verified below: whnf_impl Calls reduce_recursor; reduce_recursor
// Calls whnf_impl + as_bool + nat_constructor). Only the TRUE leaves remain
// 0-block externs (the `<[T] as Index<Range/RangeFrom>>::index` subslices,
// `<&[T] as IntoIterator>::into_iter`, `Arc<str>::from`, the `?`-op
// Try::branch/FromResidual on Result<_, MicroError>, Arc::as_ref / Vec ops /
// slice::reverse / the derived clones+PartialEq / Ord::cmp / Sub / saturating_add /
// Option::as_ref / __rust_alloc, and the `name_is_*` `&str`-eq predicates — the one
// thing the lowering cannot materialize, see the slice's cut-list), bound below.
//
// We run native whnf_impl == JIT machine code over recursor reductions:
//   - Bool.rec on Bool.true -> minor_1 / Bool.false -> minor_0;
//   - Nat.rec on Const "Nat.zero" -> minor_0;
//   - Nat.rec on `App(succ, App(succ, zero))` -> the UNFOLDED
//     `minor_1 (succ zero) (Nat.rec .. (succ zero))`, RE-whnf'd;
//   - an OVER-APPLIED recursor (extra args re-applied);
//   - a STUCK recursor (major not a constructor) -> the spine rebuilt;
//   - plain BETA/DELTA/SPINE/ZETA cases (the recursor gate must not perturb them).
//
// REGEN: `trust_ir_mir reduce_recursor_slice.rs --crate-type=lib
//   --mir-emit-closure whnf_impl <out>`. Refresh MIR_RR_WHNF_CLOSURE_TRUST_IR AND
// the EXT_RR_* symbol constants together (the crate-disambiguator hash is in both).

// The `?`-operator round-trips through the real std ControlFlow/Result/Infallible
// layouts (same-rustc family). Reuse the verify_impl-era imports.
// (Infallible / ControlFlow already imported above in this test file.)

// ===== reduce_recursor closure leaf-extern symbol constants =====
