/// The slice's `MicroChecker`: a single `env` fat-slice field (offset 0). The
/// in-module `env_get` reads `&self.env`. `#[repr(C)]` pins the layout.
#[repr(C)]
struct RrChecker<'e> {
    env: &'e [(MeArc<str>, Option<MicroExpr>)],
}

impl<'e> RrChecker<'e> {
    fn rr_env_get(&self, name: &MeArc<str>) -> Option<&MicroExpr> {
        let mut i: usize = 0;
        let n = self.env.len();
        while i < n {
            let entry = &self.env[i];
            if entry.0 == *name {
                return entry.1.as_ref();
            }
            i += 1;
        }
        None
    }
    fn rr_burn(&self) -> Result<(), MicroError> {
        Ok(())
    }

    // VERBATIM whnf_impl (the recursor gate fires for Bool.rec/Nat.rec).
    fn rr_whnf_impl(&self, e: &MicroExpr) -> Result<MicroExpr, MicroError> {
        self.rr_burn()?;
        match e {
            MicroExpr::Const(name) => {
                if rr_is_native_op(name) {
                    return Ok(e.clone());
                }
                if let Some(body) = self.rr_env_get(name) {
                    return self.rr_whnf_impl(body);
                }
                Ok(e.clone())
            }
            MicroExpr::App(f, a) => {
                let f_whnf = self.rr_whnf_impl(f)?;
                match &f_whnf {
                    MicroExpr::Lam(_, body) => {
                        let reduced = body.rr_instantiate(a);
                        self.rr_whnf_impl(&reduced)
                    }
                    _ => {
                        let mut head = f_whnf;
                        let mut args: Vec<MicroExpr> = vec![a.as_ref().clone()];
                        while let MicroExpr::App(hf, ha) = &head {
                            args.push(ha.as_ref().clone());
                            head = self.rr_whnf_impl(hf)?;
                        }
                        args.reverse();
                        if let MicroExpr::Const(name) = &head {
                            if rr_is_nat_binop_or_succ(name) {
                                let mut red_args = Vec::with_capacity(args.len());
                                for arg in &args {
                                    red_args.push(self.rr_whnf_impl(arg)?);
                                }
                                if let Some(r) = rr_reduce_nat_app(name, &red_args) {
                                    return self.rr_whnf_impl(&r);
                                }
                                let mut rebuilt = head.clone();
                                for arg in red_args {
                                    rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                                }
                                return Ok(rebuilt);
                            }
                            if rr_is_bool_binop(name) {
                                let mut red_args = Vec::with_capacity(args.len());
                                for arg in &args {
                                    red_args.push(self.rr_whnf_impl(arg)?);
                                }
                                if let Some(r) = rr_reduce_bool_app(name, &red_args) {
                                    return self.rr_whnf_impl(&r);
                                }
                                let mut rebuilt = head.clone();
                                for arg in red_args {
                                    rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                                }
                                return Ok(rebuilt);
                            }
                            if rr_is_recursor(name) {
                                if let Some(r) = self.rr_reduce_recursor(name, &args)? {
                                    return self.rr_whnf_impl(&r);
                                }
                                let mut rebuilt = head.clone();
                                for arg in args {
                                    rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                                }
                                return Ok(rebuilt);
                            }
                            if let Some(body) = self.rr_env_get(name) {
                                let mut applied = body.clone();
                                for arg in &args {
                                    applied = MicroExpr::App(
                                        MeArc::new(applied),
                                        MeArc::new(arg.clone()),
                                    );
                                }
                                return self.rr_whnf_impl(&applied);
                            }
                        }
                        let mut rebuilt = head;
                        for arg in args {
                            rebuilt = MicroExpr::App(MeArc::new(rebuilt), MeArc::new(arg));
                        }
                        Ok(rebuilt)
                    }
                }
            }
            MicroExpr::Let(_, val, body) => {
                let reduced = body.rr_instantiate(val);
                self.rr_whnf_impl(&reduced)
            }
            _ => Ok(e.clone()),
        }
    }

    // VERBATIM reduce_recursor.
    fn rr_reduce_recursor(
        &self,
        name: &str,
        args: &[MicroExpr],
    ) -> Result<Option<MicroExpr>, MicroError> {
        self.rr_burn()?;
        let num_minors = if rr_name_is_bool_rec(name) || rr_name_is_nat_rec(name) {
            2
        } else {
            return Ok(None);
        };
        let major_idx = 1 + num_minors;
        if args.len() <= major_idx {
            return Ok(None);
        }
        let minors = &args[1..major_idx];
        let major = self.rr_whnf_impl(&args[major_idx])?;
        let extra = &args[major_idx + 1..];
        let reduced = if rr_name_is_bool_rec(name) {
            let Some(b) = rr_as_bool(&major) else {
                return Ok(None);
            };
            let minor = if b { &minors[1] } else { &minors[0] };
            minor.clone()
        } else if rr_name_is_nat_rec(name) {
            match rr_nat_constructor(&major) {
                Some(RrNatCtor::Zero) => minors[0].clone(),
                Some(RrNatCtor::Succ(pred)) => {
                    let rec_on_pred = {
                        let mut spine = MicroExpr::Const(MeArc::from(name));
                        spine = MicroExpr::App(MeArc::new(spine), MeArc::new(args[0].clone()));
                        for m in minors {
                            spine = MicroExpr::App(MeArc::new(spine), MeArc::new(m.clone()));
                        }
                        MicroExpr::App(MeArc::new(spine), MeArc::new(pred.clone()))
                    };
                    MicroExpr::App(
                        MeArc::new(MicroExpr::App(
                            MeArc::new(minors[1].clone()),
                            MeArc::new(pred),
                        )),
                        MeArc::new(rec_on_pred),
                    )
                }
                None => return Ok(None),
            }
        } else {
            return Ok(None);
        };
        let mut out = reduced;
        for e in extra {
            out = MicroExpr::App(MeArc::new(out), MeArc::new(e.clone()));
        }
        Ok(Some(out))
    }
}

// ---- the reuse fns (lift/subst/instantiate), prefixed `rr_` to avoid collision ----
impl MicroExpr {
    fn rr_lift(&self, cutoff: u32, amount: u32) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                if *idx >= cutoff {
                    MicroExpr::BVar(idx.saturating_add(amount))
                } else {
                    self.clone()
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.rr_lift(cutoff, amount)),
                MeArc::new(a.rr_lift(cutoff, amount)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.rr_lift(cutoff, amount)),
                MeArc::new(body.rr_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.rr_lift(cutoff, amount)),
                MeArc::new(body.rr_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Let(ty, val, body) => MicroExpr::Let(
                MeArc::new(ty.rr_lift(cutoff, amount)),
                MeArc::new(val.rr_lift(cutoff, amount)),
                MeArc::new(body.rr_lift(cutoff.saturating_add(1), amount)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.rr_lift(cutoff, amount))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.rr_lift(cutoff, amount))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn rr_subst(&self, depth: u32, val: &MicroExpr) -> MicroExpr {
        match self {
            MicroExpr::BVar(idx) => {
                use std::cmp::Ordering;
                match idx.cmp(&depth) {
                    Ordering::Equal => val.rr_lift(0, depth),
                    Ordering::Greater => MicroExpr::BVar(idx - 1),
                    Ordering::Less => self.clone(),
                }
            }
            MicroExpr::Sort(l) => MicroExpr::Sort(l.clone()),
            MicroExpr::App(f, a) => MicroExpr::App(
                MeArc::new(f.rr_subst(depth, val)),
                MeArc::new(a.rr_subst(depth, val)),
            ),
            MicroExpr::Lam(ty, body) => MicroExpr::Lam(
                MeArc::new(ty.rr_subst(depth, val)),
                MeArc::new(body.rr_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Pi(ty, body) => MicroExpr::Pi(
                MeArc::new(ty.rr_subst(depth, val)),
                MeArc::new(body.rr_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Let(ty, v, body) => MicroExpr::Let(
                MeArc::new(ty.rr_subst(depth, val)),
                MeArc::new(v.rr_subst(depth, val)),
                MeArc::new(body.rr_subst(depth.saturating_add(1), val)),
            ),
            MicroExpr::Opaque(ty) => MicroExpr::Opaque(MeArc::new(ty.rr_subst(depth, val))),
            MicroExpr::Lit(_) => self.clone(),
            MicroExpr::Proj(idx, e) => MicroExpr::Proj(*idx, MeArc::new(e.rr_subst(depth, val))),
            MicroExpr::Const(_) => self.clone(),
        }
    }
    fn rr_instantiate(&self, arg: &MicroExpr) -> MicroExpr {
        self.rr_subst(0, arg)
    }
}

// A `Nat` ctor view (the native oracle's mirror of the slice's NatCtor).
enum RrNatCtor {
    Zero,
    Succ(MicroExpr),
}

// Native mirrors of the slice's as_bool / nat_constructor (constructor-form only).
fn rr_as_bool(e: &MicroExpr) -> Option<bool> {
    match e {
        MicroExpr::Const(name) => {
            if rr_name_is_bool_true(name) {
                Some(true)
            } else if rr_name_is_bool_false(name) {
                Some(false)
            } else {
                None
            }
        }
        _ => None,
    }
}
fn rr_nat_constructor(e: &MicroExpr) -> Option<RrNatCtor> {
    match e {
        MicroExpr::Const(name) if rr_name_is_nat_zero(name) => Some(RrNatCtor::Zero),
        MicroExpr::App(f, a) => match &**f {
            MicroExpr::Const(name) if rr_name_is_nat_succ(name) => {
                Some(RrNatCtor::Succ(a.as_ref().clone()))
            }
            _ => None,
        },
        _ => None,
    }
}
fn rr_is_recursor(name: &str) -> bool {
    rr_name_is_bool_rec(name) || rr_name_is_nat_rec(name)
}
fn rr_is_nat_binop_or_succ(_n: &str) -> bool {
    false
}
fn rr_is_bool_binop(_n: &str) -> bool {
    false
}
fn rr_is_native_op(_n: &MeArc<str>) -> bool {
    false
}
fn rr_reduce_nat_app(_op: &str, _a: &[MicroExpr]) -> Option<MicroExpr> {
    None
}
fn rr_reduce_bool_app(_op: &str, _a: &[MicroExpr]) -> Option<MicroExpr> {
    None
}
// The native side of the `name_is_*` predicates (the str literals live here).
fn rr_name_is_bool_rec(n: &str) -> bool {
    n == "Bool.rec"
}
fn rr_name_is_nat_rec(n: &str) -> bool {
    n == "Nat.rec"
}
fn rr_name_is_bool_true(n: &str) -> bool {
    n == "Bool.true"
}
fn rr_name_is_bool_false(n: &str) -> bool {
    n == "Bool.false"
}
fn rr_name_is_nat_zero(n: &str) -> bool {
    n == "Nat.zero"
}
fn rr_name_is_nat_succ(n: &str) -> bool {
    n == "Nat.succ"
}

// ===== the `name_is_*` `&str`-eq leaf shims (the JIT-bound versions) =====
// `&str` crosses the C ABI as a by-ref pointer to the 16-byte (data,len) fat slot.
extern "C" fn rr_shim_name_is_bool_rec(name: *const &str) -> bool {
    unsafe { *name == "Bool.rec" }
}
extern "C" fn rr_shim_name_is_nat_rec(name: *const &str) -> bool {
    unsafe { *name == "Nat.rec" }
}
extern "C" fn rr_shim_name_is_bool_true(name: *const &str) -> bool {
    unsafe { *name == "Bool.true" }
}
extern "C" fn rr_shim_name_is_bool_false(name: *const &str) -> bool {
    unsafe { *name == "Bool.false" }
}
extern "C" fn rr_shim_name_is_nat_zero(name: *const &str) -> bool {
    unsafe { *name == "Nat.zero" }
}
extern "C" fn rr_shim_name_is_nat_succ(name: *const &str) -> bool {
    unsafe { *name == "Nat.succ" }
}
extern "C" fn rr_shim_name_is_nat_binop_or_succ(_name: *const &str) -> bool {
    false
}
extern "C" fn rr_shim_name_is_bool_binop(_name: *const &str) -> bool {
    false
}

// ===== the subslice / iterator / Arc::from leaf shims =====
/// `<[MicroExpr] as Index<Range<usize>>>::index(self: &[T], r: Range) -> &[T]`.
/// sret = result fat (ptr,len); recv = the source fat (ptr,len); range = (start,end).
extern "C" fn rr_shim_index_range(
    sret: *mut (*const MicroExpr, usize),
    recv: *const (*const MicroExpr, usize),
    range: *const (usize, usize),
) {
    unsafe {
        let (base, _len) = *recv;
        let (start, end) = *range;
        let p = base.add(start);
        std::ptr::write(sret, (p, end - start));
    }
}
/// `<[MicroExpr] as Index<RangeFrom<usize>>>::index(self, RangeFrom{start}) -> &[T]`.
/// `RangeFrom<usize>` is a single-`usize`-field struct, so the frontend's faithful
/// by-value newtype ABI passes it BY VALUE as a `usize` (the inner `start`), not by
/// reference — so this shim takes `start: usize` directly.
extern "C" fn rr_shim_index_rangefrom(
    sret: *mut (*const MicroExpr, usize),
    recv: *const (*const MicroExpr, usize),
    start: usize,
) {
    unsafe {
        let (base, len) = *recv;
        let p = base.add(start);
        std::ptr::write(sret, (p, len - start));
    }
}
/// `<&[MicroExpr] as IntoIterator>::into_iter(self: &[T]) -> slice::Iter` modeled as
/// a `(cur, end)` cursor: cur = data, end = data + len*size_of::<MicroExpr>().
extern "C" fn rr_shim_slice_into_iter(
    sret: *mut (*const MicroExpr, *const MicroExpr),
    recv: *const (*const MicroExpr, usize),
) {
    unsafe {
        let (base, len) = *recv;
        let end = base.add(len);
        std::ptr::write(sret, (base, end));
    }
}
/// `<Arc<str> as From<&str>>::from(name: &str) -> Arc<str>` (sret fat 16-byte).
extern "C" fn rr_shim_arc_str_from(sret: *mut MeArc<str>, name: *const &str) {
    unsafe {
        std::ptr::write(sret, MeArc::from(*name));
    }
}

// ===== the standard whnf/recursor leaf shims (ABIs mirror the def_eq/verify slices) ==
extern "C" fn rr_shim_arc_expr_as_ref(arc_ref: *const *const u8) -> *const MicroExpr {
    unsafe { (*arc_ref).add(16) as *const MicroExpr }
}
extern "C" fn rr_shim_vec_push(vec: *mut Vec<MicroExpr>, value: *const MicroExpr) {
    unsafe {
        let v = std::ptr::read(value);
        (*vec).push(v);
    }
}
extern "C" fn rr_shim_vec_deref_mut(sret: *mut (*mut MicroExpr, usize), vec: *mut Vec<MicroExpr>) {
    unsafe {
        let s: &mut [MicroExpr] = (*vec).as_mut_slice();
        std::ptr::write(sret, (s.as_mut_ptr(), s.len()));
    }
}
extern "C" fn rr_shim_vec_deref(sret: *mut (*const MicroExpr, usize), vec: *const Vec<MicroExpr>) {
    unsafe {
        let s: &[MicroExpr] = (*vec).as_slice();
        std::ptr::write(sret, (s.as_ptr(), s.len()));
    }
}
extern "C" fn rr_shim_vec_len(vec: *const Vec<MicroExpr>) -> usize {
    unsafe { (*vec).len() }
}
extern "C" fn rr_shim_vec_with_capacity(sret: *mut Vec<MicroExpr>, cap: usize) {
    unsafe {
        std::ptr::write(sret, Vec::with_capacity(cap));
    }
}
extern "C" fn rr_shim_reverse(slice_ref: *const (*mut MicroExpr, usize)) {
    unsafe {
        let (ptr, len) = *slice_ref;
        let s: &mut [MicroExpr] = std::slice::from_raw_parts_mut(ptr, len);
        s.reverse();
    }
}
extern "C" fn rr_shim_opt_as_ref(
    sret: *mut Option<std::ptr::NonNull<MicroExpr>>,
    this: *const Option<MicroExpr>,
) {
    unsafe {
        let r: Option<std::ptr::NonNull<MicroExpr>> = (*this).as_ref().map(std::ptr::NonNull::from);
        std::ptr::write(sret, r);
    }
}
extern "C" fn rr_shim_arcstr_eq(a: *const MeArc<str>, b: *const MeArc<str>) -> bool {
    unsafe { *a == *b }
}
extern "C" fn rr_shim_arcstr_clone(sret: *mut [usize; 2], this: *const [usize; 2]) {
    unsafe { std::ptr::write(sret, *this) }
}
extern "C" fn rr_shim_arcexpr_clone(sret: *mut usize, this: *const usize) {
    unsafe { std::ptr::write(sret, *this) }
}
extern "C" fn rr_shim_arclevel_clone(sret: *mut usize, this: *const usize) {
    unsafe { std::ptr::write(sret, *this) }
}
/// `<Arc<str> as Deref>::deref(&self) -> &str` (sret fat (ptr,len)): the str slice
/// lives at the ArcInner data (thin Arc + 16) and its len is the Arc's trailing
/// metadata word. The Arc<str> value here is a FAT pointer (data ptr + len).
extern "C" fn rr_shim_arc_str_deref(
    sret: *mut (*const u8, usize),
    this: *const (*const u8, usize),
) {
    unsafe {
        let (thin, len) = *this;
        let data = thin.add(16);
        std::ptr::write(sret, (data, len));
    }
}
extern "C" fn rr_shim_ord_cmp(sret: *mut i8, a: *const u32, b: *const u32) {
    unsafe {
        let o = (*a).cmp(&*b);
        std::ptr::write(sret, o as i8);
    }
}
extern "C" fn rr_shim_sub(a: *const u32, b: u32) -> u32 {
    unsafe { *a - b }
}
extern "C" fn rr_shim_sat_add(a: u32, b: u32) -> u32 {
    a.saturating_add(b)
}

// ===== the `?`-operator Try::branch / FromResidual leaf shims =====
extern "C" fn rr_shim_branch_unit(
    sret: *mut ControlFlow<Result<Infallible, MicroError>, ()>,
    arg: *const Result<(), MicroError>,
) {
    unsafe {
        let r = std::ptr::read(arg);
        let cf = match r {
            Ok(v) => ControlFlow::Continue(v),
            Err(e) => ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
extern "C" fn rr_shim_branch_expr(
    sret: *mut ControlFlow<Result<Infallible, MicroError>, MicroExpr>,
    arg: *const Result<MicroExpr, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(arg);
        let cf = match r {
            Ok(v) => ControlFlow::Continue(v),
            Err(e) => ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
extern "C" fn rr_shim_branch_opt(
    sret: *mut ControlFlow<Result<Infallible, MicroError>, Option<MicroExpr>>,
    arg: *const Result<Option<MicroExpr>, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(arg);
        let cf = match r {
            Ok(v) => ControlFlow::Continue(v),
            Err(e) => ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
extern "C" fn rr_shim_fromres_expr(
    sret: *mut Result<MicroExpr, MicroError>,
    residual: *const Result<Infallible, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(residual);
        let out: Result<MicroExpr, MicroError> = match r {
            Err(e) => Err(e),
            Ok(_inf) => unreachable!(),
        };
        std::ptr::write(sret, out);
    }
}
extern "C" fn rr_shim_fromres_opt(
    sret: *mut Result<Option<MicroExpr>, MicroError>,
    residual: *const Result<Infallible, MicroError>,
) {
    unsafe {
        let r = std::ptr::read(residual);
        let out: Result<Option<MicroExpr>, MicroError> = match r {
            Err(e) => Err(e),
            Ok(_inf) => unreachable!(),
        };
        std::ptr::write(sret, out);
    }
}

