// ── Faithful re-decl of the slice's REAL kernel types (identical layout) ──────

#[derive(Clone, Debug, PartialEq, Eq)]
#[allow(dead_code)]
enum HlLevel {
    Zero,
    Succ(Box<HlLevel>),
    Param(u32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(dead_code)]
struct HlName(pub u32);

#[allow(dead_code)]
type HlLevelVec = Vec<HlLevel>;

#[derive(Clone, Debug, PartialEq, Eq)]
#[allow(dead_code)]
enum HlLiteral {
    Nat(u64),
    String(std::sync::Arc<str>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(dead_code)]
struct HlBinderData {
    pub info: u8,
    pub mult: u8,
}

#[allow(dead_code)]
type HlMDataMap = Vec<(HlName, u64)>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(dead_code)]
struct HlFVarId(pub u64);

#[derive(Clone, Debug, PartialEq, Eq)]
#[allow(dead_code)]
enum HlZFCSetExpr {
    Empty,
    Singleton(std::sync::Arc<HlExpr>),
    Pair(std::sync::Arc<HlExpr>, std::sync::Arc<HlExpr>),
    Union(std::sync::Arc<HlExpr>),
    PowerSet(std::sync::Arc<HlExpr>),
    Separation {
        set: std::sync::Arc<HlExpr>,
        pred: std::sync::Arc<HlExpr>,
    },
    Replacement {
        set: std::sync::Arc<HlExpr>,
        func: std::sync::Arc<HlExpr>,
    },
    Infinity,
    Choice(std::sync::Arc<HlExpr>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[allow(dead_code)]
struct HlExprMeta(u64);

impl HlExprMeta {
    const BVAR_RANGE_SHIFT: u32 = 44;
    const MAX_BVAR_RANGE: u32 = 1_048_575;
    fn pack(hash: u32, loose_bvar_range: u32, approx_depth: u32) -> Self {
        let depth = approx_depth.min(255);
        assert!(loose_bvar_range <= Self::MAX_BVAR_RANGE);
        let bits = (hash as u64)
            | ((depth as u64) << 32)
            | ((loose_bvar_range as u64) << Self::BVAR_RANGE_SHIFT);
        HlExprMeta(bits)
    }
    fn loose_bvar_range(self) -> u32 {
        (self.0 >> Self::BVAR_RANGE_SHIFT) as u32
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
#[allow(dead_code)]
enum HlExprKind {
    BVar(u32),
    FVar(HlFVarId),
    Sort(HlLevel),
    Const(HlName, HlLevelVec),
    App(std::sync::Arc<HlExpr>, std::sync::Arc<HlExpr>),
    Lam(HlBinderData, std::sync::Arc<HlExpr>, std::sync::Arc<HlExpr>),
    Pi(HlBinderData, std::sync::Arc<HlExpr>, std::sync::Arc<HlExpr>),
    Let(
        HlName,
        std::sync::Arc<HlExpr>,
        std::sync::Arc<HlExpr>,
        std::sync::Arc<HlExpr>,
        bool,
    ),
    Lit(HlLiteral),
    Proj(HlName, u32, std::sync::Arc<HlExpr>),
    MData(HlMDataMap, std::sync::Arc<HlExpr>),
    SProp,
    Squash(std::sync::Arc<HlExpr>),
    CubicalInterval,
    CubicalI0,
    CubicalI1,
    CubicalPath {
        ty: std::sync::Arc<HlExpr>,
        left: std::sync::Arc<HlExpr>,
        right: std::sync::Arc<HlExpr>,
    },
    CubicalPathLam {
        body: std::sync::Arc<HlExpr>,
    },
    CubicalPathApp {
        path: std::sync::Arc<HlExpr>,
        arg: std::sync::Arc<HlExpr>,
    },
    CubicalHComp {
        ty: std::sync::Arc<HlExpr>,
        phi: std::sync::Arc<HlExpr>,
        u: std::sync::Arc<HlExpr>,
        base: std::sync::Arc<HlExpr>,
    },
    CubicalTransp {
        ty: std::sync::Arc<HlExpr>,
        phi: std::sync::Arc<HlExpr>,
        base: std::sync::Arc<HlExpr>,
    },
    ZFCSet(HlZFCSetExpr),
    ZFCMem {
        element: std::sync::Arc<HlExpr>,
        set: std::sync::Arc<HlExpr>,
    },
    ZFCComprehension {
        domain: std::sync::Arc<HlExpr>,
        pred: std::sync::Arc<HlExpr>,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
#[allow(dead_code)]
struct HlExpr {
    kind: HlExprKind,
    meta: HlExprMeta,
}

#[allow(dead_code)]
fn hl_shift_bvar_range(start: u32, end: u32) -> Option<(u32, u32)> {
    if end != u32::MAX && start >= end {
        return None;
    }
    if start == u32::MAX {
        return None;
    }
    let next_start = start.saturating_add(1);
    let next_end = if end == u32::MAX {
        u32::MAX
    } else {
        end.saturating_add(1)
    };
    Some((next_start, next_end))
}

#[allow(dead_code)]
fn hl_bvar_in_range(idx: u32, start: u32, end: u32) -> bool {
    if end == u32::MAX {
        idx >= start
    } else {
        idx >= start && idx < end
    }
}

impl HlZFCSetExpr {
    fn has_loose_bvar_in_range(&self, start: u32, end: u32) -> bool {
        if end != u32::MAX && start >= end {
            return false;
        }
        match self {
            HlZFCSetExpr::Empty | HlZFCSetExpr::Infinity => false,
            HlZFCSetExpr::Singleton(e) => e.has_loose_bvar_in_range(start, end),
            HlZFCSetExpr::Pair(a, b) => {
                a.has_loose_bvar_in_range(start, end) || b.has_loose_bvar_in_range(start, end)
            }
            HlZFCSetExpr::Union(e) | HlZFCSetExpr::PowerSet(e) | HlZFCSetExpr::Choice(e) => {
                e.has_loose_bvar_in_range(start, end)
            }
            HlZFCSetExpr::Separation { set, pred }
            | HlZFCSetExpr::Replacement { set, func: pred } => {
                let p = match hl_shift_bvar_range(start, end) {
                    Some((s, e)) => pred.has_loose_bvar_in_range(s, e),
                    None => false,
                };
                set.has_loose_bvar_in_range(start, end) || p
            }
        }
    }
}

impl HlExpr {
    fn loose_bvar_range(&self) -> u32 {
        self.meta.loose_bvar_range()
    }
    // Native oracle == the verbatim has_loose_bvar_in_range_impl body.
    fn has_loose_bvar_in_range(&self, start: u32, end: u32) -> bool {
        if end != u32::MAX && start >= end {
            return false;
        }
        if self.loose_bvar_range() <= start {
            return false;
        }
        match &self.kind {
            HlExprKind::BVar(idx) => hl_bvar_in_range(*idx, start, end),
            HlExprKind::FVar(_)
            | HlExprKind::Sort(_)
            | HlExprKind::Const(_, _)
            | HlExprKind::Lit(_) => false,
            HlExprKind::App(f, a) => {
                f.has_loose_bvar_in_range(start, end) || a.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::Lam(_, ty, body) | HlExprKind::Pi(_, ty, body) => {
                let b = match hl_shift_bvar_range(start, end) {
                    Some((s, e)) => body.has_loose_bvar_in_range(s, e),
                    None => false,
                };
                ty.has_loose_bvar_in_range(start, end) || b
            }
            HlExprKind::Let(_, ty, val, body, _) => {
                let b = match hl_shift_bvar_range(start, end) {
                    Some((s, e)) => body.has_loose_bvar_in_range(s, e),
                    None => false,
                };
                ty.has_loose_bvar_in_range(start, end)
                    || val.has_loose_bvar_in_range(start, end)
                    || b
            }
            HlExprKind::Proj(_, _, e) => e.has_loose_bvar_in_range(start, end),
            HlExprKind::MData(_, inner) => inner.has_loose_bvar_in_range(start, end),
            HlExprKind::SProp => false,
            HlExprKind::Squash(inner) => inner.has_loose_bvar_in_range(start, end),
            HlExprKind::CubicalInterval | HlExprKind::CubicalI0 | HlExprKind::CubicalI1 => false,
            HlExprKind::CubicalPath { ty, left, right } => {
                ty.has_loose_bvar_in_range(start, end)
                    || left.has_loose_bvar_in_range(start, end)
                    || right.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::CubicalPathLam { body } => match hl_shift_bvar_range(start, end) {
                Some((s, e)) => body.has_loose_bvar_in_range(s, e),
                None => false,
            },
            HlExprKind::CubicalPathApp { path, arg } => {
                path.has_loose_bvar_in_range(start, end) || arg.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::CubicalHComp { ty, phi, u, base } => {
                ty.has_loose_bvar_in_range(start, end)
                    || phi.has_loose_bvar_in_range(start, end)
                    || u.has_loose_bvar_in_range(start, end)
                    || base.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::CubicalTransp { ty, phi, base } => {
                ty.has_loose_bvar_in_range(start, end)
                    || phi.has_loose_bvar_in_range(start, end)
                    || base.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::ZFCSet(s) => s.has_loose_bvar_in_range(start, end),
            HlExprKind::ZFCMem { element, set } => {
                element.has_loose_bvar_in_range(start, end)
                    || set.has_loose_bvar_in_range(start, end)
            }
            HlExprKind::ZFCComprehension { domain, pred } => {
                let p = match hl_shift_bvar_range(start, end) {
                    Some((s, e)) => pred.has_loose_bvar_in_range(s, e),
                    None => false,
                };
                domain.has_loose_bvar_in_range(start, end) || p
            }
        }
    }
}

// `(&HlExpr, u32, u32) -> bool` ABI of the JIT-compiled impl fn.
#[allow(dead_code)]
type HlbirFn = unsafe extern "C" fn(*const HlExpr, u32, u32) -> bool;

#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_has_loose_bvar_in_range_real_expr_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "mir_has_loose_bvar_in_range_real_expr_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(MIR_HLBIR_CLOSURE_TRUST_IR)
        .expect("MIR-emitted has_loose_bvar_in_range closure trust-ir text must parse");
    // CONFIRM the call graph is genuinely IN-MODULE (real bodies, not extern shims).
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("Expr__has_loose_bvar_in_range_impl"),
        "impl must be in-module"
    );
    assert!(
        bodied("Expr__has_loose_bvar_in_range"),
        "public recursion target must be in-module"
    );
    assert!(
        bodied("Expr__loose_bvar_range"),
        "Expr::loose_bvar_range (reads meta field) must be in-module"
    );
    assert!(
        bodied("ExprMeta__loose_bvar_range"),
        "ExprMeta::loose_bvar_range (>>44 bit-extract) must be in-module"
    );
    assert!(
        bodied("shift_bvar_range"),
        "shift_bvar_range must be in-module"
    );
    assert!(bodied("bvar_in_range"), "bvar_in_range must be in-module");
    assert!(
        bodied("ZFCSetExpr__has_loose_bvar_in_range"),
        "ZFC delegation must be in-module"
    );

    // ZERO externs: the closure is fully self-contained (read-only fold, no alloc).
    let externs: HashMap<String, *const u8> = HashMap::new();

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of has_loose_bvar_in_range closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("Expr__has_loose_bvar_in_range_impl")
        .expect("JIT symbol `Expr__has_loose_bvar_in_range_impl` not found")
        .as_ptr();
    // SAFETY: machine code for the `(&self, u32, u32) -> bool` ABI; buffer live.
    let f: HlbirFn = unsafe { std::mem::transmute(raw) };

    // ── Builders that compute the REAL cached meta word (the loose_bvar_range
    //    field) exactly as `compute_meta` would, so the O(1) guard fires the same.
    use std::sync::Arc;
    let mk = |kind: HlExprKind, range: u32| HlExpr {
        kind,
        meta: HlExprMeta::pack(0, range, 0),
    };
    // range(child) read off the cached meta; binder children contribute range-1.
    let rng = |e: &HlExpr| e.loose_bvar_range();
    let dec = |r: u32| r.saturating_sub(1);

    let bvar = |i: u32| mk(HlExprKind::BVar(i), i.saturating_add(1));
    let sort = || mk(HlExprKind::Sort(HlLevel::Zero), 0);
    let konst = || mk(HlExprKind::Const(HlName(0), vec![]), 0);
    let lit = || mk(HlExprKind::Lit(HlLiteral::Nat(7)), 0);
    let fvar = || mk(HlExprKind::FVar(HlFVarId(3)), 0);
    let sprop = || mk(HlExprKind::SProp, 0);
    let ci = || mk(HlExprKind::CubicalInterval, 0);
    let app = |x: HlExpr, y: HlExpr| {
        let r = rng(&x).max(rng(&y));
        mk(HlExprKind::App(Arc::new(x), Arc::new(y)), r)
    };
    let lam = |t: HlExpr, b: HlExpr| {
        let r = rng(&t).max(dec(rng(&b)));
        mk(
            HlExprKind::Lam(HlBinderData { info: 0, mult: 2 }, Arc::new(t), Arc::new(b)),
            r,
        )
    };
    let pi = |t: HlExpr, b: HlExpr| {
        let r = rng(&t).max(dec(rng(&b)));
        mk(
            HlExprKind::Pi(HlBinderData { info: 0, mult: 2 }, Arc::new(t), Arc::new(b)),
            r,
        )
    };
    let lett = |t: HlExpr, v: HlExpr, b: HlExpr| {
        let r = rng(&t).max(rng(&v)).max(dec(rng(&b)));
        mk(
            HlExprKind::Let(HlName(0), Arc::new(t), Arc::new(v), Arc::new(b), false),
            r,
        )
    };
    let proj = |i: u32, e: HlExpr| {
        let r = rng(&e);
        mk(HlExprKind::Proj(HlName(1), i, Arc::new(e)), r)
    };
    let mdata = |e: HlExpr| {
        let r = rng(&e);
        mk(HlExprKind::MData(vec![], Arc::new(e)), r)
    };
    let squash = |e: HlExpr| {
        let r = rng(&e);
        mk(HlExprKind::Squash(Arc::new(e)), r)
    };
    let cpath = |t: HlExpr, l: HlExpr, rr: HlExpr| {
        let r = rng(&t).max(rng(&l)).max(rng(&rr));
        mk(
            HlExprKind::CubicalPath {
                ty: Arc::new(t),
                left: Arc::new(l),
                right: Arc::new(rr),
            },
            r,
        )
    };
    let cplam = |b: HlExpr| {
        let r = dec(rng(&b));
        mk(HlExprKind::CubicalPathLam { body: Arc::new(b) }, r)
    };
    let cpapp = |p: HlExpr, a: HlExpr| {
        let r = rng(&p).max(rng(&a));
        mk(
            HlExprKind::CubicalPathApp {
                path: Arc::new(p),
                arg: Arc::new(a),
            },
            r,
        )
    };
    let chcomp = |t: HlExpr, p: HlExpr, u: HlExpr, bb: HlExpr| {
        let r = rng(&t).max(rng(&p)).max(rng(&u)).max(rng(&bb));
        mk(
            HlExprKind::CubicalHComp {
                ty: Arc::new(t),
                phi: Arc::new(p),
                u: Arc::new(u),
                base: Arc::new(bb),
            },
            r,
        )
    };
    let ctransp = |t: HlExpr, p: HlExpr, bb: HlExpr| {
        let r = rng(&t).max(rng(&p)).max(rng(&bb));
        mk(
            HlExprKind::CubicalTransp {
                ty: Arc::new(t),
                phi: Arc::new(p),
                base: Arc::new(bb),
            },
            r,
        )
    };
    let zmem = |el: HlExpr, st: HlExpr| {
        let r = rng(&el).max(rng(&st));
        mk(
            HlExprKind::ZFCMem {
                element: Arc::new(el),
                set: Arc::new(st),
            },
            r,
        )
    };
    let zcompr = |d: HlExpr, p: HlExpr| {
        let r = rng(&d).max(dec(rng(&p)));
        mk(
            HlExprKind::ZFCComprehension {
                domain: Arc::new(d),
                pred: Arc::new(p),
            },
            r,
        )
    };
    // ZFCSet wrappers (the i64-discriminant inner enum delegation path).
    let zset_pair = |a: HlExpr, b: HlExpr| {
        let r = rng(&a).max(rng(&b));
        mk(
            HlExprKind::ZFCSet(HlZFCSetExpr::Pair(Arc::new(a), Arc::new(b))),
            r,
        )
    };
    let zset_sep = |s: HlExpr, p: HlExpr| {
        let r = rng(&s).max(dec(rng(&p)));
        mk(
            HlExprKind::ZFCSet(HlZFCSetExpr::Separation {
                set: Arc::new(s),
                pred: Arc::new(p),
            }),
            r,
        )
    };
    let zset_empty = || mk(HlExprKind::ZFCSet(HlZFCSetExpr::Empty), 0);

    // (expr, start, end, label) — across EVERY variant + the binder-shift descent
    // (a BVar that IS / ISN'T loose at the queried depth) + the i64-discrim ZFC path.
    let cases: Vec<(HlExpr, u32, u32, &str)> = vec![
        // leaves — never loose.
        (bvar(0), 0, u32::MAX, "BVar(0) in [0,inf) loose"),
        (bvar(0), 1, u32::MAX, "BVar(0) in [1,inf) not loose"),
        (bvar(3), 2, 5, "BVar(3) in [2,5) loose"),
        (bvar(3), 4, 6, "BVar(3) in [4,6) not loose"),
        (sort(), 0, u32::MAX, "Sort never loose"),
        (konst(), 0, u32::MAX, "Const never loose"),
        (lit(), 0, u32::MAX, "Lit never loose"),
        (fvar(), 0, u32::MAX, "FVar never loose"),
        (sprop(), 0, u32::MAX, "SProp never loose"),
        (ci(), 0, u32::MAX, "CubicalInterval never loose"),
        // App.
        (app(bvar(0), bvar(1)), 0, u32::MAX, "App holds loose"),
        (app(sort(), konst()), 0, u32::MAX, "App no loose"),
        // Lam / Pi — the binder shifts the query range up by 1.
        (
            lam(sort(), bvar(0)),
            0,
            u32::MAX,
            "Lam binds BVar0 -> not loose at 0",
        ),
        (
            lam(sort(), bvar(1)),
            0,
            u32::MAX,
            "Lam body BVar1 -> loose at 0",
        ),
        (pi(bvar(0), sort()), 0, u32::MAX, "Pi domain BVar0 loose"),
        (
            pi(sort(), bvar(0)),
            0,
            u32::MAX,
            "Pi binds BVar0 -> not loose",
        ),
        // Let — 3 children, body under a binder.
        (
            lett(sort(), bvar(0), bvar(0)),
            0,
            u32::MAX,
            "Let val BVar0 loose",
        ),
        (
            lett(sort(), sort(), bvar(0)),
            0,
            u32::MAX,
            "Let body binds BVar0 -> not loose",
        ),
        (
            lett(sort(), sort(), bvar(1)),
            0,
            u32::MAX,
            "Let body BVar1 -> loose",
        ),
        // Proj / MData / Squash wrappers.
        (proj(2, bvar(0)), 0, u32::MAX, "Proj loose"),
        (mdata(bvar(0)), 0, u32::MAX, "MData loose"),
        (squash(sort()), 0, u32::MAX, "Squash no loose"),
        // Cubical STRUCT-variants.
        (
            cpath(sort(), bvar(0), bvar(1)),
            0,
            u32::MAX,
            "CubicalPath loose (left)",
        ),
        (
            cpath(sort(), sort(), sort()),
            0,
            u32::MAX,
            "CubicalPath no loose",
        ),
        (
            cplam(bvar(0)),
            0,
            u32::MAX,
            "CubicalPathLam binds BVar0 -> not loose",
        ),
        (
            cplam(bvar(1)),
            0,
            u32::MAX,
            "CubicalPathLam body BVar1 -> loose",
        ),
        (cpapp(bvar(0), sort()), 0, u32::MAX, "CubicalPathApp loose"),
        (
            chcomp(sort(), sort(), sort(), bvar(0)),
            0,
            u32::MAX,
            "CubicalHComp loose (base)",
        ),
        (
            chcomp(sort(), sort(), sort(), sort()),
            0,
            u32::MAX,
            "CubicalHComp no loose",
        ),
        (
            ctransp(sort(), bvar(0), sort()),
            0,
            u32::MAX,
            "CubicalTransp loose (phi)",
        ),
        // ZFC struct-variants on ExprKind.
        (zmem(bvar(0), sort()), 0, u32::MAX, "ZFCMem loose (element)"),
        (
            zcompr(sort(), bvar(0)),
            0,
            u32::MAX,
            "ZFCComprehension pred binds BVar0 -> not loose",
        ),
        (
            zcompr(sort(), bvar(1)),
            0,
            u32::MAX,
            "ZFCComprehension pred BVar1 -> loose",
        ),
        (
            zcompr(bvar(0), sort()),
            0,
            u32::MAX,
            "ZFCComprehension domain BVar0 -> loose",
        ),
        // ZFCSet(inner) — the i64-discriminant inner-enum delegation path.
        (
            zset_pair(bvar(0), sort()),
            0,
            u32::MAX,
            "ZFCSet::Pair loose",
        ),
        (
            zset_pair(sort(), sort()),
            0,
            u32::MAX,
            "ZFCSet::Pair no loose",
        ),
        (
            zset_sep(sort(), bvar(0)),
            0,
            u32::MAX,
            "ZFCSet::Separation pred binds BVar0 -> not loose",
        ),
        (
            zset_sep(sort(), bvar(1)),
            0,
            u32::MAX,
            "ZFCSet::Separation pred BVar1 -> loose",
        ),
        (zset_empty(), 0, u32::MAX, "ZFCSet::Empty no loose"),
        // start>=end early reject; deep nesting.
        (bvar(0), 5, 5, "empty range -> false"),
        (
            lam(sort(), app(bvar(1), proj(0, bvar(2)))),
            0,
            u32::MAX,
            "deep nested mixed loose",
        ),
        (
            lam(sort(), lam(sort(), app(bvar(0), bvar(1)))),
            0,
            u32::MAX,
            "double-binder bound -> not loose at 0",
        ),
    ];

    let mut pass = 0usize;
    for (e, start, end, label) in &cases {
        let native = e.has_loose_bvar_in_range(*start, *end);
        let ep: *const HlExpr = e as *const HlExpr;
        let jit = unsafe { f(ep, *start, *end) };
        assert_eq!(
            native, jit,
            "MIR-emitted JIT machine code disagrees with native Rust on `{label}`: native={native} jit={jit}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all has_loose_bvar_in_range cases must agree native == JIT"
    );
    drop(buffer);
}

