// ── Native oracle extension: the verbatim slice `instantiate`/`instantiate_at` over
//    the SAME `CxExpr` types, plus the `lett`/`proj` constructors the Let/Proj arms
//    rebuild through. (`lift_at`, `from_kind`, `compute_meta`, the constructors, and
//    `cx_deep_eq` — which already covers Let/Proj — are reused verbatim above.) ──
#[allow(dead_code)]
impl CxExpr {
    fn lett(name: CxName, ty: CxExpr, val: CxExpr, body: CxExpr, nondep: bool) -> Self {
        CxExpr::from_kind(CxExprKind::Let(
            name,
            std::sync::Arc::new(ty),
            std::sync::Arc::new(val),
            std::sync::Arc::new(body),
            nondep,
        ))
    }
    fn proj(name: CxName, idx: u32, e: CxExpr) -> Self {
        CxExpr::from_kind(CxExprKind::Proj(name, idx, std::sync::Arc::new(e)))
    }

    // VERBATIM instantiate / instantiate_at (the beta-substitution primitive).
    fn instantiate(&self, val: &CxExpr) -> CxExpr {
        self.instantiate_at(val, 0)
    }
    fn instantiate_at(&self, val: &CxExpr, depth: u32) -> CxExpr {
        if depth >= self.loose_bvar_range() {
            return self.clone();
        }
        match &self.kind {
            CxExprKind::BVar(idx) => {
                if *idx == depth {
                    val.lift_at(0, depth)
                } else if *idx > depth {
                    CxExpr::bvar(idx.saturating_sub(1))
                } else {
                    self.clone()
                }
            }
            CxExprKind::App(f, a) => {
                CxExpr::app(f.instantiate_at(val, depth), a.instantiate_at(val, depth))
            }
            CxExprKind::Lam(bd, ty, body) => CxExpr::lam(
                *bd,
                ty.instantiate_at(val, depth),
                body.instantiate_at(val, depth.saturating_add(1)),
            ),
            CxExprKind::Pi(bd, ty, body) => CxExpr::pi(
                *bd,
                ty.instantiate_at(val, depth),
                body.instantiate_at(val, depth.saturating_add(1)),
            ),
            CxExprKind::Let(name, ty, val_e, body, nondep) => CxExpr::lett(
                *name,
                ty.instantiate_at(val, depth),
                val_e.instantiate_at(val, depth),
                body.instantiate_at(val, depth.saturating_add(1)),
                *nondep,
            ),
            CxExprKind::Proj(name, idx, e) => {
                CxExpr::proj(*name, *idx, e.instantiate_at(val, depth))
            }
            _ => self.clone(),
        }
    }
}

/// `(sret *mut CxExpr, &self, *const val, depth) -> ()` ABI of the MIR-emitted instantiate_at.
#[allow(dead_code)]
type CxInstantiateAtFn = extern "C" fn(*mut CxExpr, *const CxExpr, *const CxExpr, u32);

/// Faithful `<u32 as Hash>::hash::<KaniHasher>` shim — `(value: &u32, state: &mut
/// KaniHasher)`. The Proj reconstruction (`compute_meta` Proj arm -> `hash_name`)
/// legitimately reaches this when the JIT rebuilds a `Proj` around the substitution.
/// KaniHasher's state is a single `u64`; `write_u32(i)` is `state ^= i; state *= MUL`.
extern "C" fn cx_shim_hash_u32(value: *const u32, state: *mut u64) {
    // SAFETY: JIT passes a valid `&u32` payload + a `&mut KaniHasher` (a single u64).
    unsafe {
        let i = *value as u64;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(0x517cc1b727220a95);
    }
}

#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_real_expr_instantiate_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_real_expr_instantiate_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_INSTANTIATE_AT_CLOSURE_TRUST_IR)
        .expect("MIR-emitted `instantiate_at` (Expr BETA substitution) trust-ir text must parse");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("Expr__instantiate_at"),
        "the beta-substitution fn must be in-module"
    );
    assert!(
        bodied("Expr__lift_at"),
        "lift_at (the COMPOSED under-binder lift) must be in-module"
    );
    assert!(
        bodied("Expr__from_kind"),
        "from_kind (CONSTRUCTION primitive) must be in-module"
    );
    assert!(
        bodied("ExprKind__compute_meta"),
        "compute_meta dispatch must be in-module"
    );
    assert!(
        bodied("ExprMeta__mk_app_meta"),
        "mk_app_meta (App metadata) must be in-module"
    );
    assert!(
        bodied("ExprMeta__mk_binder_meta"),
        "mk_binder_meta (Lam/Pi metadata) must be in-module"
    );
    assert!(
        bodied("ExprMeta__mk_let_meta"),
        "mk_let_meta (Let metadata) must be in-module"
    );
    assert!(
        bodied("ExprMeta__pack"),
        "ExprMeta::pack (bit-packing) must be in-module"
    );
    assert!(
        bodied("mix_hash"),
        "mix_hash (MurmurHash mixer) must be in-module"
    );
    assert!(
        bodied("Expr__app")
            && bodied("Expr__lam")
            && bodied("Expr__pi")
            && bodied("Expr__bvar")
            && bodied("Expr__lett")
            && bodied("Expr__proj"),
        "the real constructors must be in-module"
    );
    assert!(
        MIR_INSTANTIATE_AT_CLOSURE_TRUST_IR.contains("heap_alloc rust_heap"),
        "Arc::new children must lower to heap_alloc (not stubbed)"
    );
    assert!(
        MIR_INSTANTIATE_AT_CLOSURE_TRUST_IR.contains("14313749767032793493"),
        "mix_hash MurmurHash constant (compute_meta arithmetic) must be lowered"
    );

    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert("__rust_alloc".to_string(), cx_shim_rust_alloc as *const u8);
    externs.insert(
        "_RNvMs6_NtCs2EYQwhfuABO_4core3numm14saturating_add".to_string(),
        cx_shim_sat_add as *const u8,
    );
    externs.insert(
        "_RNvMs6_NtCs2EYQwhfuABO_4core3numm14saturating_sub".to_string(),
        cx_shim_sat_sub as *const u8,
    );
    externs.insert(
        "_RNvMs7_NtCs2EYQwhfuABO_4core3numy12wrapping_mul".to_string(),
        cx_shim_wrap_mul as *const u8,
    );
    externs.insert(
        "_RNvYhNtNtCs2EYQwhfuABO_4core3cmp3Ord3maxCs7NMZVpYdFJS_28clean_expr_instantiate_slice"
            .to_string(),
        cx_shim_max_u8 as *const u8,
    );
    externs.insert(
        "_RNvYmNtNtCs2EYQwhfuABO_4core3cmp3Ord3maxCs7NMZVpYdFJS_28clean_expr_instantiate_slice"
            .to_string(),
        cx_shim_max_u32 as *const u8,
    );
    externs.insert(
        "_RNvYmNtNtCs2EYQwhfuABO_4core3cmp3Ord3minCs7NMZVpYdFJS_28clean_expr_instantiate_slice"
            .to_string(),
        cx_shim_min_u32 as *const u8,
    );
    externs.insert("_RNvXsu_NtCskTzINo8ZBH9_5alloc4syncINtB5_3ArcNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice4ExprENtNtCs2EYQwhfuABO_4core5clone5Clone5cloneBI_".to_string(), cx_shim_arc_clone as *const u8);
    externs.insert("_RNvXsd_NtCskTzINo8ZBH9_5alloc5boxedINtB5_3BoxNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice5LevelENtNtCs2EYQwhfuABO_4core5clone5Clone5cloneBJ_".to_string(), cx_shim_box_lvl_clone as *const u8);
    externs.insert("_RNvXsa_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice5LevelENtNtCs2EYQwhfuABO_4core5clone5Clone5cloneBH_".to_string(), cx_shim_vec_lvl_clone as *const u8);
    externs.insert("_RINvXs9_NtNtCs2EYQwhfuABO_4core4hash5implsmNtB8_4Hash4hashNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice10KaniHasherEBW_".to_string(), cx_shim_hash_u32 as *const u8);
    externs.insert("_RINvXsa_NtNtCs2EYQwhfuABO_4core4hash5implsyNtB8_4Hash4hashNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice10KaniHasherEBW_".to_string(), cx_shim_hash_unreached as *const u8);
    externs.insert("_RINvXsg_NtNtCs2EYQwhfuABO_4core4hash5implsiNtB8_4Hash4hashNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice10KaniHasherEBW_".to_string(), cx_shim_hash_unreached as *const u8);
    externs.insert("_RINvXsk_NtCskTzINo8ZBH9_5alloc5boxedINtB6_3BoxNtCs7NMZVpYdFJS_28clean_expr_instantiate_slice5LevelENtNtCs2EYQwhfuABO_4core4hash4Hash4hashNtBK_10KaniHasherEBK_".to_string(), cx_shim_hash_unreached as *const u8);

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect(
            "trust-cg JIT compile of MIR-emitted `instantiate_at` (Expr BETA substitution) failed",
        )
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("Expr__instantiate_at")
        .expect("JIT symbol `Expr__instantiate_at` not found")
        .as_ptr();
    let f: CxInstantiateAtFn = unsafe { std::mem::transmute(raw) };

    let bd = CxBinderData { info: 0, mult: 2 };
    let bv = |i: u32| CxExpr::bvar(i);
    let app = |x: CxExpr, y: CxExpr| CxExpr::app(x, y);
    let lam = |t: CxExpr, b: CxExpr| CxExpr::lam(bd, t, b);
    let pi = |t: CxExpr, b: CxExpr| CxExpr::pi(bd, t, b);
    let lett = |t: CxExpr, v: CxExpr, b: CxExpr| CxExpr::lett(CxName(0), t, v, b, false);
    let proj = |i: u32, e: CxExpr| CxExpr::proj(CxName(1), i, e);

    let val_const = || CxExpr::from_kind(CxExprKind::Const(CxName(9), vec![])); // closed: lift is a no-op
    let val_open = || bv(0); // has a loose BVar(0) -> lift_at(0, depth) shifts it

    let cases: Vec<(CxExpr, CxExpr, u32, &str)> = vec![
        (
            bv(0),
            val_const(),
            0,
            "BVar0 := const (closed val, beta hit)",
        ),
        (
            bv(2),
            val_const(),
            0,
            "BVar2 at depth0 -> decrement to BVar1",
        ),
        (
            bv(0),
            val_const(),
            2,
            "BVar0 at depth2 -> unchanged (early guard clone)",
        ),
        (
            app(bv(0), bv(2)),
            val_const(),
            0,
            "App(BVar0:=val, BVar2->BVar1)",
        ),
        (
            app(bv(1), bv(0)),
            val_const(),
            1,
            "App at depth1 (BVar1:=val, BVar0 below)",
        ),
        (proj(3, bv(0)), val_const(), 0, "Proj over BVar0 := val"),
        (
            lett(bv(0), bv(1), bv(2)),
            val_const(),
            0,
            "Let(ty=BVar0:=val, val=BVar1->BVar0, body=BVar2 at depth1)",
        ),
        (
            app(bv(3), bv(4)),
            val_const(),
            10,
            "depth10 > range -> whole clone (no-op)",
        ),
        (
            lam(bv(0), app(bv(0), bv(1))),
            val_open(),
            0,
            "instantiate(Lam(App(BVar0,BVar1)), open-val) — under-binder lift fires",
        ),
        (
            pi(bv(0), app(bv(0), bv(1))),
            val_open(),
            0,
            "instantiate(Pi(App(BVar0,BVar1)), open-val) — under-binder lift",
        ),
        (
            lam(bv(0), lam(bv(0), app(bv(2), bv(0)))),
            val_open(),
            0,
            "double-Lam telescope: BVar2 := val lifted by 2",
        ),
        (
            app(lam(bv(0), bv(1)), pi(bv(0), bv(1))),
            val_open(),
            0,
            "App(Lam,Pi) both substitute outer BVar with lifted val",
        ),
    ];

    let mut pass = 0usize;
    for (body, val, depth, label) in &cases {
        let native = body.instantiate_at(val, *depth);
        let mut jit_out = std::mem::MaybeUninit::<CxExpr>::uninit();
        let bp: *const CxExpr = body as *const CxExpr;
        let vp: *const CxExpr = val as *const CxExpr;
        let jit = unsafe {
            f(jit_out.as_mut_ptr(), bp, vp, *depth);
            jit_out.assume_init()
        };
        assert!(
            cx_deep_eq(&native, &jit),
            "MIR-emitted Expr-BETA-SUBSTITUTION JIT disagrees with native Rust on `{label}`:\n  native = {native:?}\n  jit    = {jit:?}"
        );
        assert_eq!(
            native.meta.raw(),
            jit.meta.raw(),
            "top-level compute_meta word disagrees on `{label}`"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all Expr beta-substitution cases must agree native == JIT (structure + meta word)"
    );
    drop(buffer);
}

