    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRNtCskchLIXKnH0y_21clean_expr_whnf_slice6FVarIdNtB7_9PartialEq2eqBF_".to_string(), cw_shim_fvarid_eq as *const u8);
    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRNtCskchLIXKnH0y_21clean_expr_whnf_slice7LiteralNtB7_9PartialEq2eqBF_".to_string(), cw_shim_lit_eq as *const u8);
    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRmNtB7_9PartialEq2eqCskchLIXKnH0y_21clean_expr_whnf_slice".to_string(), cw_shim_u32ref_eq as *const u8);

