    externs.insert("_RNvXs7_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCs2YOnePBWmIc_22clean_expr_infer_slice5LevelENtNtNtCs2EYQwhfuABO_4core3ops5deref5Deref5derefBH_".to_string(), cw_shim_vec_lvl_deref as *const u8);
    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRNtCs2YOnePBWmIc_22clean_expr_infer_slice4NameNtB7_9PartialEq2eqBF_".to_string(), cw_shim_name_eq as *const u8);
