    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRNtCs2YOnePBWmIc_22clean_expr_infer_slice7LiteralNtB7_9PartialEq2eqBF_".to_string(), cw_shim_lit_eq as *const u8);
    externs.insert("_RNvXs7_NtNtCs2EYQwhfuABO_4core3cmp5implsRmNtB7_9PartialEq2eqCs2YOnePBWmIc_22clean_expr_infer_slice".to_string(), cw_shim_u32ref_eq as *const u8);
    // NEW leaves beyond the def_eq set: Vec::pop, Vec::<Level>::new, Box::<Level>::new,
    // and the `?`-operator Try::branch / FromResidual::from_residual on Result<Expr,_>.
    externs.insert("_RNvMs_NtCskTzINo8ZBH9_5alloc3vecINtB4_3VecNtCs2YOnePBWmIc_22clean_expr_infer_slice4ExprE3popBG_".to_string(), cw_shim_vec_pop as *const u8);
