/// The mangled symbol of the sole leaf extern `@func.2` = `core::num::<u64>::
/// wrapping_mul`. Bound to a native shim (carries the slice's crate hash; refresh
/// on regen).
const EXT_WRAPPING_MUL: &str = "_RNvMs7_NtCs2EYQwhfuABO_4core3numy12wrapping_mul";

/// Native shim for `u64::wrapping_mul` — the JIT analog of the linked-symbol path.
extern "C" fn shim_u64_wrapping_mul(a: u64, b: u64) -> u64 {
    a.wrapping_mul(b)
}

/// The REAL clean cfg(kani) `KaniHasher` (expr/meta.rs:285) — the NATIVE oracle.
/// FxHash-style multiply-XOR. `write_u64` is verbatim the body the IR lowered.
struct MkhKaniHasher {
    state: u64,
}
impl MkhKaniHasher {
    fn new() -> Self {
        MkhKaniHasher { state: 0 }
    }
    fn write_u64(&mut self, i: u64) {
        self.state ^= i;
        self.state = self.state.wrapping_mul(0x517cc1b727220a95);
    }
    fn finish(&self) -> u64 {
        self.state
    }
}

/// Native `make_hash_direct(&Name) -> u64` oracle: the exact arithmetic the env-key
/// hash performs (a `Name(u64)`'s derived Hash writes its one u64 field via write_u64).
fn mkh_native(name_field: u64) -> u64 {
    let mut h = MkhKaniHasher::new();
    h.write_u64(name_field);
    h.finish()
}

/// Rust `make_hash_direct(&Name) -> u64` (the real env-key hash, KaniHasher) -> MIR
/// -> trust-ir (stage1 `--mir-emit-closure`) -> trust-cg JIT -> machine code ==
/// native Rust, over N concrete keys. This VERIFIES the deterministic hash sub-step
/// of the real `HashMap::get` lookup (the SwissTable group-scan itself does NOT lower
/// — it bottoms out at NEON `simd_eq`, a bodiless `#[rustc_intrinsic]`; see the header).
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_env_key_make_hash_kanihasher_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "mir_env_key_make_hash_kanihasher_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(MIR_MAKE_HASH_TRUST_IR)
        .expect("MIR-emitted `make_hash_direct` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(
        EXT_WRAPPING_MUL.to_string(),
        shim_u64_wrapping_mul as *const u8,
    );
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted `make_hash_direct` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("make_hash_direct")
        .expect("JIT symbol `make_hash_direct` not found")
        .as_ptr();
    // SAFETY: machine code for a `(*const Name) -> u64` fn (Name = #[repr] {u64});
    // a thin `&Name` pointer is the u64-field address. Buffer held live.
    let f: extern "C" fn(*const u64) -> u64 = unsafe { std::mem::transmute(raw) };

    // A spread of env-key field values: 0, small, powers of two, large, the kind of
    // interned-Name handles a real Environment lookup hashes.
    let keys: [u64; 12] = [
        0,
        1,
        2,
        42,
        255,
        256,
        0xDEAD_BEEF,
        0x0000_0001_0000_0000,
        0x517c_c1b7_2722_0a95,
        u64::MAX,
        0x8000_0000_0000_0000,
        12345678901234567,
    ];

    let mut pass = 0usize;
    for &k in &keys {
        let native = mkh_native(k);
        // The JIT takes `&Name`; `Name` is a single-u64 struct, so the field address
        // IS the struct address. Pass a pointer to the u64 key.
        let kk = k;
        let jit = f(&kk as *const u64);
        assert_eq!(
            native, jit,
            "MIR-emitted JIT make_hash disagrees with native KaniHasher on key {k:#x}: \
             native={native:#x} jit={jit:#x}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        keys.len(),
        "all env-key hashes must agree native == JIT"
    );
    drop(buffer);
}

