#[derive(Clone, Debug, PartialEq, Eq, Hash)]
#[allow(dead_code)]
enum CyLevel {
    Zero,
    Succ(Box<CyLevel>),
    Param(CyName),
}

#[allow(dead_code)]
impl CyLevel {
    fn has_params(&self) -> bool {
        match self {
            CyLevel::Zero => false,
            CyLevel::Succ(l) => l.has_params(),
            CyLevel::Param(_) => true,
        }
    }
    fn is_def_eq(l1: &CyLevel, l2: &CyLevel) -> bool {
        match (l1, l2) {
            (CyLevel::Zero, CyLevel::Zero) => true,
            (CyLevel::Succ(a), CyLevel::Succ(b)) => CyLevel::is_def_eq(a, b),
            (CyLevel::Param(a), CyLevel::Param(b)) => a.0 == b.0,
            _ => false,
        }
    }
    fn succ(l: CyLevel) -> CyLevel {
        CyLevel::Succ(Box::new(l))
    }
    fn imax(u: CyLevel, v: CyLevel) -> CyLevel {
        if CyLevel::is_zero(&v) {
            return CyLevel::Zero;
        }
        CyLevel::max(u, v)
    }
    fn is_zero(l: &CyLevel) -> bool {
        matches!(l, CyLevel::Zero)
    }
    fn depth(l: &CyLevel) -> u32 {
        match l {
            CyLevel::Zero => 0,
            CyLevel::Succ(inner) => 1 + CyLevel::depth(inner),
            CyLevel::Param(_) => 0,
        }
    }
    fn of_depth(d: u32) -> CyLevel {
        if d == 0 {
            CyLevel::Zero
        } else {
            CyLevel::Succ(Box::new(CyLevel::of_depth(d - 1)))
        }
    }
    fn max(u: CyLevel, v: CyLevel) -> CyLevel {
        match (&u, &v) {
            (CyLevel::Param(_), _) | (_, CyLevel::Param(_)) => u,
            _ => CyLevel::of_depth(CyLevel::depth(&u).max(CyLevel::depth(&v))),
        }
    }
    fn substitute_params(&self, params: &[CyName], levels: &[CyLevel]) -> CyLevel {
        match self {
            CyLevel::Zero => CyLevel::Zero,
            CyLevel::Succ(inner) => {
                CyLevel::Succ(Box::new(inner.substitute_params(params, levels)))
            }
            CyLevel::Param(n) => {
                let mut i = 0usize;
                while i < params.len() {
                    if params[i].0 == n.0 {
                        return levels[i].clone();
                    }
                    i += 1;
                }
                CyLevel::Param(*n)
            }
        }
    }
}

