// Arc<Expr>::clone drifted ABI across the generation toolchains. Stable fixture:
// the older frontend emitted the sret form `(sret, this) -> ()`. Trust fixture:
// the current frontend emits register-return `(this) -> ptr` — Arc<Expr> is
// pointer-sized (8 B = NonNull<ArcInner>), so the AArch64 ABI returns it in x0,
// not via an sret out-pointer. The raw Arc value is the ArcInner base
// (= data_ptr - 16, matching the +16 in cy_shim_arc_as_ref); into_raw keeps the
// strong count this clone just incremented. The shim ABI must match the compiled
// fixture — these are used ONLY by the two gated cy_ tests, so cfg-select both.
#[cfg(kernel_fixture_layout_matches)]
extern "C" fn cy_shim_arc_clone(
    sret: *mut std::sync::Arc<CyExpr>,
    this: *const std::sync::Arc<CyExpr>,
) {
    unsafe {
        std::ptr::write(sret, std::sync::Arc::clone(&*this));
    }
}
#[cfg(not(kernel_fixture_layout_matches))]
extern "C" fn cy_shim_arc_clone(this: *const std::sync::Arc<CyExpr>) -> *const CyExpr {
    unsafe {
        let data = std::sync::Arc::into_raw(std::sync::Arc::clone(&*this)) as *const u8;
        data.sub(16) as *const CyExpr
    }
}
extern "C" fn cy_shim_arc_as_ref(arc_ref: *const *const u8) -> *const CyExpr {
    unsafe { (*arc_ref).add(16) as *const CyExpr }
}
