extern "C" fn cy_shim_result_branch(
    sret: *mut std::ops::ControlFlow<Result<std::convert::Infallible, CyTypeError>, CyExpr>,
    this: *const Result<CyExpr, CyTypeError>,
) {
    unsafe {
        let cf = match std::ptr::read(this) {
            Ok(v) => std::ops::ControlFlow::Continue(v),
            Err(e) => std::ops::ControlFlow::Break(Err(e)),
        };
        std::ptr::write(sret, cf);
    }
}
extern "C" fn cy_shim_result_from_residual(
    sret: *mut Result<CyExpr, CyTypeError>,
    residual: *const Result<std::convert::Infallible, CyTypeError>,
) {
    unsafe {
        let err = match std::ptr::read(residual) {
            Ok(_) => unreachable!("Infallible residual"),
            Err(e) => e,
        };
        std::ptr::write(sret, Err(err));
    }
}
const CY_KANI_MAGIC: u64 = 0x517cc1b727220a95;
extern "C" fn cy_shim_hash_u32(value: *const u32, state: *mut u64) {
    unsafe {
        let i = *value as u64;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CY_KANI_MAGIC);
    }
}
extern "C" fn cy_shim_hash_u64(value: *const u64, state: *mut u64) {
    unsafe {
        let i = *value;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CY_KANI_MAGIC);
    }
}
extern "C" fn cy_shim_hash_i32(value: *const i32, state: *mut u64) {
    unsafe {
        let i = (*value as u32) as u64;
        let s = (*state) ^ i;
        *state = s.wrapping_mul(CY_KANI_MAGIC);
    }
}
extern "C" fn cy_shim_hash_box_level(boxptr: *const Box<CyLevel>, state: *mut u64) {
    use std::hash::{Hash, Hasher};
    unsafe {
        let lvl: &CyLevel = &*(boxptr);
        let mut h = CyKaniHasher { state: *state };
        lvl.hash(&mut h);
        *state = h.finish();
    }
}
