    externs.insert(
        format!(
            "_RINvXsa_NtNtCs2EYQwhfuABO_4core4hash5implsyNtB8_4Hash4hashNt{hash}10KaniHasherEBW_"
        ),
        cy_shim_hash_u64 as *const u8,
    );
    externs.insert(
        format!(
            "_RINvXsg_NtNtCs2EYQwhfuABO_4core4hash5implsiNtB8_4Hash4hashNt{hash}10KaniHasherEBW_"
        ),
        cy_shim_hash_i32 as *const u8,
    );
    externs.insert(format!("_RINvXsk_NtCskTzINo8ZBH9_5alloc5boxedINtB6_3BoxNt{hash}5LevelENtNtCs2EYQwhfuABO_4core4hash4Hash4hashNtBK_10KaniHasherEBK_"), cy_shim_hash_box_level as *const u8);
