// ── The `Ty` enum, BYTE-IDENTICAL to the production trust-ir `Ty`
//    (trust-ir/crates/trust-ir/src/ty.rs:55-131) and to the slice. The variant
//    SET and ORDER must match exactly so rustc niche-encodes the discriminant the
//    same way the emitted IR decodes it. The id newtypes / inline enums are the
//    same `pub struct $name(pub u32)` / enum shapes. ──
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfStructId(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfTyId(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfFuncTyId(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfEnumId(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfRecordId(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfClosureTyId(pub u32);

// `#[allow(dead_code)]`: several variants/fields below are never CONSTRUCTED in
// this test, but they MUST exist so rustc niche-encodes `TfTy`'s discriminant
// byte-identically to the production `Ty` the emitted IR decodes. Removing them
// would change the layout and break the round-trip; the attribute does not.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum TfSetRepr {
    Bitset,
    #[default]
    Boxed,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TfFatPtrKind {
    Slice(TfTyId),
    Str,
    TraitObject { trait_id: u32 },
}

#[allow(dead_code)]
#[derive(Debug, Clone, PartialEq, Eq)]
enum TfTy {
    I8,
    I16,
    I32,
    I64,
    I128,
    U8,
    U16,
    U32,
    U64,
    U128,
    F16,
    F32,
    F64,
    Bool,
    Vector(Box<TfTy>, u32),
    Ptr,
    FatPtr(TfFatPtrKind),
    Unit,
    Never,
    Struct(TfStructId),
    Array(TfTyId, u64),
    Tuple(Vec<TfTy>),
    Enum(TfEnumId),
    Func(TfFuncTyId),
    Ref(Box<TfTy>),
    RefMut(Box<TfTy>),
    PtrConst(Box<TfTy>),
    PtrMut(Box<TfTy>),
    Rc(Box<TfTy>),
    Set(TfTyId, TfSetRepr),
    Sequence(TfTyId),
    Record(TfRecordId),
    Closure(TfClosureTyId),
}

/// Native oracle — VERBATIM `int_value_fits_ty` (shape.rs:1005-1019), over `TfTy`.
fn int_value_fits_ty_native(value: i128, ty: &TfTy) -> bool {
    match ty {
        TfTy::I8 => value >= i8::MIN as i128 && value <= i8::MAX as i128,
        TfTy::I16 => value >= i16::MIN as i128 && value <= i16::MAX as i128,
        TfTy::I32 => value >= i32::MIN as i128 && value <= i32::MAX as i128,
        TfTy::I64 => value >= i64::MIN as i128 && value <= i64::MAX as i128,
        TfTy::I128 => true,
        TfTy::U8 => value >= 0 && value <= u8::MAX as i128,
        TfTy::U16 => value >= 0 && value <= u16::MAX as i128,
        TfTy::U32 => value >= 0 && value <= u32::MAX as i128,
        TfTy::U64 => value >= 0 && value <= u64::MAX as i128,
        TfTy::U128 => value >= 0,
        _ => false,
    }
}

/// `(i128, *const TfTy) -> bool` as AAPCS64 sees the emitted `@int_value_fits_ty`.
/// The i128 value is passed by value (register pair); `&Ty` is a thin pointer.
type IntFitsFn = extern "C" fn(i128, *const TfTy) -> bool;

/// TRUST-SELF FOOTHOLD: the production trust-ir `int_value_fits_ty` -> MIR ->
/// trust-ir (stage1 `--mir-emit-closure`) -> trust-cg JIT -> machine code ==
/// native Rust, over (value, Ty) pairs that exercise EVERY arm and the inclusive
/// boundary of every integer width. This is the first verification of a function
/// of TRUST's OWN compiler toolchain by executed machine code: the method that
/// verified the clean kernel now applies to Trust itself.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_int_value_fits_ty_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_int_value_fits_ty_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_INT_FITS_TRUST_IR)
        .expect("MIR-emitted `int_value_fits_ty` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `int_value_fits_ty` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("int_value_fits_ty")
        .expect("JIT symbol `int_value_fits_ty` not found")
        .as_ptr();
    // SAFETY: machine code for a `(i128, *const TfTy) -> bool` fn; buffer held live.
    let f: IntFitsFn = unsafe { std::mem::transmute(raw) };

    // (value, Ty, label). Covers: every integer arm, both inclusive boundaries
    // (fit and just-past), the unsigned `>= 0` lower bound, the always-true i128
    // arm, and several non-integer arms that must take the `_ => false` path.
    let cases: Vec<(i128, TfTy, &str)> = vec![
        // i8: [-128, 127]
        (127, TfTy::I8, "127:i8"),
        (128, TfTy::I8, "128:i8"),
        (-128, TfTy::I8, "-128:i8"),
        (-129, TfTy::I8, "-129:i8"),
        // i16: [-32768, 32767]
        (32767, TfTy::I16, "32767:i16"),
        (32768, TfTy::I16, "32768:i16"),
        (-32768, TfTy::I16, "-32768:i16"),
        (-32769, TfTy::I16, "-32769:i16"),
        // i32
        (2147483647, TfTy::I32, "i32::MAX:i32"),
        (2147483648, TfTy::I32, "i32::MAX+1:i32"),
        (-2147483648, TfTy::I32, "i32::MIN:i32"),
        (-2147483649, TfTy::I32, "i32::MIN-1:i32"),
        // i64
        (i64::MAX as i128, TfTy::I64, "i64::MAX:i64"),
        (i64::MAX as i128 + 1, TfTy::I64, "i64::MAX+1:i64"),
        (i64::MIN as i128, TfTy::I64, "i64::MIN:i64"),
        (i64::MIN as i128 - 1, TfTy::I64, "i64::MIN-1:i64"),
        // i128: always true
        (i128::MAX, TfTy::I128, "i128::MAX:i128"),
        (i128::MIN, TfTy::I128, "i128::MIN:i128"),
        (0, TfTy::I128, "0:i128"),
        // u8: [0, 255]
        (0, TfTy::U8, "0:u8"),
        (255, TfTy::U8, "255:u8"),
        (256, TfTy::U8, "256:u8"),
        (-1, TfTy::U8, "-1:u8"),
        // u16
        (65535, TfTy::U16, "u16::MAX:u16"),
        (65536, TfTy::U16, "u16::MAX+1:u16"),
        (-1, TfTy::U16, "-1:u16"),
        // u32
        (4294967295, TfTy::U32, "u32::MAX:u32"),
        (4294967296, TfTy::U32, "u32::MAX+1:u32"),
        (-1, TfTy::U32, "-1:u32"),
        // u64
        (u64::MAX as i128, TfTy::U64, "u64::MAX:u64"),
        (u64::MAX as i128 + 1, TfTy::U64, "u64::MAX+1:u64"),
        (-1, TfTy::U64, "-1:u64"),
        // u128: only `>= 0`
        (i128::MAX, TfTy::U128, "i128::MAX:u128"),
        (0, TfTy::U128, "0:u128"),
        (-1, TfTy::U128, "-1:u128"),
        // Non-integer arms -> `_ => false`, regardless of value.
        (0, TfTy::Bool, "0:bool"),
        (1, TfTy::F32, "1:f32"),
        (5, TfTy::Ptr, "5:ptr"),
        (0, TfTy::Unit, "0:unit"),
        (0, TfTy::Never, "0:never"),
        (0, TfTy::Vector(Box::new(TfTy::I32), 4), "0:<4 x i32>"),
        (0, TfTy::Struct(TfStructId(0)), "0:struct"),
        (0, TfTy::FatPtr(TfFatPtrKind::Str), "0:fatptr"),
        (0, TfTy::Closure(TfClosureTyId(0)), "0:closure"),
    ];

    let mut pass = 0usize;
    for (value, ty, label) in &cases {
        let native = int_value_fits_ty_native(*value, ty);
        // SAFETY: the JIT reads `&Ty` the same byte layout the native value has.
        let jit = f(*value, ty as *const TfTy);
        assert_eq!(
            native, jit,
            "TRUST-SELF int_value_fits_ty JIT machine code disagrees with native \
             Rust on `{label}` (value={value}): native={native} jit={jit}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all int_value_fits_ty cases must agree native == JIT"
    );

    // NEGATIVE CONTROL: corrupt the native oracle's bound (i8 upper bound widened
    // to i16) and confirm it now DISAGREES with the JIT on a value that fits i16
    // but not i8 — proving the test actually discriminates the bound, i.e. it is
    // not vacuously passing.
    fn int_value_fits_ty_corrupt(value: i128, ty: &TfTy) -> bool {
        match ty {
            // Bug: i8 upper bound widened to i16::MAX (should be i8::MAX).
            TfTy::I8 => value >= i8::MIN as i128 && value <= i16::MAX as i128,
            _ => int_value_fits_ty_native(value, ty),
        }
    }
    let corrupt = int_value_fits_ty_corrupt(200, &TfTy::I8); // corrupt says true
    let jit_200_i8 = f(200, &TfTy::I8 as *const TfTy); // real JIT says false (200 > 127)
    assert_ne!(
        corrupt, jit_200_i8,
        "negative control must FAIL: a corrupted bound should disagree with the JIT"
    );
    assert!(!jit_200_i8, "JIT must reject 200 as not fitting i8");

    drop(buffer);
}

// ============================================================================
// TRUST-SELF FOOTHOLD — BATCH 2: three more functions of TRUST's OWN toolchain,
// all from the trust-ir ALLOCATION-BOUNDS analyzer and the shape/layout module,
// lowered by the SAME stage1 MIR path (`trust_ir_mir --mir-emit-closure`) that
// carried the clean kernel and the `int_value_fits_ty` foothold above. Each is a
// PURE, deterministic, closure-free function transcribed VERBATIM from source;
// native Rust is the oracle and JIT-compiled machine code must agree.
//
//   * `swap_cmp`   (alloc_bound.rs:450) — the operand-swap law of comparisons.
//   * `type_max`   (alloc_bound.rs:306) — largest unsigned value in `bits` bits.
//   * `total_bits` (shape.rs:300)       — pointer-value total width (thin/fat).
//
// REGEN (per fn):
//   S=$HOME/trust/build/aarch64-apple-darwin/stage1
//   cd $HOME/trust-ir/frontend && env -u RUSTUP_TOOLCHAIN RUSTC=$S/bin/rustc \
//     DYLD_LIBRARY_PATH=$S/lib/rustlib/aarch64-apple-darwin/lib \
//     target/debug/trust_ir_mir <slice.rs> --crate-type=lib \
//     --mir-emit-closure <fn> <out.tir>
// Slices: dev-scratch/trust_swap_cmp_slice.rs, trust_type_max_slice.rs,
//         trust_total_bits_slice.rs.

// ── swap_cmp ────────────────────────────────────────────────────────────────
// `swap_cmp(op)` is the `c` such that `K op count` ≡ `count c K` — the trust-ir
// guard pass (`guard_count_bound`, alloc_bound.rs:402) uses it to normalize a
// guard written `K <op> count` into `count <swap_cmp(op)> K`. A total 10-arm
// match over `ICmpOp` returning an `ICmpOp`. The emit reported:
//   EMIT-CLOSURE-OK swap_cmp: 947 bytes; validate_module = 0 error(s); re-parse OK
//
// ABI (read off the IR): `(ptr, ptr) -> ()`. The result `ICmpOp` is returned
// THROUGH an out-pointer `%0` (a 1-byte enum); the input `ICmpOp` is read through
// `%1`. The body loads the i8 discriminant, `switch`es all 10 arms, stores the
// swapped discriminant. Fully self-contained (NO external leaves).
const MIR_SWAP_CMP_TRUST_IR: &str = r#"; TrustIr text format v1
module "mir::closure::swap_cmp"

functy.0 = (ptr, u8) -> ()

fn @swap_cmp(functy.0) {
bb0(%0: ptr, %1: u8):
    %2 = alloca i8, align 1
    store u8 %1, ptr %2
    %3 = load i8, ptr %2
    %4 = sext i8 %3 to i64
    switch %4 [ 0: bb3 1: bb2 2: bb11 3: bb10 4: bb9 5: bb8 6: bb7 7: bb6 8: bb5 9: bb4 default: bb1 ]
bb1:
    unreachable
bb2:
    %5 = const i8 1
    store i8 %5, ptr %0
    br bb12
bb3:
    %6 = const i8 0
    store i8 %6, ptr %0
    br bb12
bb4:
    %7 = const i8 7
    store i8 %7, ptr %0
    br bb12
bb5:
    %8 = const i8 6
    store i8 %8, ptr %0
    br bb12
bb6:
    %9 = const i8 9
    store i8 %9, ptr %0
    br bb12
bb7:
    %10 = const i8 8
    store i8 %10, ptr %0
    br bb12
bb8:
    %11 = const i8 3
    store i8 %11, ptr %0
    br bb12
bb9:
    %12 = const i8 2
    store i8 %12, ptr %0
    br bb12
bb10:
    %13 = const i8 5
    store i8 %13, ptr %0
    br bb12
bb11:
    %14 = const i8 4
    store i8 %14, ptr %0
    br bb12
bb12:
    ret
}
"#;

// `ICmpOp`, BYTE-IDENTICAL to the production trust-ir `ICmpOp` (inst.rs:75-86):
// the variant SET and ORDER must match so rustc niche-encodes the i8 discriminant
// the same way the emitted IR decodes/encodes it.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TfICmpOp {
    Eq,
    Ne,
    Ult,
    Ule,
    Ugt,
    Uge,
    Slt,
    Sle,
    Sgt,
    Sge,
}

/// Native oracle — VERBATIM `swap_cmp` (alloc_bound.rs:450-463), over `TfICmpOp`.
fn swap_cmp_native(op: TfICmpOp) -> TfICmpOp {
    match op {
        TfICmpOp::Ult => TfICmpOp::Ugt,
        TfICmpOp::Ule => TfICmpOp::Uge,
        TfICmpOp::Ugt => TfICmpOp::Ult,
        TfICmpOp::Uge => TfICmpOp::Ule,
        TfICmpOp::Slt => TfICmpOp::Sgt,
        TfICmpOp::Sle => TfICmpOp::Sge,
        TfICmpOp::Sgt => TfICmpOp::Slt,
        TfICmpOp::Sge => TfICmpOp::Sle,
        TfICmpOp::Eq => TfICmpOp::Eq,
        TfICmpOp::Ne => TfICmpOp::Ne,
    }
}

/// `(out: *mut TfICmpOp, in: *const TfICmpOp) -> ()` — the AAPCS64 view of the
/// emitted `@swap_cmp` (result returned through the out-pointer).
// `swap_cmp(op: ICmpOp)` takes its arg BY VALUE. `ICmpOp` is a fieldless enum with a
// single-scalar (i8 discriminant) layout, so the frontend's faithful by-value newtype
// ABI passes it as a `u8` (the discriminant), not by reference — hence `u8` here.
type SwapCmpFn = extern "C" fn(*mut TfICmpOp, u8);

/// TRUST-SELF (batch 2): the production trust-ir `swap_cmp` -> MIR -> trust-ir
/// (stage1 `--mir-emit-closure`) -> trust-cg JIT -> machine code == native Rust,
/// over EVERY one of the 10 `ICmpOp` arms (the strict/reversed pairs and the Eq/Ne
/// fixed points). Exercises returning an ENUM VALUE (niche-encoded discriminant on
/// the RESULT), a different lowering surface from the bool/int predicates.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_swap_cmp_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_swap_cmp_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_SWAP_CMP_TRUST_IR)
        .expect("MIR-emitted `swap_cmp` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `swap_cmp` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("swap_cmp")
        .expect("JIT symbol `swap_cmp` not found")
        .as_ptr();
    // SAFETY: machine code for a `(*mut TfICmpOp, *const TfICmpOp) -> ()` fn.
    let f: SwapCmpFn = unsafe { std::mem::transmute(raw) };

    let all = [
        TfICmpOp::Eq,
        TfICmpOp::Ne,
        TfICmpOp::Ult,
        TfICmpOp::Ule,
        TfICmpOp::Ugt,
        TfICmpOp::Uge,
        TfICmpOp::Slt,
        TfICmpOp::Sle,
        TfICmpOp::Sgt,
        TfICmpOp::Sge,
    ];
    let mut pass = 0usize;
    for op in all {
        let native = swap_cmp_native(op);
        let mut out = TfICmpOp::Eq;
        // SAFETY: JIT writes one `TfICmpOp` (i8 discriminant) through `out`; `op` is
        // passed by value as its u8 discriminant.
        f(&mut out as *mut TfICmpOp, op as u8);
        assert_eq!(
            native, out,
            "TRUST-SELF swap_cmp JIT disagrees with native on `{op:?}`: \
             native={native:?} jit={out:?}"
        );
        // The swap is an involution: swap(swap(op)) == op. Check the JIT honors it.
        let mut out2 = TfICmpOp::Eq;
        f(&mut out2 as *mut TfICmpOp, out as u8);
        assert_eq!(out2, op, "swap_cmp must be an involution under the JIT");
        pass += 1;
    }
    assert_eq!(
        pass,
        all.len(),
        "all swap_cmp arms must agree native == JIT"
    );

    // NEGATIVE CONTROL: a corrupted oracle that fails to swap Ult (returns Ult)
    // must DISAGREE with the JIT (which returns Ugt) — proving discrimination.
    fn swap_cmp_corrupt(op: TfICmpOp) -> TfICmpOp {
        match op {
            TfICmpOp::Ult => TfICmpOp::Ult, // bug: should be Ugt
            other => swap_cmp_native(other),
        }
    }
    let mut jit_ult = TfICmpOp::Eq;
    f(&mut jit_ult as *mut TfICmpOp, TfICmpOp::Ult as u8);
    assert_ne!(
        swap_cmp_corrupt(TfICmpOp::Ult),
        jit_ult,
        "negative control must FAIL: corrupted swap should disagree with the JIT"
    );
    assert_eq!(jit_ult, TfICmpOp::Ugt, "JIT must swap Ult -> Ugt");

    drop(buffer);
}

// ── type_max ────────────────────────────────────────────────────────────────
// `type_max(bits)` = largest unsigned value in `bits` bits — the trust-ir
// allocation-bounds analyzer (`local_count_bound`, alloc_bound.rs:360) uses it to
// turn a narrow type's width into a max element count. A `bits >= 128` guard (it
// AVOIDS the `1u128 << 128` shift-overflow UB) over real u128 shift+subtract.
// The original emit reported 913 bytes; after canonical wide-constant migration
// the captured module validates and re-parses cleanly.
//
// CANONICAL WIDE CONSTANT: an older captured emit spelled `u128::MAX` as
// `const u128 -1`. TrustIr's v24 one-spelling rule correctly rejects that signed
// carrier for an unsigned type. The production MIR lowering now uses
// `Constant::u128`, so this fixture spells the positive magnitude; the parser
// represents it as `Constant::U128` and both validation and codegen agree.
//
// ABI (read off the IR): `(u32) -> (u128)`. The `bits: u32` in a register; the
// u128 result in a register pair. The body: `icmp uge u32 bits, 128` -> if true
// `const u128 u128::MAX`; else `zext bits to u128`, `shl 1u128`, then
// `sub.overflow u128 _, 1` with the `-1` overflow check INLINED (an `unreachable`
// on overflow) — fully self-contained, NO external leaves.
const MIR_TYPE_MAX_TRUST_IR: &str = r#"; TrustIr text format v1
module "mir::closure::type_max"

functy.0 = (u32) -> (u128)

fn @type_max(functy.0) {
bb0(%0: u32):
    %4 = alloca (i128, i128), align 16
    %5 = const u32 128
    %6 = icmp uge u32 %0, %5
    condbr %6, bb1, bb2(%0)
bb1:
    %7 = const u128 340282366920938463463374607431768211455
    br bb5(%7)
bb2(%1: u32):
    %8 = const u32 128
    %9 = icmp ult u32 %1, %8
    condbr %9, bb3(%1), bb6
bb3(%2: u32):
    %10 = const u128 1
    %11 = zext u32 %2 to u128
    %12 = shl u128 %10, %11
    %13 = const u128 1
    %14, %15 = sub.overflow u128 %12, %13
    store u128 %14, ptr %4
    %16 = const i64 16
    %17 = gep i8, ptr %4, %16
    store bool %15, ptr %17
    %18 = const i64 16
    %19 = gep i8, ptr %4, %18
    %20 = load bool, ptr %19
    %21 = const bool false
    %22 = icmp eq bool %20, %21
    condbr %22, bb4, bb6
bb4:
    %23 = load u128, ptr %4
    br bb5(%23)
bb5(%3: u128):
    ret %3
bb6:
    unreachable
}
"#;

/// Native oracle — VERBATIM `type_max` (alloc_bound.rs:305-312).
fn type_max_native(bits: u32) -> u128 {
    if bits >= 128 {
        u128::MAX
    } else {
        (1u128 << bits) - 1
    }
}

/// `(u32) -> u128` — the AAPCS64 view of the emitted `@type_max` (u128 result in a
/// register pair, returned directly).
type TypeMaxFn = extern "C" fn(u32) -> u128;

/// TRUST-SELF (batch 2): the production trust-ir `type_max` -> MIR -> trust-ir ->
/// trust-cg JIT -> machine code == native Rust, over the `bits >= 128` saturation
/// branch, the `bits < 128` shift+subtract branch, and the boundary (bits = 0,
/// 127, 128). Exercises real u128 shift/subtract arithmetic in the JIT.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_type_max_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_type_max_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_TYPE_MAX_TRUST_IR)
        .expect("MIR-emitted `type_max` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `type_max` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("type_max")
        .expect("JIT symbol `type_max` not found")
        .as_ptr();
    // SAFETY: machine code for a `(u32) -> u128` fn; buffer held live.
    let f: TypeMaxFn = unsafe { std::mem::transmute(raw) };

    // Every interesting width: 0, the small widths, each integer-type boundary,
    // 127 (max non-saturating), 128 (first saturating), and well past.
    let widths: [u32; 13] = [0, 1, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 200];
    let mut pass = 0usize;
    for &bits in &widths {
        let native = type_max_native(bits);
        let jit = f(bits);
        assert_eq!(
            native, jit,
            "TRUST-SELF type_max JIT disagrees with native on bits={bits}: \
             native={native:#x} jit={jit:#x}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        widths.len(),
        "all type_max widths must agree native == JIT"
    );
    // Spot-check the load-bearing values explicitly.
    assert_eq!(f(0), 0, "type_max(0) == 0");
    assert_eq!(f(8), 255, "type_max(8) == 255");
    assert_eq!(f(64), u64::MAX as u128, "type_max(64) == u64::MAX");
    assert_eq!(f(128), u128::MAX, "type_max(128) == u128::MAX (saturated)");
    assert_eq!(f(127), u128::MAX >> 1, "type_max(127) == u128::MAX >> 1");

    // NEGATIVE CONTROL: a corrupted oracle (saturates at >= 64 instead of >= 128)
    // must DISAGREE with the JIT for a width in [64, 128) — proving the JIT really
    // computes the shift and the test is not vacuous.
    fn type_max_corrupt(bits: u32) -> u128 {
        if bits >= 64 {
            u128::MAX // bug: should saturate only at >= 128
        } else {
            (1u128 << bits) - 1
        }
    }
    assert_ne!(
        type_max_corrupt(100),
        f(100),
        "negative control must FAIL: corrupted saturation should disagree with JIT"
    );
    assert_eq!(f(100), (1u128 << 100) - 1, "JIT must shift for bits=100");

    drop(buffer);
}

// ── total_bits ──────────────────────────────────────────────────────────────
// `PointerLayoutShape::total_bits` (shape.rs:300) = total in-register width of a
// pointer value: thin -> `data_bits`; fat -> `data_bits + metadata_bits` CHECKED
// for u32 overflow. The emit reported:
//   EMIT-CLOSURE-OK PointerLayoutShape::total_bits: 873 bytes; validate_module = 0;
//   re-parse OK
//
// DOCUMENTED SHIM (a real Trust finding): the emitted closure's ONLY external
// leaf is `core::num::<impl u32>::checked_add`, which the frontend lowers to an
// EMPTY function body (`fn @...checked_add(functy.0) {}`) — a `core` intrinsic
// leaf is not lowered. So the round-trip requires a faithful trust-ir body for
// `checked_add`, modeled here EXACTLY like the clean-kernel rung shims. The shim
// matches the `Option<u32>` ABI the caller reads off the emitted `total_bits`
// body (read from its `Some` arm bb2): an 8-byte `Option<u32>` laid out as
// {tag: i32 @offset 0 (1=Some, 0=None), payload: u32 @offset 4}. The shim does a
// real `add.overflow u32` and writes that exact layout. EVERYTHING ELSE — the
// discriminant read of `metadata_bits`, the thin/fat switch, the field GEPs, the
// call wiring — is the VERBATIM emitted `total_bits`; only the `checked_add` leaf
// is the shim, and its correctness is independently obvious (and the negative
// control corrupts it to prove the test discriminates).
//
// ABI (read off the IR): `total_bits` is `(ptr, ptr) -> ()` — `Option<u32>`
// result through out-ptr `%0` (tag @0, payload @4); `&PointerLayoutShape` is `%1`
// (data_bits @0; metadata_bits Option<u32> as {tag @0, payload @4 within the
// field}; etc.). `checked_add` is `(ptr, u32, u32) -> ()`.
const MIR_TOTAL_BITS_TRUST_IR: &str = r#"; TrustIr text format v1
module "mir::closure::PointerLayoutShape::total_bits"

functy.0 = (ptr, u32, u32) -> ()

functy.1 = (ptr, ptr) -> ()

fn @checked_add_shim(functy.0) {
bb0(%0: ptr, %1: u32, %2: u32):
    %3, %4 = add.overflow u32 %1, %2
    %5 = const bool false
    %6 = icmp eq bool %4, %5
    condbr %6, bb1, bb2
bb1:
    %7 = const i32 1
    store i32 %7, ptr %0
    %8 = const i64 4
    %9 = gep i8, ptr %0, %8
    store u32 %3, ptr %9
    br bb3
bb2:
    %10 = const i32 0
    store i32 %10, ptr %0
    br bb3
bb3:
    ret
}

fn @PointerLayoutShape__total_bits(functy.1) {
bb0(%0: ptr, %1: ptr):
    %2 = load i32, ptr %1
    %3 = sext i32 %2 to i64
    switch %3 [ 0: bb2 1: bb3 default: bb1 ]
bb1:
    unreachable
bb2:
    %4 = const i64 16
    %5 = gep i8, ptr %1, %4
    %6 = load u32, ptr %5
    %7 = const i64 4
    %8 = gep i8, ptr %0, %7
    store u32 %6, ptr %8
    %9 = const i32 1
    store i32 %9, ptr %0
    br bb4
bb3:
    %10 = const i64 4
    %11 = gep i8, ptr %1, %10
    %12 = load u32, ptr %11
    %13 = const i64 16
    %14 = gep i8, ptr %1, %13
    %15 = load u32, ptr %14
    call @func.0(%0, %15, %12)
    br bb4
bb4:
    ret
}
"#;

// `PointerLayoutShape` + `PointerMetadataShape`, BYTE-IDENTICAL to production
// (shape.rs:224-230, 267-273), so rustc lays the struct/Option fields out the way
// the emitted IR's GEP offsets (0, 4, 16) assume.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfTyIdTb(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TfPointerMetadataShape {
    SliceLen { elem: TfTyIdTb },
    StrLen,
    VTable { trait_id: u32 },
}
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfPointerLayoutShape {
    data_bits: u32,
    metadata_bits: Option<u32>,
    metadata: Option<TfPointerMetadataShape>,
}

/// Native oracle — VERBATIM `total_bits` (shape.rs:300-305).
fn total_bits_native(s: TfPointerLayoutShape) -> Option<u32> {
    match s.metadata_bits {
        Some(metadata_bits) => s.data_bits.checked_add(metadata_bits),
        None => Some(s.data_bits),
    }
}

/// `(out: *mut Option<u32>, shape: *const TfPointerLayoutShape) -> ()` — AAPCS64
/// view of the emitted `@total_bits` (Option<u32> result through out-ptr).
type TotalBitsFn = extern "C" fn(*mut Option<u32>, *const TfPointerLayoutShape);

/// TRUST-SELF (batch 2): the production trust-ir `PointerLayoutShape::total_bits`
/// -> MIR -> trust-ir -> trust-cg JIT -> machine code == native Rust, over thin
/// (None metadata), fat (Some metadata), and the `checked_add` OVERFLOW boundary
/// (u32::MAX + 1 -> None). The `checked_add` leaf is a documented shim (see the
/// IR comment); everything else is the verbatim emitted body. Exercises an
/// Option<u32> result through an out-pointer + a cross-function call.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_total_bits_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_total_bits_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_TOTAL_BITS_TRUST_IR)
        .expect("MIR-emitted `total_bits` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `total_bits` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("PointerLayoutShape__total_bits")
        .expect("JIT symbol `PointerLayoutShape__total_bits` not found")
        .as_ptr();
    // SAFETY: machine code for `(*mut Option<u32>, *const TfPointerLayoutShape)`.
    let f: TotalBitsFn = unsafe { std::mem::transmute(raw) };

    let meta = Some(TfPointerMetadataShape::VTable { trait_id: 0 });
    let cases: Vec<(TfPointerLayoutShape, &str)> = vec![
        // thin pointers (None metadata_bits) -> Some(data_bits)
        (
            TfPointerLayoutShape {
                data_bits: 64,
                metadata_bits: None,
                metadata: None,
            },
            "thin(64)",
        ),
        (
            TfPointerLayoutShape {
                data_bits: 0,
                metadata_bits: None,
                metadata: None,
            },
            "thin(0)",
        ),
        // fat pointers (Some metadata_bits) -> Some(data + meta), no overflow
        (
            TfPointerLayoutShape {
                data_bits: 64,
                metadata_bits: Some(64),
                metadata: meta,
            },
            "fat(64,64)",
        ),
        (
            TfPointerLayoutShape {
                data_bits: 32,
                metadata_bits: Some(0),
                metadata: meta,
            },
            "fat(32,0)",
        ),
        // checked_add OVERFLOW boundary -> None
        (
            TfPointerLayoutShape {
                data_bits: u32::MAX,
                metadata_bits: Some(1),
                metadata: meta,
            },
            "fat(MAX,1) overflow",
        ),
        (
            TfPointerLayoutShape {
                data_bits: u32::MAX,
                metadata_bits: Some(0),
                metadata: meta,
            },
            "fat(MAX,0) no-overflow",
        ),
    ];

    let mut pass = 0usize;
    for (shape, label) in &cases {
        let native = total_bits_native(*shape);
        let mut out: Option<u32> = Some(0xDEAD); // poison; the JIT must overwrite
        // SAFETY: JIT writes one `Option<u32>` through `out`.
        f(
            &mut out as *mut Option<u32>,
            shape as *const TfPointerLayoutShape,
        );
        assert_eq!(
            native, out,
            "TRUST-SELF total_bits JIT disagrees with native on `{label}`: \
             native={native:?} jit={out:?}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all total_bits cases must agree native == JIT"
    );

    // NEGATIVE CONTROL: corrupt the oracle's checked_add to a WRAPPING add (so the
    // overflow case returns Some(0) instead of None) — it must disagree with the
    // JIT (which correctly returns None), proving the test discriminates the
    // overflow path through the shim.
    fn total_bits_corrupt(s: TfPointerLayoutShape) -> Option<u32> {
        match s.metadata_bits {
            Some(metadata_bits) => Some(s.data_bits.wrapping_add(metadata_bits)), // bug
            None => Some(s.data_bits),
        }
    }
    let overflow = TfPointerLayoutShape {
        data_bits: u32::MAX,
        metadata_bits: Some(1),
        metadata: meta,
    };
    let mut jit_of: Option<u32> = Some(0xDEAD);
    f(
        &mut jit_of as *mut Option<u32>,
        &overflow as *const TfPointerLayoutShape,
    );
    assert_ne!(
        total_bits_corrupt(overflow),
        jit_of,
        "negative control must FAIL: a wrapping checked_add should disagree with JIT"
    );
    assert_eq!(jit_of, None, "JIT must return None on checked_add overflow");

    drop(buffer);
}

// ============================================================================
// TRUST-SELF FOOTHOLD — BATCH 3: three more functions of TRUST's OWN toolchain,
// lowered by the SAME stage1 MIR path (`trust_ir_mir --mir-emit-closure`) that
// carried the clean kernel and the earlier foothold batches. Each is PURE,
// deterministic, closure-free, transcribed VERBATIM from trust-ir source; native
// Rust is the oracle and the JIT-compiled machine code must agree.
//
//   * `FatPtrKind::metadata_shape` (shape.rs:243) — enum->enum with PAYLOADS
//     (Slice(elem)->SliceLen{elem}, TraitObject{id}->VTable{id}, Str->StrLen).
//   * `Ty::is_reference`           (ty.rs:338)    — wide `Ty` discriminant -> bool.
//   * `Ty::is_aggregate`           (ty.rs:356)    — wide `Ty` discriminant -> bool.
//
// `metadata_shape` is fully self-contained (NO external leaves). `is_reference`
// and `is_aggregate` lower the FAITHFUL niche-encoded `Ty` discriminant (the
// emitted IR decodes the high-i64 niche of the Box/Vec field into a canonical
// 0..32 tag via a compare/select chain, then a final `switch` over the matching
// arms) — NO shims, NO external leaves either.
//
// REGEN (per fn):
//   S=$HOME/trust/build/aarch64-apple-darwin/stage1
//   cd $HOME/trust-ir/frontend && env -u RUSTUP_TOOLCHAIN RUSTC=$S/bin/rustc \\
//     DYLD_LIBRARY_PATH=$S/lib/rustlib/aarch64-apple-darwin/lib \\
//     target/debug/trust_ir_mir <slice.rs> --crate-type=lib \\
//     --mir-emit-closure <root> <out.tir>
// Slices: dev-scratch/trust_metadata_shape_slice.rs (root metadata_shape_root),
//         trust_is_reference_slice.rs (root is_reference_root),
//         trust_is_aggregate_slice.rs (root is_aggregate_root).
// Emit reports:
//   EMIT-CLOSURE-OK metadata_shape_root: 1058 bytes; validate_module = 0; re-parse OK
//   EMIT-CLOSURE-OK is_reference_root:   4712 bytes; validate_module = 0; re-parse OK
//   EMIT-CLOSURE-OK is_aggregate_root:   4720 bytes; validate_module = 0; re-parse OK

// -- metadata_shape -----------------------------------------------------------
// `FatPtrKind::metadata_shape(&self) -> PointerMetadataShape` maps a fat-pointer
// KIND to the SHAPE of its metadata word. The emitted `@FatPtrKind__metadata_shape`
// is `(out: *mut PointerMetadataShape, in: *const FatPtrKind) -> ()`: it loads the
// i32 input tag, `switch`es 3 arms, copies any u32 payload (TyId / trait_id) from
// the input's @4 to the output's @4, and stores the output tag. The root wrapper
// `@metadata_shape_root` is `(ptr, ptr) -> ()` forwarding to it. Self-contained.
const MIR_METADATA_SHAPE_TRUST_IR: &str = r#"; TrustIr text format v1
module "mir::closure::metadata_shape_root"

functy.0 = (ptr, ptr) -> ()

functy.1 = (ptr, ptr) -> ()

fn @metadata_shape_root(functy.0) {
bb0(%0: ptr, %1: ptr):
    call @func.1(%0, %1)
    br bb1
bb1:
    ret
}

fn @FatPtrKind__metadata_shape(functy.1) {
bb0(%0: ptr, %1: ptr):
    %4 = alloca i32, align 4
    %5 = load i32, ptr %1
    %6 = sext i32 %5 to i64
    switch %6 [ 0: bb4(%1) 1: bb3 2: bb2(%1) default: bb1 ]
bb1:
    unreachable
bb2(%2: ptr):
    %7 = const i64 4
    %8 = gep i8, ptr %2, %7
    %9 = load u32, ptr %8
    %10 = const i64 4
    %11 = gep i8, ptr %0, %10
    store u32 %9, ptr %11
    %12 = const i32 2
    store i32 %12, ptr %0
    br bb5
bb3:
    %13 = const i32 1
    store i32 %13, ptr %0
    br bb5
bb4(%3: ptr):
    %14 = const i64 4
    %15 = gep i8, ptr %3, %14
    %16 = load i32, ptr %15
    store i32 %16, ptr %4
    %17 = const i64 4
    %18 = gep i8, ptr %0, %17
    %19 = load i32, ptr %4
    store i32 %19, ptr %18
    %20 = const i32 0
    store i32 %20, ptr %0
    br bb5
bb5:
    ret
}
"#;

// `FatPtrKind` + `PointerMetadataShape`, BYTE-IDENTICAL to production (ty.rs:39-43,
// shape.rs:226-230), so rustc lays the {tag@0, payload@4} layouts out the way the
// emitted IR's GEP offsets (0, 4) and tags (0=SliceLen,1=StrLen,2=VTable;
// 0=Slice,1=Str,2=TraitObject) assume.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TfTyIdMs(pub u32);
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TfFatPtrKindMs {
    Slice(TfTyIdMs),
    Str,
    TraitObject { trait_id: u32 },
}
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TfPointerMetadataShapeMs {
    SliceLen { elem: TfTyIdMs },
    StrLen,
    VTable { trait_id: u32 },
}

/// Native oracle -- VERBATIM `metadata_shape` (shape.rs:243-249), over the Tf types.
fn metadata_shape_native(k: TfFatPtrKindMs) -> TfPointerMetadataShapeMs {
    match k {
        TfFatPtrKindMs::Slice(elem) => TfPointerMetadataShapeMs::SliceLen { elem },
        TfFatPtrKindMs::Str => TfPointerMetadataShapeMs::StrLen,
        TfFatPtrKindMs::TraitObject { trait_id } => TfPointerMetadataShapeMs::VTable { trait_id },
    }
}

/// `(out: *mut PointerMetadataShape, in: *const FatPtrKind) -> ()` -- AAPCS64 view
/// of the emitted `@metadata_shape_root` (result through the out-pointer).
type MetadataShapeFn = extern "C" fn(*mut TfPointerMetadataShapeMs, *const TfFatPtrKindMs);

/// TRUST-SELF (batch 3): the production trust-ir `FatPtrKind::metadata_shape` ->
/// MIR -> trust-ir -> trust-cg JIT -> machine code == native Rust, over all three
/// `FatPtrKind` arms, INCLUDING the u32 payloads carried through (TyId for Slice,
/// trait_id for TraitObject). Exercises an enum->enum map that READS a payload off
/// the input and WRITES it into the output -- distinct from the fieldless swap_cmp.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_metadata_shape_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_metadata_shape_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_METADATA_SHAPE_TRUST_IR)
        .expect("MIR-emitted `metadata_shape` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `metadata_shape` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("metadata_shape_root")
        .expect("JIT symbol `metadata_shape_root` not found")
        .as_ptr();
    // SAFETY: machine code for `(*mut PointerMetadataShape, *const FatPtrKind)`.
    let f: MetadataShapeFn = unsafe { std::mem::transmute(raw) };

    let cases: Vec<(TfFatPtrKindMs, &str)> = vec![
        (TfFatPtrKindMs::Slice(TfTyIdMs(0)), "Slice(0)"),
        (TfFatPtrKindMs::Slice(TfTyIdMs(7)), "Slice(7)"),
        (TfFatPtrKindMs::Slice(TfTyIdMs(u32::MAX)), "Slice(MAX)"),
        (TfFatPtrKindMs::Str, "Str"),
        (TfFatPtrKindMs::TraitObject { trait_id: 0 }, "dyn.0"),
        (TfFatPtrKindMs::TraitObject { trait_id: 42 }, "dyn.42"),
        (
            TfFatPtrKindMs::TraitObject { trait_id: u32::MAX },
            "dyn.MAX",
        ),
    ];

    let mut pass = 0usize;
    for (kind, label) in &cases {
        let native = metadata_shape_native(*kind);
        // Poison the out slot so the JIT must overwrite both tag and payload.
        let mut out = TfPointerMetadataShapeMs::VTable { trait_id: 0xDEAD };
        // SAFETY: JIT writes one `PointerMetadataShape` through `out`.
        f(
            &mut out as *mut TfPointerMetadataShapeMs,
            kind as *const TfFatPtrKindMs,
        );
        assert_eq!(
            native, out,
            "TRUST-SELF metadata_shape JIT disagrees with native on `{label}`: \
             native={native:?} jit={out:?}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all metadata_shape cases must agree native == JIT"
    );

    // NEGATIVE CONTROL: a corrupted oracle that DROPS the Slice payload (always
    // elem=0) must DISAGREE with the JIT on `Slice(7)` (which carries 7 through) --
    // proving the test discriminates the payload copy, not just the tag.
    fn metadata_shape_corrupt(k: TfFatPtrKindMs) -> TfPointerMetadataShapeMs {
        match k {
            // bug: drops the real elem, hard-codes 0.
            TfFatPtrKindMs::Slice(_) => TfPointerMetadataShapeMs::SliceLen { elem: TfTyIdMs(0) },
            other => metadata_shape_native(other),
        }
    }
    let mut jit_slice7 = TfPointerMetadataShapeMs::VTable { trait_id: 0xDEAD };
    f(
        &mut jit_slice7 as *mut TfPointerMetadataShapeMs,
        &TfFatPtrKindMs::Slice(TfTyIdMs(7)) as *const TfFatPtrKindMs,
    );
    assert_ne!(
        metadata_shape_corrupt(TfFatPtrKindMs::Slice(TfTyIdMs(7))),
        jit_slice7,
        "negative control must FAIL: dropping the Slice payload should disagree with JIT"
    );
    assert_eq!(
        jit_slice7,
        TfPointerMetadataShapeMs::SliceLen { elem: TfTyIdMs(7) },
        "JIT must carry the Slice element id (7) into SliceLen"
    );

    drop(buffer);
}

// -- is_reference / is_aggregate ----------------------------------------------
// Both are wide `matches!` predicates over the production `Ty` enum. The emitted
// `@Ty__is_*` is `(in: *const Ty) -> bool`: it loads the i64 holding the niche-
// encoded discriminant (the Box/Vec field's spare-value niche), decodes it to a
// canonical 0..32 tag with a compare/select chain, then a final `switch` selects
// the matching arms. `is_reference` selects {FatPtr, Ref, RefMut, PtrConst,
// PtrMut, Rc}; `is_aggregate` selects {Struct, Array, Tuple, Enum, Set, Sequence,
// Record}. Self-contained -- NO external leaves, NO shims. The same `TfTy` /
// `Tf*Id` layout types the `int_value_fits_ty` foothold uses are reused so rustc
// niche-encodes the discriminant byte-identically to the emitted IR's decode.
