/// TRUST-SELF (batch 3): the production trust-ir `Ty::is_reference` -> MIR ->
/// trust-ir -> trust-cg JIT -> machine code == native Rust, over ONE value of
/// EVERY `Ty` variant (the whole discriminant space). Exercises the faithful
/// niche-decode + switch lowering of the wide `Ty` enum to a bool predicate.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_is_reference_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_is_reference_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_IS_REFERENCE_TRUST_IR)
        .expect("MIR-emitted `is_reference` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `is_reference` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("is_reference_root")
        .expect("JIT symbol `is_reference_root` not found")
        .as_ptr();
    // SAFETY: machine code for a `(*const TfTy) -> bool` fn; buffer held live.
    let f: TyPredFn = unsafe { std::mem::transmute(raw) };

    let cases = all_ty_variants();
    let mut pass = 0usize;
    let mut saw_true = false;
    let mut saw_false = false;
    for (ty, label) in &cases {
        let native = is_reference_native(ty);
        // SAFETY: JIT reads `&Ty` with the byte layout the native value has.
        let jit = f(ty as *const TfTy);
        assert_eq!(
            native, jit,
            "TRUST-SELF is_reference JIT disagrees with native on `{label}`: \
             native={native} jit={jit}"
        );
        saw_true |= jit;
        saw_false |= !jit;
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all is_reference variants must agree native == JIT"
    );
    assert!(
        saw_true && saw_false,
        "is_reference must produce both true and false"
    );

    // Spot-check the load-bearing arms explicitly through the JIT.
    assert!(
        f(&TfTy::Ref(Box::new(TfTy::I32)) as *const TfTy),
        "Ref is a reference"
    );
    assert!(
        f(&TfTy::FatPtr(TfFatPtrKind::Str) as *const TfTy),
        "FatPtr is a reference"
    );
    assert!(
        !f(&TfTy::Ptr as *const TfTy),
        "thin Ptr is NOT a reference here"
    );
    assert!(!f(&TfTy::I32 as *const TfTy), "I32 is NOT a reference");

    // NEGATIVE CONTROL: a corrupted oracle that also calls thin `Ptr` a reference
    // must DISAGREE with the JIT on `Ptr` (which the real predicate excludes).
    fn is_reference_corrupt(t: &TfTy) -> bool {
        match t {
            TfTy::Ptr => true, // bug: thin Ptr is not in the reference set
            other => is_reference_native(other),
        }
    }
    assert_ne!(
        is_reference_corrupt(&TfTy::Ptr),
        f(&TfTy::Ptr as *const TfTy),
        "negative control must FAIL: counting thin Ptr as a reference should disagree with JIT"
    );

    drop(buffer);
}

/// TRUST-SELF (batch 3): the production trust-ir `Ty::is_aggregate` -> MIR ->
/// trust-ir -> trust-cg JIT -> machine code == native Rust, over ONE value of
/// EVERY `Ty` variant. A DIFFERENT true-set than `is_reference`, so the JIT must
/// decode and switch on a different subset of the discriminant space.
