/// Rust `env_get(&EnvTable, &Name) -> u64` (the REAL hashbrown SwissTable lookup,
/// generic `Group` u64-SWAR) -> MIR -> trust-ir (stage1 `--mir-emit-closure`) ->
/// trust-cg JIT -> machine code == native Rust, over HITS and MISSES on a
/// real-layout deterministic table. THIS CLOSES THE ENV BOUNDARY: the SwissTable
/// group scan that earlier blocked at NEON `simd_eq` is now JIT-verified as pure
/// u64 arithmetic, faithful to hashbrown's algorithm.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_real_hashmap_get_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_real_hashmap_get_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_ENV_GET_TRUST_IR)
        .expect("MIR-emitted `env_get` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);

    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(
        EXT_HG_CONST_PTR_ADD.to_string(),
        hg_shim_const_ptr_add as *const u8,
    );
    externs.insert(
        EXT_HG_CAST_TAG_1.to_string(),
        hg_shim_cast_identity as *const u8,
    );
    externs.insert(
        EXT_HG_CAST_TAG_2.to_string(),
        hg_shim_cast_identity as *const u8,
    );
    externs.insert(
        EXT_HG_CAST_ENTRY.to_string(),
        hg_shim_cast_identity as *const u8,
    );
    externs.insert(
        EXT_HG_READ_UNALIGNED.to_string(),
        hg_shim_read_unaligned_u64 as *const u8,
    );
    externs.insert(
        EXT_HG_WRAPPING_SUB.to_string(),
        hg_shim_u64_wrapping_sub as *const u8,
    );
    externs.insert(
        EXT_HG_WRAPPING_MUL.to_string(),
        hg_shim_u64_wrapping_mul as *const u8,
    );
    externs.insert(EXT_HG_TO_LE.to_string(), hg_shim_u64_to_le as *const u8);
    externs.insert(
        EXT_HG_FROM_NE_BYTES.to_string(),
        hg_shim_u64_from_ne_bytes as *const u8,
    );
    externs.insert(
        EXT_HG_TRAILING_ZEROS.to_string(),
        hg_shim_u64_trailing_zeros as *const u8,
    );
    externs.insert(EXT_HG_ENTRY_SUB.to_string(), hg_shim_entry_sub as *const u8);
    externs.insert(
        EXT_HG_OPTION_BRANCH.to_string(),
        hg_shim_option_branch as *const u8,
    );
    externs.insert(
        EXT_HG_OPTION_FROM_RESIDUAL.to_string(),
        hg_shim_option_from_residual as *const u8,
    );

    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted `env_get` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("env_get")
        .expect("JIT symbol `env_get` not found")
        .as_ptr();
    // SAFETY: machine code for `env_get(&EnvTable, &Name) -> u64`. `&EnvTable` is a
    // thin pointer to the 16-byte `(bucket_mask, ctrl)` struct; `&Name` is a thin
    // pointer to the u64 key. Buffer held live across all calls.
    let f: extern "C" fn(*const HgEnvTable, *const HgName) -> u64 =
        unsafe { std::mem::transmute(raw) };

    // A spread of env-key/value entries (the kind of interned-Name -> ConstantInfo
    // handles a real Environment lookup holds) over a 16-bucket real-layout table.
    // Keys 0 and 1819 are an ADVERSARIAL h2-COLLISION pair: both hash into the
    // SAME group (ctrl positions 0 and 7, both within the group-load window at
    // pos 0) with the SAME h2 control tag (0x00). So `match_tag` flags BOTH as
    // candidates for either lookup, FORCING the inlined key-equality `eq(index)`
    // to REJECT the spurious match and accept only the right bucket — exactly the
    // SwissTable false-positive-rejection property the match_tag header documents.
    let entries: [(u64, u64); 7] = [
        (0, 1000),
        (1819, 1819000), // h2-collides with key 0 in the same group
        (1, 1001),
        (42, 1042),
        (0xDEAD_BEEF, 2),
        (0x517c_c1b7_2722_0a95, 7),
        (12345678901234567, 99),
    ];
    let table = HgTable::build(16, &entries);
    let env = table.as_env_table();

    let mut pass = 0usize;

    // HITS: each present key must return its value, native == JIT.
    for &(k, v) in &entries {
        let key = HgName(k);
        let native = hg_env_get_native(&env, key, &table);
        let kk = key;
        let jit = f(&env as *const HgEnvTable, &kk as *const HgName);
        assert_eq!(
            native, v,
            "native oracle wrong on HIT key {k:#x}: got {native:#x}, expected {v:#x}"
        );
        assert_eq!(
            native, jit,
            "JIT env_get disagrees with native on HIT key {k:#x}: native={native:#x} jit={jit:#x}"
        );
        pass += 1;
    }

    // MISSES: an absent key must return the NOT_FOUND sentinel, native == JIT.
    let absent: [u64; 7] = [2, 3, 255, 256, 0xCAFE_F00D, u64::MAX, 0x8000_0000_0000_0001];
    for &k in &absent {
        let key = HgName(k);
        let native = hg_env_get_native(&env, key, &table);
        let kk = key;
        let jit = f(&env as *const HgEnvTable, &kk as *const HgName);
        assert_eq!(
            native, HG_NOT_FOUND,
            "native oracle wrong on MISS key {k:#x}: got {native:#x}, expected NOT_FOUND"
        );
        assert_eq!(
            native, jit,
            "JIT env_get disagrees with native on MISS key {k:#x}: native={native:#x} jit={jit:#x}"
        );
        pass += 1;
    }

    assert_eq!(
        pass,
        entries.len() + absent.len(),
        "all real-hashbrown SwissTable get cases (hits + misses) must agree native == JIT"
    );
    drop(buffer);
}
// ════════════════════════════════════════════════════════════════════════════
// MIR-PATH MILESTONE: whnf's QUOTIENT (Quot.lift) reduction leaf UN-CUT + verified.
//
// The real-Expr `whnf_inner` App-stuck branch calls `try_quot_reduction(&app)`
// (the sibling of `try_iota_reduction`). In the FROZEN `mir_real_expr_whnf_roundtrip`
// rung that call is an in-module STUB returning None. Here it is the REAL Quot.lift
// iota rule, faithful to clean-kernel quot.rs `try_quot_lift_reduction`:
//
//   Quot.lift α r β f h (Quot.mk α' r' a) [extra..]   ->   f a [extra..]
//
// `--mir-emit-closure whnf_impl` over the EXTENDED `clean_expr_whnf_slice.rs`
// (Quot enabled) lowers the call-graph closure:
//   whnf_impl -> whnf_inner -> { try_quot_reduction, try_iota_reduction(None),
//                                unfold_const, instantiate, from_kind, reduce_proj }
//   try_quot_reduction -> { whnf_impl (the VERIFIED body, to whnf the major premise),
//                           get_app_fn, get_app_args, is_quot_lift, is_quot_mk,
//                           Expr::app }
// All of whnf_impl / whnf_inner / try_quot_reduction / get_app_fn / get_app_args /
// is_quot_lift / is_quot_mk / Expr::app / instantiate / lift_at / from_kind /
// compute_meta / mix_hash / unfold_const / reduce_proj / get_constructor are REAL
// IN-MODULE bodies (verified below). Only the TRUE leaves stay 0-block externs (the
// Arc/Box/Vec/Option clones, Vec ops, slice reverse, Arc as_ref, saturating
// add/sub, wrapping_mul, Ord min/max, the KaniHasher Hash impls) — the SAME leaf
// set as the frozen WHNF rung (only the crate disambiguator differs), so every
// shim is reused.
//
// We run native whnf_impl == JIT machine code over Quot.lift reductions:
//   - Quot.lift .. (Quot.mk α r a)        -> f a (re-whnf'd)
//   - Quot.lift .. (Quot.mk α r a) extra  -> f a extra (extra re-applied)
//   - a STUCK quot (major not Quot.mk)    -> spine rebuilt (no reduction)
//   - a STUCK quot (major a DELTA-const that unfolds to Quot.mk a) -> f a
//     (the major is whnf'd by the VERIFIED whnf_impl inside try_quot_reduction)
//   - under-applied Quot.lift (< 6 args)  -> stuck spine
//   - a non-Quot head                     -> the prior BETA/DELTA/Proj-iota cases,
//     UNPERTURBED (the quot gate must not change the rest of whnf).
// + a NEGATIVE control: a Quot.lift over Quot.mk reduces (so a wrong stub that
//   returned None would be caught by the f-a mismatch).
//
// This is the EXACT analog of the verified recursor rung
// (`mir_reduce_recursor_iota_roundtrip`), applied to Quot's sibling — whnf's
// quotient leaf is now faithful + JIT-verified (one more cut closed).
//
// REGEN: `trust_ir_mir clean_expr_whnf_slice.rs --crate-type=bin
//   --mir-emit-closure whnf_impl <out>`. Refresh MIR_WHNF_QUOT_CLOSURE_TRUST_IR
// AND the EXT/extern symbol disambiguator together. (disambiguator: Cs6aLFzTHF3gX)
// ════════════════════════════════════════════════════════════════════════════

/// The slice's `CertVerifier` with the QUOT-info field: `env`@0 (fat slice),
/// `ctors`@16 (fat slice), `quots`@32 (thin ptr). `#[repr(C)]` pins the layout the
/// in-module `unfold_const` / `get_constructor` / `is_quot_lift` / `is_quot_mk`
/// read (matches the stage1-emitted offsets: quots@32, lift@0, mk@4).
#[repr(C)]
struct CwqVerifier<'e> {
    env: &'e [(CwName, Option<CwExpr>)],
    ctors: &'e [(CwName, u32)],
    quots: &'e CwqQuotInfo,
}

/// The modeled quot-info (the two Quot Name handles the lift rule needs).
#[repr(C)]
struct CwqQuotInfo {
    lift: CwName,
    mk: CwName,
}

impl<'e> CwqVerifier<'e> {
    fn cwq_unfold_const(&self, name: &CwName) -> Option<CwExpr> {
        let mut i: usize = 0;
        let n = self.env.len();
        while i < n {
            let entry = &self.env[i];
            if entry.0 == *name {
                return entry.1.clone();
            }
            i += 1;
        }
        None
    }
    fn cwq_get_constructor_num_params(&self, name: &CwName) -> Option<u32> {
        let mut i: usize = 0;
        let n = self.ctors.len();
        while i < n {
            let entry = &self.ctors[i];
            if entry.0 == *name {
                return Some(entry.1);
            }
            i += 1;
        }
        None
    }
    fn cwq_is_quot_lift(&self, name: &CwName) -> bool {
        name.0 == self.quots.lift.0
    }
    fn cwq_is_quot_mk(&self, name: &CwName) -> bool {
        name.0 == self.quots.mk.0
    }
    fn cwq_try_iota_reduction(&self, _e: &CwExpr) -> Option<CwExpr> {
        None
    }

    // VERBATIM try_quot_reduction (the Quot.lift iota rule, composing the verified whnf).
    fn cwq_try_quot_reduction(&self, e: &CwExpr) -> Option<CwExpr> {
        let fn_head = e.get_app_fn();
        let args = e.get_app_args();
        let name = match &fn_head.kind {
            CwExprKind::Const(name, _levels) => *name,
            _ => return None,
        };
        if !self.cwq_is_quot_lift(&name) {
            return None;
        }
        if args.len() < 6 {
            return None;
        }
        let major = &args[5];
        let major_whnf = self.cwq_whnf_impl(major);
        let major_head = major_whnf.get_app_fn();
        let mk_name = match &major_head.kind {
            CwExprKind::Const(mk_name, _) => *mk_name,
            _ => return None,
        };
        if !self.cwq_is_quot_mk(&mk_name) {
            return None;
        }
        let major_args = major_whnf.get_app_args();
        if major_args.len() < 3 {
            return None;
        }
        let a = &major_args[2];
        let f = &args[3];
        let mut result = CwExpr::app(f.clone(), a.clone());
        let elim_arity: usize = 6;
        let mut i = elim_arity;
        while i < args.len() {
            result = CwExpr::app(result, args[i].clone());
            i += 1;
        }
        Some(result)
    }

    fn cwq_whnf_impl(&self, e: &CwExpr) -> CwExpr {
        self.cwq_whnf_inner(e)
    }
    fn cwq_whnf_inner(&self, e: &CwExpr) -> CwExpr {
        match &e.kind {
            CwExprKind::App(f, a) => {
                let f_whnf = self.cwq_whnf_impl(f);
                match &f_whnf.kind {
                    CwExprKind::Lam(_, _, body) => {
                        let reduced = body.instantiate(a);
                        self.cwq_whnf_impl(&reduced)
                    }
                    _ => {
                        let app = CwExpr::from_kind(CwExprKind::App(
                            std::sync::Arc::new(f_whnf),
                            a.clone(),
                        ));
                        if let Some(reduced) = self.cwq_try_iota_reduction(&app) {
                            return self.cwq_whnf_impl(&reduced);
                        }
                        if let Some(reduced) = self.cwq_try_quot_reduction(&app) {
                            return self.cwq_whnf_impl(&reduced);
                        }
                        app
                    }
                }
            }
            CwExprKind::Let(_, _, val, body, _) => {
                let reduced = body.instantiate(val);
                self.cwq_whnf_impl(&reduced)
            }
            CwExprKind::Const(name, _levels) => match self.cwq_unfold_const(name) {
                Some(val) => self.cwq_whnf_impl(&val),
                None => e.clone(),
            },
            CwExprKind::Proj(struct_name, idx, expr) => {
                self.cwq_reduce_proj(struct_name, *idx, expr)
            }
            CwExprKind::MData(_, inner) => self.cwq_whnf_impl(inner),
            _ => e.clone(),
        }
    }
    fn cwq_reduce_proj(&self, struct_name: &CwName, idx: u32, expr: &CwExpr) -> CwExpr {
        let expr_whnf = self.cwq_whnf_impl(expr);
        let head = expr_whnf.get_app_fn();
        if let CwExprKind::Const(ctor_name, _) = &head.kind
            && let Some(num_params) = self.cwq_get_constructor_num_params(ctor_name)
        {
            let args = expr_whnf.get_app_args();
            let field_idx = num_params as usize + idx as usize;
            if field_idx < args.len() {
                return self.cwq_whnf_impl(&args[field_idx]);
            }
        }
        CwExpr::from_kind(CwExprKind::Proj(
            *struct_name,
            idx,
            std::sync::Arc::new(expr_whnf),
        ))
    }
}

