    externs.insert("_RNvMNtCskTzINo8ZBH9_5alloc3vecINtB2_3VecNtCs6aLFzTHF3gX_21clean_expr_whnf_slice4ExprE3newBE_".to_string(), cw_shim_vec_new as *const u8);
