    externs.insert("_RNvMs_NtCskTzINo8ZBH9_5alloc3vecINtB4_3VecNtCs6aLFzTHF3gX_21clean_expr_whnf_slice4ExprE3lenBG_".to_string(), cw_shim_vec_len as *const u8);
