    externs.insert("_RNvXsa_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCs6aLFzTHF3gX_21clean_expr_whnf_slice5LevelENtNtCs2EYQwhfuABO_4core5clone5Clone5cloneBH_".to_string(), cw_shim_vec_lvl_clone as *const u8);
    externs.insert("_RNvXsc_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCs6aLFzTHF3gX_21clean_expr_whnf_slice4ExprEINtNtNtCs2EYQwhfuABO_4core3ops5index5IndexjE5indexBH_".to_string(), cw_shim_vec_index as *const u8);
