/// Native oracle — VERBATIM `Ty::is_integer_vector_mask_for_select_ty`
/// (ty.rs:328-335), over `TfTy` (which is laid out byte-identically to the
/// production `Ty` the emitted IR decodes). `vector_shape` / `is_integer` are the
/// same verbatim leaves.
fn mask_select_native(cond_ty: &TfTy, select_ty: &TfTy) -> bool {
    fn vector_shape(t: &TfTy) -> Option<(&TfTy, u32)> {
        match t {
            TfTy::Vector(elem, lanes) => Some((elem.as_ref(), *lanes)),
            _ => None,
        }
    }
    fn is_signed(t: &TfTy) -> bool {
        matches!(t, TfTy::I8 | TfTy::I16 | TfTy::I32 | TfTy::I64 | TfTy::I128)
    }
    fn is_unsigned(t: &TfTy) -> bool {
        matches!(t, TfTy::U8 | TfTy::U16 | TfTy::U32 | TfTy::U64 | TfTy::U128)
    }
    fn is_integer(t: &TfTy) -> bool {
        is_signed(t) || is_unsigned(t)
    }
    match (vector_shape(cond_ty), vector_shape(select_ty)) {
        (Some((cond_elem, cond_lanes)), Some((_select_elem, select_lanes))) => {
            cond_lanes == select_lanes && is_integer(cond_elem)
        }
        _ => false,
    }
}

/// `(cond: *const TfTy, select: *const TfTy) -> bool` — AAPCS64 view of the emitted
/// `@mask_root` (two `&Ty` thin-pointer operands -> bool).
type TyMaskFn = extern "C" fn(*const TfTy, *const TfTy) -> bool;

/// TRUST-SELF (batch 4): the production trust-ir
/// `Ty::is_integer_vector_mask_for_select_ty` -> MIR -> trust-ir (stage1
/// `--mir-emit-closure`) -> trust-cg JIT -> machine code == native Rust, over a
/// cross product of operand pairs that exercises BOTH `vector_shape` decodes, the
/// lane-count comparison (equal vs unequal), the `is_integer` recursion (signed /
/// unsigned / float / non-integer element), and every base case (non-vector
/// operand on either side). Plus a fail-loud negative control.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_mask_select_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_mask_select_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_MASK_SELECT_TRUST_IR)
        .expect("MIR-emitted `is_integer_vector_mask_for_select_ty` trust-ir text must parse");
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &HashMap::new())
        .expect("trust-cg JIT compile of MIR-emitted `mask_root` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("mask_root")
        .expect("JIT symbol `mask_root` not found")
        .as_ptr();
    // SAFETY: machine code for a `(*const TfTy, *const TfTy) -> bool` fn; buffer live.
    let f: TyMaskFn = unsafe { std::mem::transmute(raw) };

    // Operand menu — vectors of varying element type + lane count, plus non-vector
    // base-case operands. The cross product drives every branch.
    let menu: Vec<(TfTy, &'static str)> = vec![
        (TfTy::Vector(Box::new(TfTy::I8), 4), "<4 x i8>"),
        (TfTy::Vector(Box::new(TfTy::I32), 4), "<4 x i32>"),
        (TfTy::Vector(Box::new(TfTy::I64), 4), "<4 x i64>"),
        (TfTy::Vector(Box::new(TfTy::I128), 4), "<4 x i128>"),
        (TfTy::Vector(Box::new(TfTy::U8), 4), "<4 x u8>"),
        (TfTy::Vector(Box::new(TfTy::U32), 4), "<4 x u32>"),
        (TfTy::Vector(Box::new(TfTy::U128), 4), "<4 x u128>"),
        (TfTy::Vector(Box::new(TfTy::F32), 4), "<4 x f32>"), // float elem -> not int
        (TfTy::Vector(Box::new(TfTy::Bool), 4), "<4 x bool>"), // bool elem -> not int
        (TfTy::Vector(Box::new(TfTy::I32), 2), "<2 x i32>"), // diff lane count
        (TfTy::Vector(Box::new(TfTy::I32), 8), "<8 x i32>"), // diff lane count
        (TfTy::I32, "i32"),                                  // non-vector base case
        (TfTy::F64, "f64"),                                  // non-vector base case
        (TfTy::Ptr, "ptr"),                                  // non-vector base case
        (TfTy::Bool, "bool"),                                // non-vector base case
    ];

    let mut pass = 0usize;
    let mut saw_true = false;
    let mut saw_false_lanes = false; // false because lanes differ
    let mut saw_false_elem = false; // false because element not integer
    let mut saw_false_nonvec = false; // false because an operand is not a vector
    for (cond, clab) in &menu {
        for (select, slab) in &menu {
            let native = mask_select_native(cond, select);
            // SAFETY: JIT reads `&TfTy` with the byte layout the native value has.
            let jit = f(cond as *const TfTy, select as *const TfTy);
            assert_eq!(
                native, jit,
                "TRUST-SELF mask_select JIT disagrees with native on cond=`{clab}` select=`{slab}`: \
                 native={native} jit={jit}"
            );
            saw_true |= jit;
            // Classify a few of the false cases so we can assert the branches ran.
            if !jit {
                let cv = matches!(cond, TfTy::Vector(_, _));
                let sv = matches!(select, TfTy::Vector(_, _));
                if cv && sv {
                    if let (TfTy::Vector(_, cl), TfTy::Vector(_, sl)) = (cond, select) {
                        if cl != sl {
                            saw_false_lanes = true;
                        } else {
                            saw_false_elem = true; // same lanes, must be non-int elem
                        }
                    }
                } else {
                    saw_false_nonvec = true;
                }
            }
            pass += 1;
        }
    }
    assert_eq!(
        pass,
        menu.len() * menu.len(),
        "all mask_select pairs must agree native == JIT"
    );
    assert!(
        saw_true && saw_false_lanes && saw_false_elem && saw_false_nonvec,
        "mask_select must exercise: a true case, a lane-mismatch false, a non-integer-element \
         false, and a non-vector false — true={saw_true} lanes={saw_false_lanes} \
         elem={saw_false_elem} nonvec={saw_false_nonvec}"
    );

    // Spot-check the load-bearing arms explicitly through the JIT.
    {
        let c = TfTy::Vector(Box::new(TfTy::I32), 4);
        let s = TfTy::Vector(Box::new(TfTy::F32), 4);
        assert!(
            f(&c as *const TfTy, &s as *const TfTy),
            "<4 x i32> IS a physical integer mask for a <4 x f32> select"
        );
    }
    {
        let c = TfTy::Vector(Box::new(TfTy::F32), 4); // float element -> not a mask
        let s = TfTy::Vector(Box::new(TfTy::F32), 4);
        assert!(
            !f(&c as *const TfTy, &s as *const TfTy),
            "<4 x f32> condition is NOT an integer mask"
        );
    }
    {
        let c = TfTy::Vector(Box::new(TfTy::I32), 2); // lane mismatch -> false
        let s = TfTy::Vector(Box::new(TfTy::I32), 4);
        assert!(
            !f(&c as *const TfTy, &s as *const TfTy),
            "lane-count mismatch (2 != 4) -> not a select-matching mask"
        );
    }
    {
        let c = TfTy::I32; // non-vector condition -> false
        let s = TfTy::Vector(Box::new(TfTy::I32), 4);
        assert!(
            !f(&c as *const TfTy, &s as *const TfTy),
            "a scalar i32 is not a vector mask"
        );
    }

    // NEGATIVE CONTROL (fail-loud): a corrupted oracle that drops the
    // `cond_elem.is_integer()` requirement (treats ANY same-lane vector pair as a
    // mask) must DISAGREE with the JIT on `<4 x f32>` vs `<4 x f32>` — the JIT
    // correctly returns false (float element is not an integer mask). Proves the
    // test discriminates the `is_integer` recursion, not just the lane check.
    fn mask_select_corrupt(cond_ty: &TfTy, select_ty: &TfTy) -> bool {
        match (cond_ty, select_ty) {
            (TfTy::Vector(_, cl), TfTy::Vector(_, sl)) => cl == sl, // bug: ignores element type
            _ => false,
        }
    }
    let c = TfTy::Vector(Box::new(TfTy::F32), 4);
    let s = TfTy::Vector(Box::new(TfTy::F32), 4);
    let jit = f(&c as *const TfTy, &s as *const TfTy);
    assert_ne!(
        mask_select_corrupt(&c, &s),
        jit,
        "negative control must FAIL: ignoring the is_integer element check should disagree with JIT"
    );
    assert!(
        !jit,
        "JIT must return false for a <4 x f32> condition (float element, not an integer mask)"
    );

    drop(buffer);
}

