/// The exact mangled symbol of the ONE extern leaf the closure body calls —
/// `<u32>::checked_mul` (the slice-crate-hashed name from the emit above). Bound to
/// the host shim below so the JIT can resolve it.
const EXT_CHECKED_MUL: &str =
    "_RNvMs6_NtCs2EYQwhfuABO_4core3numm11checked_mulCsgFMi9JUuHDW_19closure_outer_slice";

/// `Option<u32>` mirror with the SAME layout the frontend's `tcx.layout_of`
/// recovered (and `and_then` reads): tag at byte 0 (0 = None, 1 = Some), value at
/// byte 4; 8 bytes total. The JIT'd `combine_outer`/`and_then` read/write this
/// exact shape through the sret + by-ref Option pointers.
#[repr(C)]
#[derive(Clone, Copy, PartialEq, Debug)]
struct Opt32 {
    tag: u32,
    val: u32,
}
impl Opt32 {
    fn some(v: u32) -> Self {
        Opt32 { tag: 1, val: v }
    }
    fn none() -> Self {
        Opt32 { tag: 0, val: 0 }
    }
}

/// Host shim for the extern leaf `<u32>::checked_mul` in the closure body. ABI:
/// `(out: *mut Opt32 [sret], x: u32, k: u32) -> ()`, writing `Some(x*k)` or `None`
/// on overflow. This is the genuine `u32::checked_mul` semantics; the JIT'd closure
/// body CALLs it (the leaf arithmetic intentionally left extern — the rung pulls in
/// the combinator + closure body, not core's deep checked-arith helpers).
extern "C" fn checked_mul_u32_shim(out: *mut Opt32, x: u32, k: u32) {
    // SAFETY: `out` is the JIT's 8-byte Opt32 sret slot, held live by the caller.
    unsafe {
        match x.checked_mul(k) {
            Some(v) => *out = Opt32::some(v),
            None => *out = Opt32::none(),
        }
    }
}

/// The native oracle: the VERBATIM slice semantics
/// `combine_outer(o, k) = o.and_then(|b| b.checked_mul(k))`.
fn combine_outer_native(o: Opt32, k: u32) -> Opt32 {
    let opt = if o.tag == 1 { Some(o.val) } else { None };
    match opt.and_then(|b| b.checked_mul(k)) {
        Some(v) => Opt32::some(v),
        None => Opt32::none(),
    }
}

/// `(out: *mut Opt32 [sret], o: *const Opt32, k: u32) -> ()` — the JIT'd
/// `combine_outer`'s rust ABI (sret result, by-ref Option arg, scalar `k`).
type CombineFn = extern "C" fn(*mut Opt32, *const Opt32, u32);

/// RUNG 9 round-trip: a NON-ESCAPING CLOSURE consumed by `Option::and_then`,
/// JIT-compiled and executed — native == JIT machine code. The JIT runs the REAL
/// monomorphized `Option::and_then` (in-module), which constructs/consumes the
/// closure: it matches the Option, in the `Some` arm SPREADS the rust-call args
/// tuple and invokes the closure body (in-module), which reads the captured `k`
/// from the capture struct and calls `checked_mul` (the bound host leaf). This is
/// the closure-combinator family unblocked end-to-end.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn frontend_rung9_option_and_then_closure_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "frontend_rung9_option_and_then_closure_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(FRONTEND_RUNG9_CLOSURE_TRUST_IR)
        .expect("frontend RUNG9 closure/and_then trust-ir text must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(
        EXT_CHECKED_MUL.to_string(),
        checked_mul_u32_shim as *const u8,
    );
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of combine_outer (closure + and_then) failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("combine_outer")
        .expect("JIT symbol combine_outer not found")
        .as_ptr();
    // SAFETY: machine code for the `(*mut Opt32, *const Opt32, u32) -> ()` rust ABI;
    // buffer held live for the duration of the calls.
    let f: CombineFn = unsafe { std::mem::transmute(raw) };

    let call = |o: Opt32, k: u32| -> Opt32 {
        let mut out = Opt32 {
            tag: 0xDEAD,
            val: 0xBEEF,
        };
        f(&mut out as *mut Opt32, &o as *const Opt32, k);
        out
    };

    // Cover BOTH combinator branches (Some / None), the closure's checked_mul
    // success AND overflow (the closure body's `b.checked_mul(k)` returning None),
    // and k = 0 / 1 edge cases.
    let cases: Vec<(Opt32, u32, &str)> = vec![
        (Opt32::some(7), 6, "Some(7), k=6 -> Some(42)"),
        (Opt32::some(0), 99, "Some(0), k=99 -> Some(0)"),
        (Opt32::some(123), 1, "Some(123), k=1 -> Some(123)"),
        (Opt32::some(123), 0, "Some(123), k=0 -> Some(0)"),
        (Opt32::none(), 6, "None, k=6 -> None"),
        (Opt32::none(), 0, "None, k=0 -> None"),
        (
            Opt32::some(0x1000_0000),
            0x10,
            "Some big * 0x10 -> OVERFLOW -> None",
        ),
        (
            Opt32::some(u32::MAX),
            2,
            "Some(MAX) * 2 -> OVERFLOW -> None",
        ),
        (Opt32::some(0xFFFF), 0xFFFF, "Some(0xFFFF)^2 fits -> Some"),
    ];
    // Semantic Option<u32> equality: for `None` (tag 0) the value field is
    // UNINITIALIZED in the real ABI (the `and_then` None arm writes only the tag),
    // so compare the value ONLY when `Some` (tag 1). This matches `Option<u32>`'s
    // semantics — a `None`'s payload bytes are don't-care.
    let opt_eq = |a: Opt32, b: Opt32| -> bool {
        if a.tag != b.tag {
            return false;
        }
        a.tag == 0 || a.val == b.val
    };
    for (o, k, label) in cases {
        let native = combine_outer_native(o, k);
        let jit = call(o, k);
        assert!(
            opt_eq(native, jit),
            "JIT machine code (non-escaping closure + Option::and_then) disagrees on {label}: \
             native={native:?} jit={jit:?}"
        );
    }

    // NEGATIVE CONTROL (fail-loud): a corrupted oracle that drops the overflow
    // check (uses wrapping multiply, always Some) must DISAGREE with the JIT on an
    // overflowing case — the JIT correctly returns None (the closure's
    // `checked_mul` overflowed). Proves the test exercises the real checked-mul
    // closure path, not just the Some/None plumbing.
    fn combine_outer_corrupt(o: Opt32, k: u32) -> Opt32 {
        if o.tag == 1 {
            Opt32::some(o.val.wrapping_mul(k)) // bug: no overflow -> None
        } else {
            Opt32::none()
        }
    }
    let (o, k) = (Opt32::some(u32::MAX), 2);
    let jit = call(o, k);
    assert_ne!(
        combine_outer_corrupt(o, k),
        jit,
        "negative control must FAIL: ignoring checked_mul overflow should disagree with the JIT"
    );
    assert_eq!(
        jit.tag, 0,
        "JIT must return None (tag 0) on the overflowing closure case"
    );

    drop(buffer);
}

