/// The ONE extern leaf `<u32>::checked_mul` in the bit_width closures (slice-crate-
/// hashed). Bound to the same `checked_mul_u32_shim` the de-risk test uses.
const EXT_BW_CHECKED_MUL: &str =
    "_RNvMs6_NtCs2EYQwhfuABO_4core3numm11checked_mulCs13KjIXIEljt_20trust_bitwidth_slice";

/// `Ty` mirror with the SAME default layout the frontend's `tcx.layout_of` recovered
/// and the JIT reads: disc@0 (i32), Vector lanes@4 (u32), Vector box@8 (ptr); 16
/// bytes / align 8. Discriminants follow declaration order (Ptr=8, FatPtr=9,
/// Vector=10). We use the SAME `repr(Rust)` enum the slice does, so rustc reproduces
/// the exact layout the slice was compiled with.
// All variants are kept (and in declaration order) to reproduce the exact
// discriminant assignment the slice was compiled with (Ptr=8, FatPtr=9, Vector=10) —
// the values the JIT's `switch` matches. Some are not constructed by the test cases
// below, hence the enum-level allow.
#[derive(Clone)]
#[allow(dead_code)]
enum TyBw {
    Bool,
    U8,
    U16,
    U32,
    U64,
    U128,
    F32,
    F64,
    Ptr,
    FatPtr,
    Vector(Box<TyBw>, u32),
    Unit,
}

impl TyBw {
    /// VERBATIM native oracle: the slice's `bit_width`.
    fn bit_width(&self) -> Option<u32> {
        match self {
            TyBw::Bool => Some(1),
            TyBw::U8 => Some(8),
            TyBw::U16 => Some(16),
            TyBw::U32 => Some(32),
            TyBw::U64 => Some(64),
            TyBw::U128 => Some(128),
            TyBw::F32 => Some(32),
            TyBw::F64 => Some(64),
            TyBw::Vector(elem, lanes) => elem.bit_width().and_then(|bits| bits.checked_mul(*lanes)),
            TyBw::Ptr | TyBw::FatPtr => None,
            _ => None,
        }
    }
    /// VERBATIM native oracle: the slice's `bit_width_with`.
    fn bit_width_with(&self, pointer_bits: u32) -> Option<u32> {
        match self {
            TyBw::Ptr => Some(pointer_bits),
            TyBw::FatPtr => pointer_bits.checked_mul(2),
            TyBw::Vector(elem, lanes) => elem
                .bit_width_with(pointer_bits)
                .and_then(|bits| bits.checked_mul(*lanes)),
            _ => self.bit_width(),
        }
    }
}

/// `(out: *mut Opt32 [sret], t: *const TyBw, pb: u32) -> ()` — `Ty::bit_width_with`'s
/// rust ABI (sret `Option<u32>`, by-ref `&Ty`, scalar `pointer_bits`).
type BitWidthFn = extern "C" fn(*mut Opt32, *const TyBw, u32);

/// RUNG 9 (THE REAL TARGET) round-trip: trust-ir's own `Ty::bit_width_with` — a
/// closure capturing `lanes`, consumed by `Option::and_then`, over a RECURSIVE heap
/// `Ty` — JIT-compiled and executed, native == JIT machine code. The JIT runs the
/// REAL monomorphized `and_then` + the closure body (both in-module), the recursive
/// `Vector` arm walking the `Box<Ty>`, and the `bit_width` delegation — only
/// `<u32>::checked_mul` is the bound host leaf. This verifies the actual rung target.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn frontend_rung9_trust_bit_width_with_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "frontend_rung9_trust_bit_width_with_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(FRONTEND_RUNG9_BITWIDTH_TRUST_IR)
        .expect("frontend RUNG9 bit_width_with trust-ir text must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(
        EXT_BW_CHECKED_MUL.to_string(),
        checked_mul_u32_shim as *const u8,
    );
    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of Ty::bit_width_with (closure + and_then) failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("Ty__bit_width_with")
        .expect("JIT symbol Ty__bit_width_with not found")
        .as_ptr();
    // SAFETY: machine code for the `(*mut Opt32, *const TyBw, u32) -> ()` rust ABI;
    // buffer held live for the calls.
    let f: BitWidthFn = unsafe { std::mem::transmute(raw) };

    let call = |t: &TyBw, pb: u32| -> Option<u32> {
        let mut out = Opt32 {
            tag: 0xDEAD,
            val: 0xBEEF,
        };
        f(&mut out as *mut Opt32, t as *const TyBw, pb);
        if out.tag == 1 { Some(out.val) } else { None }
    };

    // A spread of `Ty`s: scalars (delegate to bit_width), pointers (resolved by pb),
    // fat pointers (pb*2), and RECURSIVE vectors (the closure arm capturing lanes,
    // incl. an OVERFLOWING vector whose checked_mul returns None, and a NESTED
    // vector-of-vector exercising the recursion + and_then twice).
    let cases: Vec<(TyBw, u32, &str)> = vec![
        (TyBw::U32, 64, "U32 -> Some(32)"),
        (TyBw::U64, 64, "U64 -> Some(64)"),
        (TyBw::U128, 64, "U128 -> Some(128)"),
        (TyBw::F32, 64, "F32 -> Some(32)"),
        (TyBw::F64, 64, "F64 -> Some(64)"),
        (TyBw::Bool, 64, "Bool -> Some(1)"),
        (TyBw::Ptr, 64, "Ptr@64 -> Some(64)"),
        (TyBw::Ptr, 32, "Ptr@32 -> Some(32)"),
        (TyBw::FatPtr, 64, "FatPtr@64 -> Some(128)"),
        (TyBw::FatPtr, 32, "FatPtr@32 -> Some(64)"),
        (
            TyBw::Vector(Box::new(TyBw::U32), 4),
            64,
            "Vec<U32;4> -> Some(128)",
        ),
        (
            TyBw::Vector(Box::new(TyBw::U8), 8),
            64,
            "Vec<U8;8> -> Some(64)",
        ),
        (
            TyBw::Vector(Box::new(TyBw::Ptr), 2),
            64,
            "Vec<Ptr;2>@64 -> Some(128)",
        ),
        (
            TyBw::Vector(Box::new(TyBw::Ptr), 2),
            32,
            "Vec<Ptr;2>@32 -> Some(64)",
        ),
        (
            TyBw::Vector(Box::new(TyBw::U128), 0xFFFF_FFFF),
            64,
            "Vec<U128;u32::MAX> -> OVERFLOW None",
        ),
        (
            TyBw::Vector(Box::new(TyBw::Vector(Box::new(TyBw::U16), 4)), 3),
            64,
            "Vec<Vec<U16;4>;3> -> Some(192) nested",
        ),
    ];
    for (t, pb, label) in &cases {
        let native = t.bit_width_with(*pb);
        let jit = call(t, *pb);
        assert_eq!(
            native, jit,
            "JIT machine code (Ty::bit_width_with: closure + and_then, recursive heap) \
             disagrees on {label}: native={native:?} jit={jit:?}"
        );
    }

    // NEGATIVE CONTROL: a corrupted oracle that drops the vector overflow check
    // (wrapping multiply) must DISAGREE with the JIT on the overflowing vector — the
    // JIT correctly returns None (the closure's checked_mul overflowed).
    fn bit_width_with_corrupt(t: &TyBw, pb: u32) -> Option<u32> {
        match t {
            TyBw::Ptr => Some(pb),
            TyBw::FatPtr => Some(pb.wrapping_mul(2)),
            TyBw::Vector(elem, lanes) => {
                bit_width_with_corrupt(elem, pb).map(|bits| bits.wrapping_mul(*lanes))
            }
            _ => t.bit_width(),
        }
    }
    let overflow = TyBw::Vector(Box::new(TyBw::U128), 0xFFFF_FFFF);
    let jit = call(&overflow, 64);
    assert_ne!(
        bit_width_with_corrupt(&overflow, 64),
        jit,
        "negative control must FAIL: ignoring vector-width overflow should disagree with the JIT"
    );
    assert_eq!(
        jit, None,
        "JIT must return None on the overflowing vector (checked_mul overflow)"
    );

    drop(buffer);
}

