#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_is_integer_vector_mask_for_select_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "trust_self_is_integer_vector_mask_for_select_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(MIR_MASK_FOR_SELECT_TRUST_IR)
        .expect("MIR-emitted `is_integer_vector_mask_for_select_ty` trust-ir must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_BOX_AS_REF.to_string(), box_as_ref_shim as *const u8);
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of `is_integer_vector_mask_for_select_ty` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("Ty__is_integer_vector_mask_for_select_ty")
        .expect("JIT symbol `Ty__is_integer_vector_mask_for_select_ty` not found")
        .as_ptr();
    // SAFETY: machine code for `(*const VmTy, *const VmTy) -> bool`; buffer live.
    let f: MaskForSelectFn = unsafe { std::mem::transmute(raw) };

    let vec_ty = |elem: VmTy, lanes: u32| VmTy::Vector(Box::new(elem), lanes);

    // (cond_ty, select_ty, label). Exercises: both vectors same lanes int-elem (TRUE
    // — the physical mask); same lanes but non-integer elem (bool/float -> false);
    // mismatched lane counts (-> false); one or both non-vectors (-> vector_shape
    // None -> false); every integer + non-integer lane elem (-> is_integer ->
    // is_signed | is_unsigned).
    let cases: Vec<(VmTy, VmTy, &str)> = vec![
        // physical integer masks (same lane count, integer elem) => TRUE
        (
            vec_ty(VmTy::I32, 4),
            vec_ty(VmTy::F32, 4),
            "<4 x i32> mask for <4 x f32> (TRUE)",
        ),
        (
            vec_ty(VmTy::U8, 16),
            vec_ty(VmTy::U8, 16),
            "<16 x u8> mask for <16 x u8> (TRUE)",
        ),
        (
            vec_ty(VmTy::I64, 2),
            vec_ty(VmTy::F64, 2),
            "<2 x i64> mask for <2 x f64> (TRUE)",
        ),
        (
            vec_ty(VmTy::I8, 8),
            vec_ty(VmTy::I16, 8),
            "<8 x i8> mask for <8 x i16> (TRUE)",
        ),
        (
            vec_ty(VmTy::U128, 1),
            vec_ty(VmTy::F32, 1),
            "<1 x u128> mask for <1 x f32> (TRUE)",
        ),
        // same lane count but NON-integer cond elem => false (the legal/bool case)
        (
            vec_ty(VmTy::Bool, 4),
            vec_ty(VmTy::F32, 4),
            "<4 x bool> NOT a physical mask",
        ),
        (
            vec_ty(VmTy::F32, 4),
            vec_ty(VmTy::F32, 4),
            "<4 x f32> cond not integer",
        ),
        (
            vec_ty(VmTy::F64, 2),
            vec_ty(VmTy::I64, 2),
            "<2 x f64> cond not integer",
        ),
        // lane-count mismatch => false
        (
            vec_ty(VmTy::I32, 4),
            vec_ty(VmTy::F32, 8),
            "lane mismatch 4 vs 8",
        ),
        (
            vec_ty(VmTy::I8, 16),
            vec_ty(VmTy::I8, 8),
            "lane mismatch 16 vs 8",
        ),
        // non-vector on either side => vector_shape None => false
        (
            VmTy::I32,
            vec_ty(VmTy::F32, 4),
            "scalar i32 cond (not a vector)",
        ),
        (
            vec_ty(VmTy::I32, 4),
            VmTy::F32,
            "scalar f32 select (not a vector)",
        ),
        (VmTy::Bool, VmTy::Bool, "both scalar"),
        (VmTy::Ptr, VmTy::Unit, "both non-vector misc"),
    ];

    let mut mismatches: Vec<&str> = Vec::new();
    for (cond, sel, label) in &cases {
        let native = cond.is_integer_vector_mask_for_select_ty(sel);
        // SAFETY: JIT reads `&Ty`s at the byte layout the native values have.
        let jit = f(cond as *const VmTy, sel as *const VmTy);
        if native != jit {
            mismatches.push(label);
        }
    }
    assert!(
        mismatches.is_empty(),
        "is_integer_vector_mask_for_select_ty native == JIT diverged on: {mismatches:?} \
         (would be a trust-cg miscompile of the mask-detection call graph)"
    );

    // NEGATIVE CONTROL: a corrupted oracle that DROPS the lane-count equality (accepts
    // any two integer vectors as a mask). It must DISAGREE with the JIT on a lane
    // mismatch case (the JIT correctly rejects mismatched lanes), proving the test
    // discriminates the `cond_lanes == select_lanes` check.
    fn vm_mask_corrupt(cond: &VmTy, select_ty: &VmTy) -> bool {
        match (cond.vector_shape(), select_ty.vector_shape()) {
            (Some((cond_elem, _cl)), Some((_se, _sl))) => cond_elem.is_integer(), // bug: drop lane-eq
            _ => false,
        }
    }
    let bad_cond = VmTy::Vector(Box::new(VmTy::I32), 4);
    let bad_sel = VmTy::Vector(Box::new(VmTy::F32), 8); // lane mismatch
    let corrupt = vm_mask_corrupt(&bad_cond, &bad_sel); // corrupt says true
    let jit_bad = f(&bad_cond as *const VmTy, &bad_sel as *const VmTy); // real JIT says false
    assert_ne!(
        corrupt, jit_bad,
        "negative control must FAIL: dropping the lane-count check should disagree with the JIT"
    );
    assert!(
        !jit_bad,
        "JIT must reject a <4 x i32> mask against a <8 x f32> select (lane mismatch)"
    );

    drop(buffer);
}

#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_validate_select_condition_ty_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution(
        "trust_self_validate_select_condition_ty_roundtrip",
    );
    let module = emitted_fixture::parse_emitted(MIR_VALIDATE_SELECT_COND_TRUST_IR)
        .expect("MIR-emitted `validate_select_condition_ty_code` trust-ir must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_BOX_AS_REF.to_string(), box_as_ref_shim as *const u8);
    externs.insert(EXT_BOX_NEW.to_string(), box_new_shim as *const u8);
    externs.insert(EXT_TY_EQ.to_string(), ty_eq_shim as *const u8);
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of `validate_select_condition_ty_code` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("validate_select_condition_ty_code")
        .expect("JIT symbol `validate_select_condition_ty_code` not found")
        .as_ptr();
    // SAFETY: machine code for `(*const VmTy, *const VmTy) -> u8`; buffer live.
    let f: ValidateSelectCondFn = unsafe { std::mem::transmute(raw) };

    let vec_ty = |elem: VmTy, lanes: u32| VmTy::Vector(Box::new(elem), lanes);
    let bool_vec = |lanes: u32| VmTy::Vector(Box::new(VmTy::Bool), lanes);

    // (select_ty, cond_ty, label). Outcomes: 0=Ok (cond is the required condition),
    // 1=PhysicalIntegerMask (same-lane integer vector), 2=TypeMismatch (anything else).
    let cases: Vec<(VmTy, VmTy, &str)> = vec![
        // Ok: scalar select wants scalar bool cond.
        (VmTy::I32, VmTy::Bool, "scalar select + bool cond => Ok(0)"),
        (VmTy::F64, VmTy::Bool, "f64 select + bool cond => Ok(0)"),
        (VmTy::Ptr, VmTy::Bool, "ptr select + bool cond => Ok(0)"),
        // Ok: vector select wants <N x bool> mask of matching lanes.
        (
            vec_ty(VmTy::F32, 4),
            bool_vec(4),
            "<4 x f32> select + <4 x bool> => Ok(0)",
        ),
        (
            vec_ty(VmTy::I64, 2),
            bool_vec(2),
            "<2 x i64> select + <2 x bool> => Ok(0)",
        ),
        (
            vec_ty(VmTy::U8, 16),
            bool_vec(16),
            "<16 x u8> select + <16 x bool> => Ok(0)",
        ),
        // PhysicalIntegerMask: vector select + same-lane integer-vector cond.
        (
            vec_ty(VmTy::F32, 4),
            vec_ty(VmTy::I32, 4),
            "<4 x f32> + <4 x i32> => PhysMask(1)",
        ),
        (
            vec_ty(VmTy::F64, 2),
            vec_ty(VmTy::I64, 2),
            "<2 x f64> + <2 x i64> => PhysMask(1)",
        ),
        (
            vec_ty(VmTy::I8, 8),
            vec_ty(VmTy::U8, 8),
            "<8 x i8> + <8 x u8> => PhysMask(1)",
        ),
        // TypeMismatch: scalar select + non-bool cond.
        (
            VmTy::I32,
            VmTy::I32,
            "scalar select + i32 cond => Mismatch(2)",
        ),
        (
            VmTy::F64,
            VmTy::U8,
            "scalar select + u8 cond => Mismatch(2)",
        ),
        // TypeMismatch: vector select + wrong-lane bool mask.
        (
            vec_ty(VmTy::F32, 4),
            bool_vec(8),
            "<4 x f32> + <8 x bool> => Mismatch(2)",
        ),
        // TypeMismatch: vector select + same-lane FLOAT/bool? float vector (not integer, not bool-mask of right lanes).
        (
            vec_ty(VmTy::F32, 4),
            vec_ty(VmTy::F32, 4),
            "<4 x f32> + <4 x f32> => Mismatch(2)",
        ),
        // TypeMismatch: vector select + scalar bool cond (lanes 1 mask wrong).
        (
            vec_ty(VmTy::F32, 4),
            VmTy::Bool,
            "<4 x f32> + scalar bool => Mismatch(2)",
        ),
    ];

    let mut mismatches: Vec<&str> = Vec::new();
    for (sel, cond, label) in &cases {
        let native = vm_validate_select_condition_ty_code(sel, cond);
        // SAFETY: JIT reads `&Ty`s at the byte layout the native values have.
        let jit = f(sel as *const VmTy, cond as *const VmTy);
        if native != jit {
            mismatches.push(label);
        }
    }
    assert!(
        mismatches.is_empty(),
        "validate_select_condition_ty native == JIT diverged on: {mismatches:?} \
         (a trust-cg miscompile of the validator control flow / mask path)"
    );

    // NEGATIVE CONTROL: a corrupted decision that swaps the mask/mismatch outcomes
    // (returns 2 where the real validator returns 1). It must DISAGREE with the JIT
    // on a physical-mask case, proving the test discriminates the mask branch.
    fn vm_validate_corrupt(select_ty: &VmTy, cond_ty: &VmTy) -> u8 {
        let expected = vm_required_select_condition_ty(select_ty);
        if cond_ty == &expected {
            return 0;
        }
        if cond_ty.is_integer_vector_mask_for_select_ty(select_ty) {
            return 2; // bug: should be 1 (PhysicalMask)
        }
        2
    }
    let sel = VmTy::Vector(Box::new(VmTy::F32), 4);
    let cond = VmTy::Vector(Box::new(VmTy::I32), 4); // physical mask
    let corrupt = vm_validate_corrupt(&sel, &cond); // corrupt says 2
    let jit_v = f(&sel as *const VmTy, &cond as *const VmTy); // real JIT says 1
    assert_ne!(
        corrupt, jit_v,
        "negative control must FAIL: collapsing PhysicalMask into Mismatch should disagree with the JIT"
    );
    assert_eq!(
        jit_v, 1,
        "JIT must classify a same-lane integer-vector cond as PhysicalIntegerMask(1)"
    );

    drop(buffer);
}

