// ===========================================================================
// TRUST-SELF — THE ALLOCATION-BOUND CONST-FOLDER: `fold_binop` (alloc_bound.rs:247).
//
// `fold_binop(op, lhs, rhs) -> Option<i128>` folds integer arithmetic on KNOWN
// constants while bounding an allocation's size. Every arm is overflow-AWARE: it
// returns None (no static bound) rather than a WRONG wrapped value, because a
// wrapped fold under-estimates a size and yields an out-of-bounds access — a direct
// memory-safety miscompile. Transcribed VERBATIM from alloc_bound.rs except the Shl
// guard `(0..128).contains(&b)` -> the equivalent `b < 0 || b >= 128` (the stage1
// MIR frontend cannot lower the `Range<i128>` const aggregate `Range::contains`
// builds — a real frontend gap, reported in the run notes; the rewrite is provably
// the same predicate). Lowered by the SAME `--mir-emit-closure` path; 3 IN-MODULE
// members (`fold_binop`, the monomorphized `Option::<i128>::and_then`, and the Shl
// closure `|m| a.checked_mul(m)`), validate_module=0, re-parses.
//
// The VERIFIED surface is the full `BinOp` switch, the `?`-operator `Option<i128>`
// plumbing, and the Shl `checked_shl().and_then(checked_mul)` overflow chain — all
// JIT machine code. The host leaves are `core` intrinsics bound to native shims
// (the SAME discipline as fold_add's checked_add / total_bits' checked_add): the `?`
// desugar (`Try::branch` + `FromResidual::from_residual`), and the i128 `checked_*`
// ops. `BinOp` is the production fieldless enum (u8 discriminant); the emitted
// `switch` decodes the same bytes. ABI read off the IR: `@fold_binop` is
// `(out: &mut Option<i128>, op: u8, lhs: &Option<i128>, rhs: &Option<i128>)`.
// ===========================================================================

/// rustc's 32-byte `Option<i128>` layout (no niche): discriminant `i128` @0
/// (0=None, 1=Some), payload `i128` @16. (Read off the emitted bodies.)
#[repr(C, align(16))]
#[derive(Clone, Copy)]
struct OptI128 {
    disc: i128,
    val: i128,
}
impl OptI128 {
    fn none() -> Self {
        OptI128 { disc: 0, val: 0 }
    }
    fn some(v: i128) -> Self {
        OptI128 { disc: 1, val: v }
    }
    fn get(self) -> Option<i128> {
        match self.disc {
            0 => None,
            1 => Some(self.val),
            d => panic!("bad OptI128 disc {d}"),
        }
    }
}
/// rustc's `ControlFlow<Option<Infallible>, i128>` (what `<Option<i128> as Try>::branch`
/// returns): disc `i128` @0 (0=Continue, 1=Break), value `i128` @16.
#[repr(C, align(16))]
#[derive(Clone, Copy)]
struct CtrlFlowI128 {
    disc: i128,
    val: i128,
}

/// `@fold_binop` ABI: `(out: &mut Option<i128>, op: u8, lhs: &Option<i128>, rhs: &Option<i128>)`.
type FoldBinopFn = extern "C" fn(*mut OptI128, u8, *const OptI128, *const OptI128);

// The `?`-operator desugar for `Option<i128>`. `Try::branch(out: &mut ControlFlow, opt:
// &Option<i128>)`: Some(v) -> Continue(v) [disc 0], None -> Break(residual) [disc 1].
const EXT_TRY_BRANCH: &str = "_RNvXsJ_NtCs2EYQwhfuABO_4core6optionINtB5_6OptionnENtNtNtB7_3ops9try_trait3Try6branchCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn try_branch_shim(out: *mut CtrlFlowI128, opt: *const OptI128) {
    // SAFETY: `out` a valid ControlFlow slot; `opt` a valid &Option<i128>.
    unsafe {
        match (*opt).get() {
            Some(v) => std::ptr::write(out, CtrlFlowI128 { disc: 0, val: v }), // Continue(v)
            None => std::ptr::write(out, CtrlFlowI128 { disc: 1, val: 0 }),    // Break(residual)
        }
    }
}
// `FromResidual::from_residual(out: &mut Option<i128>)`: the `?` early-return writes
// None to the result.
const EXT_FROM_RESIDUAL: &str = "_RNvXsK_NtCs2EYQwhfuABO_4core6optionINtB5_6OptionnEINtNtNtB7_3ops9try_trait12FromResidualIBy_NtNtB7_7convert10InfallibleEE13from_residualCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn from_residual_shim(out: *mut OptI128) {
    // SAFETY: `out` a valid Option<i128> slot.
    unsafe {
        std::ptr::write(out, OptI128::none());
    }
}
// i128 `checked_add/sub/mul(out: &mut Option<i128>, a: i128, b: i128)` — sret Option.
const EXT_CHECKED_ADD_I128: &str =
    "_RNvMs2_NtCs2EYQwhfuABO_4core3numn11checked_addCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn checked_add_i128_shim(out: *mut OptI128, a: i128, b: i128) {
    // SAFETY: `out` a valid Option<i128> slot.
    unsafe {
        std::ptr::write(out, a.checked_add(b).map_or(OptI128::none(), OptI128::some));
    }
}
const EXT_CHECKED_SUB_I128: &str =
    "_RNvMs2_NtCs2EYQwhfuABO_4core3numn11checked_subCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn checked_sub_i128_shim(out: *mut OptI128, a: i128, b: i128) {
    // SAFETY: `out` a valid Option<i128> slot.
    unsafe {
        std::ptr::write(out, a.checked_sub(b).map_or(OptI128::none(), OptI128::some));
    }
}
const EXT_CHECKED_MUL_I128: &str =
    "_RNvMs2_NtCs2EYQwhfuABO_4core3numn11checked_mulCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn checked_mul_i128_shim(out: *mut OptI128, a: i128, b: i128) {
    // SAFETY: `out` a valid Option<i128> slot.
    unsafe {
        std::ptr::write(out, a.checked_mul(b).map_or(OptI128::none(), OptI128::some));
    }
}
// `i128::checked_shl(out: &mut Option<i128>, val: i128, shift: u32)` — sret Option.
const EXT_CHECKED_SHL_I128: &str =
    "_RNvMs2_NtCs2EYQwhfuABO_4core3numn11checked_shlCs99MkpMfQ48c_23trust_fold_binop2_slice";
extern "C" fn checked_shl_i128_shim(out: *mut OptI128, val: i128, shift: u32) {
    // SAFETY: `out` a valid Option<i128> slot.
    unsafe {
        std::ptr::write(
            out,
            val.checked_shl(shift)
                .map_or(OptI128::none(), OptI128::some),
        );
    }
}

// BinOp discriminants (the production fieldless enum order; inst.rs:11-40).
const BINOP_ADD: u8 = 0;
const BINOP_SUB: u8 = 1;
const BINOP_MUL: u8 = 2;
const BINOP_UDIV: u8 = 3;
const BINOP_AND: u8 = 14;
const BINOP_OR: u8 = 15;
const BINOP_XOR: u8 = 16;
const BINOP_SHL: u8 = 17;
const BINOP_LSHR: u8 = 18;

// The native oracle: VERBATIM alloc_bound.rs:247-265 (Shl guard as the equivalent
// comparison, matching the lowered slice). Takes the op as a u8 the same way.
fn vm_fold_binop(op: u8, lhs: Option<i128>, rhs: Option<i128>) -> Option<i128> {
    let (a, b) = (lhs?, rhs?);
    match op {
        BINOP_ADD => a.checked_add(b),
        BINOP_SUB => a.checked_sub(b),
        BINOP_MUL => a.checked_mul(b),
        BINOP_AND => Some(a & b),
        BINOP_OR => Some(a | b),
        BINOP_XOR => Some(a ^ b),
        BINOP_SHL => {
            if !(0..128).contains(&b) {
                return None;
            }
            1i128.checked_shl(b as u32).and_then(|m| a.checked_mul(m))
        }
        _ => None,
    }
}

#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_fold_binop_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_fold_binop_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_FOLD_BINOP_TRUST_IR)
        .expect("MIR-emitted `fold_binop` trust-ir must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_TRY_BRANCH.to_string(), try_branch_shim as *const u8);
    externs.insert(
        EXT_FROM_RESIDUAL.to_string(),
        from_residual_shim as *const u8,
    );
    externs.insert(
        EXT_CHECKED_ADD_I128.to_string(),
        checked_add_i128_shim as *const u8,
    );
    externs.insert(
        EXT_CHECKED_SUB_I128.to_string(),
        checked_sub_i128_shim as *const u8,
    );
    externs.insert(
        EXT_CHECKED_MUL_I128.to_string(),
        checked_mul_i128_shim as *const u8,
    );
    externs.insert(
        EXT_CHECKED_SHL_I128.to_string(),
        checked_shl_i128_shim as *const u8,
    );
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of `fold_binop` failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("fold_binop")
        .expect("JIT symbol `fold_binop` not found")
        .as_ptr();
    // SAFETY: machine code for `(&mut Option<i128>, u8, &Option<i128>, &Option<i128>)`.
    let f: FoldBinopFn = unsafe { std::mem::transmute(raw) };
    let jit_fold = |op: u8, lhs: Option<i128>, rhs: Option<i128>| -> Option<i128> {
        let l = lhs.map_or(OptI128::none(), OptI128::some);
        let r = rhs.map_or(OptI128::none(), OptI128::some);
        let mut out = OptI128 { disc: 99, val: 0 };
        f(
            &mut out as *mut OptI128,
            op,
            &l as *const OptI128,
            &r as *const OptI128,
        );
        out.get()
    };

    // (op, lhs, rhs, label). Covers: `?` short-circuit (either operand None);
    // checked add/sub/mul Some + overflow->None boundary; bitwise and/or/xor; the Shl
    // arm (in-range fold, the b<0 / b>=128 guards, and the checked_mul value overflow
    // inside Shl); and an unsupported op (UDiv/LShr -> None).
    let cases: Vec<(u8, Option<i128>, Option<i128>, &str)> = vec![
        // `?` short-circuit: unknown operand => None.
        (BINOP_ADD, None, Some(3), "Add None,3 => None (?)"),
        (BINOP_MUL, Some(7), None, "Mul 7,None => None (?)"),
        // Add: Some + overflow boundary.
        (BINOP_ADD, Some(2), Some(3), "Add 2,3 => 5"),
        (
            BINOP_ADD,
            Some(i128::MAX),
            Some(1),
            "Add MAX,1 => None (overflow)",
        ),
        (
            BINOP_ADD,
            Some(i128::MIN),
            Some(-1),
            "Add MIN,-1 => None (overflow)",
        ),
        // Sub.
        (BINOP_SUB, Some(10), Some(4), "Sub 10,4 => 6"),
        (
            BINOP_SUB,
            Some(i128::MIN),
            Some(1),
            "Sub MIN,1 => None (overflow)",
        ),
        // Mul.
        (BINOP_MUL, Some(6), Some(7), "Mul 6,7 => 42"),
        (
            BINOP_MUL,
            Some(i128::MAX),
            Some(2),
            "Mul MAX,2 => None (overflow)",
        ),
        (BINOP_MUL, Some(0), Some(i128::MAX), "Mul 0,MAX => 0"),
        // Bitwise.
        (BINOP_AND, Some(0b1100), Some(0b1010), "And => 0b1000"),
        (BINOP_OR, Some(0b1100), Some(0b1010), "Or => 0b1110"),
        (BINOP_XOR, Some(0b1100), Some(0b1010), "Xor => 0b0110"),
        (BINOP_AND, Some(-1), Some(0x5555), "And -1,0x5555 => 0x5555"),
        // Unsupported ops (the `_ => None` arm).
        (BINOP_UDIV, Some(10), Some(2), "UDiv => None (unsupported)"),
        (BINOP_LSHR, Some(8), Some(1), "LShr => None (unsupported)"),
        // Shl arm — see the pinned-miscompile note below. Cases whose NATIVE result
        // is None (the b<0 / b>=128 guards, and the 3*2^126 value overflow) AGREE with
        // the JIT (both None); the Shl cases whose native result is `Some` are the
        // DOCUMENTED trust-cg Shl miscompile (the JIT never reaches `checked_shl`).
        (
            BINOP_SHL,
            Some(5),
            Some(128),
            "Shl 5<<128 => None (b>=128 guard) [agrees]",
        ),
        (
            BINOP_SHL,
            Some(5),
            Some(-1),
            "Shl 5<<-1 => None (b<0 guard) [agrees]",
        ),
        (
            BINOP_SHL,
            Some(3),
            Some(126),
            "Shl 3<<126 => None (3*2^126 overflows) [agrees]",
        ),
        (
            BINOP_SHL,
            Some(1),
            Some(0),
            "Shl 1<<0 => Some(1) [MISCOMPILE]",
        ),
        (
            BINOP_SHL,
            Some(3),
            Some(4),
            "Shl 3<<4 => Some(48) [MISCOMPILE]",
        ),
        (
            BINOP_SHL,
            Some(1),
            Some(126),
            "Shl 1<<126 => Some [MISCOMPILE]",
        ),
        (
            BINOP_SHL,
            Some(1),
            Some(127),
            "Shl 1<<127 => Some(i128::MIN) [MISCOMPILE]",
        ),
        (
            BINOP_SHL,
            Some(3),
            Some(63),
            "Shl 3<<63 => Some [MISCOMPILE]",
        ),
    ];

    // ── FULLY VERIFIED SURFACE — promoted 2026-07-02 ──────────────────────────
    //
    // Historically the Shl arm miscompiled inside the full multi-arm `fold_binop`
    // CFG — the JIT never reached `checked_shl` and returned None for every Shl
    // input.
    // Root cause was the aarch64 switch/BST block-id namespace collision, fixed in
    // trust-cg e49df83; the pinned five-case mismatch set went empty exactly as the
    // pin was designed to alarm, and the test was promoted: the ENTIRE `fold_binop`
    // surface (all arms incl. Shl-`Some`, the `?` short-circuit, the checked-arith
    // overflow->None boundary) must agree native == JIT, no allowances.
    let mut mismatches: Vec<&str> = Vec::new();
    for (op, lhs, rhs, label) in &cases {
        let native = vm_fold_binop(*op, *lhs, *rhs);
        let jit = jit_fold(*op, *lhs, *rhs);
        if native != jit {
            mismatches.push(label);
        }
    }
    assert!(
        mismatches.is_empty(),
        "fold_binop native == JIT diverged (was fully verified after trust-cg e49df83 \
         fixed the switch/BST collision): {mismatches:?}"
    );

    // NEGATIVE CONTROL on the VERIFIED surface: a corrupted oracle that uses WRAPPING
    // multiply for the `BinOp::Mul` arm (drops the overflow check), returning
    // Some(wrapped) where the real folder returns None. It must DISAGREE with the JIT
    // on the Mul-overflow case (which is on the VERIFIED, non-Shl surface), proving
    // the test discriminates the checked-arith path and is not vacuously passing.
    fn vm_fold_binop_corrupt(op: u8, lhs: Option<i128>, rhs: Option<i128>) -> Option<i128> {
        let (a, b) = (lhs?, rhs?);
        if op == BINOP_MUL {
            return Some(a.wrapping_mul(b)); // bug: wrapping, not checked
        }
        vm_fold_binop(op, Some(a), Some(b))
    }
    let corrupt = vm_fold_binop_corrupt(BINOP_MUL, Some(i128::MAX), Some(2)); // Some(wrapped)
    let jit_ov = jit_fold(BINOP_MUL, Some(i128::MAX), Some(2)); // None (correct)
    assert_ne!(
        corrupt, jit_ov,
        "negative control must FAIL: a wrapping Mul fold should disagree with the JIT's checked_mul"
    );
    assert_eq!(
        jit_ov, None,
        "JIT must return None when i128::MAX * 2 overflows"
    );

    drop(buffer);
}

