// `u128::saturating_sub(self, rhs) -> u128` — the one host leaf the slice would
// need (the `k.saturating_sub(1)` for `K-1`). Direct (u128, u128) -> u128 ABI.
const EXT_SAT_SUB_U128: &str = "_RNvMs8_NtCs2EYQwhfuABO_4core3numo14saturating_sub";
extern "C" fn sat_sub_u128_shim(a: u128, b: u128) -> u128 {
    a.saturating_sub(b)
}

// (Former pin removed — trust-cg now lowers `edge_bounds`; see the PROMOTED
// verification `trust_self_edge_bounds_roundtrip` below.)
// PROMOTED: the pinned i128 high-half ISel limit was fixed upstream, so
// `edge_bounds` is now a FULL native == JIT verification. The oracle below is
// transcribed VERBATIM from tests/slices/trust_edge_bounds_slice.rs (the
// production `edge_bounds`, alloc_bound.rs:427, its `ICmpOp` enum, `op_for_tag`,
// the single-`Option<u128>` `edge_bound_pick`, and the C-ABI-shaped entry) and is
// swept against the JIT over every (op_tag, k, which) tuple.
mod edge_bounds_oracle {
    // ICmpOp (inst.rs:73-86) — VERBATIM variant set & order.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    pub enum ICmpOp {
        Eq,
        Ne,
        Ult,
        Ule,
        Ugt,
        Uge,
        Slt,
        Sle,
        Sgt,
        Sge,
    }

    // edge_bounds (alloc_bound.rs:427-447) — byte-for-byte.
    fn edge_bounds(op: ICmpOp, k: Option<i128>) -> (Option<u128>, Option<u128>) {
        let Some(k) = k else { return (None, None) };
        if k < 0 {
            return (None, None);
        }
        let k = k as u128;
        let km1 = k.saturating_sub(1);
        match op {
            ICmpOp::Ult | ICmpOp::Slt => (Some(km1), None),
            ICmpOp::Ule | ICmpOp::Sle => (Some(k), None),
            ICmpOp::Ugt | ICmpOp::Sgt => (None, Some(k)),
            ICmpOp::Uge | ICmpOp::Sge => (None, Some(km1)),
            ICmpOp::Eq => (Some(k), None),
            ICmpOp::Ne => (None, Some(k)),
        }
    }

    fn op_for_tag(tag: u32) -> ICmpOp {
        match tag {
            0 => ICmpOp::Eq,
            1 => ICmpOp::Ne,
            2 => ICmpOp::Ult,
            3 => ICmpOp::Ule,
            4 => ICmpOp::Ugt,
            5 => ICmpOp::Uge,
            6 => ICmpOp::Slt,
            7 => ICmpOp::Sle,
            8 => ICmpOp::Sgt,
            _ => ICmpOp::Sge,
        }
    }

    fn edge_bound_pick(op: ICmpOp, k: Option<i128>, want_then: bool) -> Option<u128> {
        let edges = edge_bounds(op, k);
        if want_then { edges.0 } else { edges.1 }
    }

    // C-ABI-shaped native entry mirroring `@edge_bounds_entry`
    // (op_tag, k_present, k_hi, k_lo, which) -> u64.
    pub fn edge_bounds_entry(op_tag: u32, k_present: u32, k_hi: i64, k_lo: u64, which: u32) -> u64 {
        let k: Option<i128> = if k_present != 0 {
            Some(((k_hi as i128) << 64) | (k_lo as i128))
        } else {
            None
        };
        let op = op_for_tag(op_tag);
        let want_then = which < 3;
        let edge = edge_bound_pick(op, k, want_then);
        match which {
            0 | 3 => match edge {
                Some(_) => 1,
                None => 0,
            },
            1 | 4 => match edge {
                Some(v) => v as u64,
                None => 0,
            },
            _ => match edge {
                Some(v) => (v >> 64) as u64,
                None => 0,
            },
        }
    }
}

/// TRUST-SELF: the production `edge_bounds` (trust-ir/crates/trust-ir/src/
/// alloc_bound.rs:427) — the per-comparison SOUNDNESS core of the allocation-
/// bounds guard pass — lowered Rust -> MIR -> trust-ir -> trust-cg JIT -> machine
/// code == native Rust, over all 10 `ICmpOp` arms x a k-menu (None; k=0 saturation
/// edge; small; i64::MAX; a real high-half i128; negative; near i128::MAX) x all 6
/// `which` selectors. Extern: `u128::saturating_sub` for the `K-1` edge. This was
/// previously a pinned trust-cg i128 high-half ISel limit; it is now compiled and
/// verified.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn trust_self_edge_bounds_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("trust_self_edge_bounds_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_EDGE_BOUNDS_TRUST_IR)
        .expect("MIR-emitted `edge_bounds_entry` trust-ir must parse");
    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert(EXT_SAT_SUB_U128.to_string(), sat_sub_u128_shim as *const u8);
    let config = CompilerConfig::jit_fast(Target::Aarch64);
    let buffer = Compiler::new(config)
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect(
            "REGRESSION: trust-cg must JIT-compile `edge_bounds` (previously a pinned i128 \
             high-half ISel limit, now promoted to a full native==JIT verification)",
        )
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("edge_bounds_entry")
        .expect("JIT symbol `edge_bounds_entry` not found")
        .as_ptr();
    // SAFETY: machine code for `extern "C" fn(u32, u32, i64, u64, u32) -> u64`.
    let f: extern "C" fn(u32, u32, i64, u64, u32) -> u64 = unsafe { std::mem::transmute(raw) };

    // k-menu: (k_present, k_hi, k_lo). Covers None, the k=0 saturating-sub edge,
    // small values, a full low half, a value that needs the high limb, a genuine
    // two-limb i128, a negative k (the k<0 early return), and near i128::MAX.
    let k_menu: [(u32, i64, u64); 9] = [
        (0, 0, 0),                     // None
        (1, 0, 0),                     // k = 0  (km1 saturates to 0)
        (1, 0, 1),                     // k = 1
        (1, 0, 42),                    // k = 42
        (1, 0, u64::MAX),              // k = 2^64 - 1  (low half full)
        (1, 1, 0),                     // k = 2^64      (needs high half)
        (1, 0x0123_4567, 0x89AB_CDEF), // k with a real high-half
        (1, -1, 0),                    // k < 0         (negative-count early return)
        (1, i64::MAX, u64::MAX),       // k near i128::MAX
    ];

    let mut pass = 0usize;
    for op_tag in 0u32..=9 {
        for &(k_present, k_hi, k_lo) in &k_menu {
            for which in 0u32..=5 {
                let native =
                    edge_bounds_oracle::edge_bounds_entry(op_tag, k_present, k_hi, k_lo, which);
                let jit = f(op_tag, k_present, k_hi, k_lo, which);
                assert_eq!(
                    native, jit,
                    "edge_bounds JIT disagrees: op_tag={op_tag} k_present={k_present} \
                     k_hi={k_hi} k_lo={k_lo} which={which} native={native} jit={jit}"
                );
                pass += 1;
            }
        }
    }
    assert_eq!(
        pass,
        10 * k_menu.len() * 6,
        "every (op_tag, k, which) tuple must agree native == JIT"
    );

    // NEGATIVE CONTROL: `count < 10` (op=Ult, tag 2) implies a then-edge of 9. An
    // off-by-one oracle claiming the then-edge low half is 10 must DISAGREE with
    // the JIT, proving the differential discriminates values.
    let corrupt_then_lo = 10u64;
    let jit_then_lo = f(2, 1, 0, 10, 1); // op=Ult, k=10, which=1 (then-edge low)
    assert_ne!(
        corrupt_then_lo, jit_then_lo,
        "negative control must FAIL: an off-by-one then-edge should disagree with the JIT"
    );
    assert_eq!(
        jit_then_lo, 9,
        "JIT must compute `count < 10` then-edge = 9"
    );

    drop(buffer);
}
