// ── CrInductiveError: faithful mirror of the slice's three rejection variants.
//    The gate's i32 root distinguishes them: 1=head, 2=param, 3=index. The native
//    oracle below returns the SAME small-int code as the JIT root, so we compare ints
//    (avoiding any enum-payload layout dependency in the oracle).
type CrValidateFn = extern "C" fn(u32, u32, *const CwExpr, u32, u32, u32) -> i32;

// Native oracle: a VERBATIM transcription of the slice's validate_ctor_return_type
// over CwExpr, returning the SAME code (0=accept,1=head,2=param,3=index).
fn cr_mentions_name(e: &CwExpr, name: &CwName) -> bool {
    match &e.kind {
        CwExprKind::Const(n, _) => n == name,
        CwExprKind::BVar(_) | CwExprKind::FVar(_) | CwExprKind::Sort(_) | CwExprKind::Lit(_) => {
            false
        }
        CwExprKind::App(f, a) => cr_mentions_name(f, name) || cr_mentions_name(a, name),
        CwExprKind::Lam(_, ty, body) => cr_mentions_name(ty, name) || cr_mentions_name(body, name),
        CwExprKind::Pi(_, ty, body) => cr_mentions_name(ty, name) || cr_mentions_name(body, name),
        CwExprKind::Let(_, ty, val, body, _) => {
            cr_mentions_name(ty, name)
                || cr_mentions_name(val, name)
                || cr_mentions_name(body, name)
        }
        CwExprKind::Proj(_, _, x) => cr_mentions_name(x, name),
        CwExprKind::MData(_, inner) => cr_mentions_name(inner, name),
    }
}
fn cr_app_fn(e: &CwExpr) -> CwExpr {
    let mut cur = e.clone();
    loop {
        let next = match &cur.kind {
            CwExprKind::App(f, _) => f.as_ref().clone(),
            _ => return cur,
        };
        cur = next;
    }
}
fn cr_app_args(e: &CwExpr) -> Vec<CwExpr> {
    let mut args = Vec::new();
    let mut cur = e.clone();
    while let CwExprKind::App(f, a) = &cur.kind {
        args.push(a.as_ref().clone());
        let next = f.as_ref().clone();
        cur = next;
    }
    args.reverse();
    args
}
fn cr_count_pi_args(e: &CwExpr) -> u32 {
    let mut count = 0u32;
    let mut cur = e;
    while let CwExprKind::Pi(_, _, body) = &cur.kind {
        count = count.saturating_add(1);
        cur = body;
    }
    count
}
fn cr_get_return_type(e: &CwExpr) -> &CwExpr {
    let mut cur = e;
    while let CwExprKind::Pi(_, _, body) = &cur.kind {
        cur = body;
    }
    cur
}
// native validate_ctor_return_type -> 0=accept, 1=head, 2=param, 3=index.
fn cr_native_root(
    ind_raw: u32,
    ctor_type: &CwExpr,
    num_params: u32,
    sib_raw: u32,
    sib_count: u32,
) -> i32 {
    let ind = CwName(ind_raw);
    let sib = CwName(sib_raw);
    let one = [&ind];
    let two = [&ind, &sib];
    let all: &[&CwName] = if sib_count >= 2 { &two } else { &one };

    let return_type = cr_get_return_type(ctor_type);
    // (ordinary inductive: no CubicalPath — the cubical branch is never taken.)
    let head = cr_app_fn(return_type);
    // Check 1: head is the inductive Const.
    match &head.kind {
        CwExprKind::Const(name, _) if name == &ind => {}
        _ => return 1,
    }
    let args = cr_app_args(return_type);
    let args_len = args.len();
    // Check 2: param args = declared params as BVars.
    if num_params > 0 {
        let total_binders = cr_count_pi_args(ctor_type);
        let mut i: u32 = 0;
        while i < num_params {
            let mut param_ok = false;
            if total_binders > i {
                let expected = total_binders - 1 - i;
                let idx = i as usize;
                if idx < args_len
                    && let CwExprKind::BVar(b) = &args[idx].kind
                    && *b == expected
                {
                    param_ok = true;
                }
            }
            if !param_ok {
                return 2;
            }
            i += 1;
        }
    }
    // Check 3: index args must not mention any inductive in the block.
    let np = num_params as usize;
    let mut j = np;
    while j < args_len {
        let idx_arg = &args[j];
        for n in all {
            if cr_mentions_name(idx_arg, n) {
                return 3;
            }
        }
        j += 1;
    }
    0
}

/// END-TO-END MIR-PATH SOUNDNESS MILESTONE: the JIT-EXECUTED constructor return-type
/// GATE. native validate_ctor_return_type == JIT over accept + the three REJECT classes
/// (wrong head / param mismatch / index-mentions-inductive) + a negative control.
#[test]
#[cfg_attr(
    kernel_fixture_layout_lint_only,
    allow(unreachable_code, unused_variables)
)]
fn mir_real_expr_ctor_return_roundtrip() {
    #[cfg(kernel_fixture_layout_lint_only)]
    kernel_fixture_guard::refuse_uncertified_execution("mir_real_expr_ctor_return_roundtrip");
    let module = emitted_fixture::parse_emitted(MIR_CTOR_RETURN_CLOSURE_TRUST_IR)
        .expect("MIR-emitted validate_ctor_root closure trust-ir text must parse");

    // CONFIRM the gate engine is genuinely IN-MODULE (real bodies, not stubs) and that
    // it composes the VERIFIED App-spine pillar + the Pi-telescope walks + mentions_name.
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    assert!(
        bodied("validate_ctor_return_type"),
        "the GATE validate_ctor_return_type must be in-module (not a stub)"
    );
    assert!(
        bodied("get_return_type"),
        "the Pi-telescope return-type walk must be in-module"
    );
    assert!(
        bodied("count_pi_args"),
        "count_pi_args (param BVar-index check) must be in-module"
    );
    assert!(
        bodied("mentions_name"),
        "the structural Const-occurrence scan (index check) must be in-module"
    );
    assert!(
        bodied("Expr__get_app_fn") && bodied("Expr__get_app_args"),
        "the VERIFIED App-spine pillar must be in-module (head + arg decomposition)"
    );

    // CONFIRM the gate Calls all three checks' pillars (get_return_type=func.15,
    // get_app_fn=func.18, get_app_args=func.25, count_pi_args=func.27, mentions_name=func.29).
    let scope = |hdr: &str| -> &str {
        let s = MIR_CTOR_RETURN_CLOSURE_TRUST_IR
            .find(hdr)
            .expect("fn header present");
        let after = &MIR_CTOR_RETURN_CLOSURE_TRUST_IR[s + 1..];
        let e = after
            .find("\nfn @")
            .map(|i| s + 1 + i)
            .unwrap_or(MIR_CTOR_RETURN_CLOSURE_TRUST_IR.len());
        &MIR_CTOR_RETURN_CLOSURE_TRUST_IR[s..e]
    };
    let g = scope("fn @validate_ctor_return_type");
    assert!(
        g.contains("@func.15("),
        "gate must Call get_return_type (strip the Pi telescope)"
    );
    assert!(
        g.contains("@func.18("),
        "gate must Call get_app_fn (Check 1: return-type head)"
    );
    assert!(
        g.contains("@func.25("),
        "gate must Call get_app_args (Check 2/3: the arg list)"
    );
    assert!(
        g.contains("@func.27("),
        "gate must Call count_pi_args (Check 2: total binders for the BVar index)"
    );
    assert!(
        g.contains("@func.29("),
        "gate must Call mentions_name (Check 3: index-mentions-inductive reject)"
    );

    // ── AUTO-BIND the empty-body extern leaves by demangled-substring classification
    //    (the elim_zero pattern): each binds to a VERIFIED Cw*/cp_*/ez_* shim of
    //    byte-identical layout. ALL leaves MUST bind (asserted) — no silent stub.
    let empty_leaves: Vec<String> = {
        let lines: Vec<&str> = MIR_CTOR_RETURN_CLOSURE_TRUST_IR.lines().collect();
        let mut out = Vec::new();
        let mut i = 0usize;
        while i < lines.len() {
            if let Some(rest) = lines[i].strip_prefix("fn @")
                && let Some(name) = rest.split('(').next()
                && i + 1 < lines.len()
                && lines[i + 1].trim() == "}"
            {
                out.push(name.to_string());
            }
            i += 1;
        }
        out
    };

    let mut externs: HashMap<String, *const u8> = HashMap::new();
    externs.insert("__rust_alloc".to_string(), cw_shim_rust_alloc as *const u8);
    let mut unbound: Vec<String> = Vec::new();
    for sym in &empty_leaves {
        let s = sym.as_str();
        let shim: Option<*const u8> =
            // arithmetic primitives (ExprMeta hashing / count_pi_args)
            if s.contains("14saturating_add") { Some(cw_shim_sat_add as *const u8) }
            else if s.contains("14saturating_sub") { Some(cw_shim_sat_sub as *const u8) }
            else if s.contains("12wrapping_mul") { Some(cw_shim_wrap_mul as *const u8) }
            else if s.starts_with("_RNvYh") && s.contains("3Ord3max") { Some(cw_shim_max_u8 as *const u8) }
            else if s.starts_with("_RNvYh") && s.contains("3Ord3min") { Some(cw_shim_min_u8 as *const u8) }
            else if s.starts_with("_RNvYm") && s.contains("3Ord3max") { Some(ez_shim_max_usize as *const u8) }
            else if s.starts_with("_RNvYm") && s.contains("3Ord3min") { Some(ez_shim_min_usize as *const u8) }
            // KaniHasher Hash impls (compute_meta)
            else if s.contains("5implsmNtB8_4Hash4hash") { Some(cw_shim_hash_u32 as *const u8) }
            else if s.contains("5implsyNtB8_4Hash4hash") { Some(cw_shim_hash_u64 as *const u8) }
            else if s.contains("5implsiNtB8_4Hash4hash") { Some(cw_shim_hash_i32 as *const u8) }
            else if s.contains("3BoxNt") && s.contains("5Level") && s.contains("4Hash4hash") { Some(cw_shim_hash_box_level as *const u8) }
            // Name equality (Check 1 head test)
            else if s.contains("4NameNtB7_9PartialEq2eq") { Some(cw_shim_name_eq as *const u8) }
            // &[&Name] into_iter (Check 3 inner loop)
            else if s.contains("4NameNt") && s.contains("12IntoIterator9into_iter") { Some(cp_shim_names_into_iter as *const u8) }
            // Vec<Constructor>::new (root's empty ctor list)
            else if s.contains("11ConstructorE3new") { Some(ez_shim_vec_ctor_new as *const u8) }
            // Vec<InductiveType>::new (root's empty `decl.types`) — empty Vec, layout-agnostic.
            else if s.contains("13InductiveTypeE3new") { Some(ez_shim_vec_ctor_new as *const u8) }
            // Vec<Expr> ops (get_app_args build; args.len()/args[i])
            else if s.contains("3VecNt") && s.contains("4ExprE3new") { Some(cw_shim_vec_new as *const u8) }
            else if s.contains("3VecNt") && s.contains("4ExprE3len") { Some(cw_shim_vec_len as *const u8) }
            else if s.contains("3VecNt") && s.contains("4ExprE4push") { Some(cw_shim_vec_push as *const u8) }
            else if s.contains("3VecNt") && s.contains("4ExprE") && s.contains("5index5IndexjE5index") { Some(cw_shim_vec_index as *const u8) }
            else if s.contains("3VecNt") && s.contains("4ExprE") && s.contains("8DerefMut9deref_mut") { Some(cw_shim_vec_deref_mut as *const u8) }
            else if s.contains("SNt") && s.contains("4Expr7reverse") { Some(cw_shim_reverse as *const u8) }
            // Vec<Level>/Box<Level> clone (Expr clone in the root)
            else if s.contains("3VecNt") && s.contains("5LevelE") && s.contains("Clone5clone") { Some(cw_shim_vec_lvl_clone as *const u8) }
            else if s.contains("3BoxNt") && s.contains("5LevelE") && s.contains("Clone5clone") { Some(cw_shim_box_lvl_clone as *const u8) }
            // Arc<Expr> ops (App-spine walks)
            else if s.contains("3ArcNt") && s.contains("4ExprE") && s.contains("5AsRef") { Some(cw_shim_arc_as_ref as *const u8) }
            else if s.contains("3ArcNt") && s.contains("4ExprE") && s.contains("Clone5clone") { Some(cw_shim_arc_clone as *const u8) }
            else { None };
        match shim {
            Some(p) => {
                externs.insert(sym.clone(), p);
            }
            None => unbound.push(sym.clone()),
        }
    }
    assert!(
        unbound.is_empty(),
        "unbound extern leaves (need shims): {:#?}",
        unbound
    );
    assert_eq!(
        externs.len(),
        empty_leaves
            .iter()
            .collect::<std::collections::HashSet<_>>()
            .len()
            + 1,
        "every distinct empty-body leaf must be bound (plus __rust_alloc)"
    );

    let buffer = Compiler::new(CompilerConfig::jit_fast(Target::Aarch64))
        .with_codegen_license(permit_unlicensed())
        .compile_module_to_jit(&module, &externs)
        .expect("trust-cg JIT compile of MIR-emitted validate_ctor_root closure failed")
        .buffer;
    let raw = buffer
        .get_fn_ptr_bound("validate_ctor_root")
        .expect("JIT symbol `validate_ctor_root` not found")
        .as_ptr();
    let f: CrValidateFn = unsafe { std::mem::transmute(raw) };

    let bd = CwBinderData { info: 0, mult: 0 };
    let app = |x: CwExpr, y: CwExpr| CwExpr::app(x, y);
    let pi = |t: CwExpr, b: CwExpr| CwExpr::pi(bd, t, b);
    let cn = |k: u32| CwExpr::cnst(CwName(k));
    let bv = |i: u32| CwExpr::bvar(i);
    let sort = || CwExpr::sort0();
    // Names: Tree=1, Forest=2 (mutual sibling), Nat=11, List=12, Vec=13.
    const TREE: u32 = 1;
    const FOREST: u32 = 2;
    const CTORNM: u32 = 100;
    const NAT: u32 = 11;
    const LIST: u32 = 12;
    let tree = || cn(TREE);
    let nat = || cn(NAT);
    let list = || cn(LIST);

    // (ctor_type, ind_name, num_params, sibling, sibling_count, expect, label)
    //   expect: 0=accept, 1=wrong head, 2=param mismatch, 3=index mentions inductive.
    let cases: Vec<(CwExpr, u32, u32, u32, u32, i32, &str)> = vec![
        // ── ACCEPT ──
        // mk : Tree                              (nullary, head=Tree, no params/indices)
        (tree(), TREE, 0, 0, 1, 0, "Tree (nullary, head ok)"),
        // mk : Nat -> Tree                       (one field, head=Tree)
        (
            pi(nat(), tree()),
            TREE,
            0,
            0,
            1,
            0,
            "Nat -> Tree (head ok, no params)",
        ),
        // mk : Tree -> Tree                      (recursive field; head=Tree)
        (
            pi(tree(), tree()),
            TREE,
            0,
            0,
            1,
            0,
            "Tree -> Tree (recursive, head ok)",
        ),
        // 1 param A: mk : (A:Sort) -> Tree (BVar 0)   (param arg = BVar 0, ok)
        (
            pi(sort(), app(tree(), bv(0))),
            TREE,
            1,
            0,
            1,
            0,
            "(A) -> Tree A (param BVar 0 ok)",
        ),
        // 1 param A + one CLEAN index: mk : (A:Sort) -> Tree (BVar 0) Nat  (index=Nat, no ind)
        (
            pi(sort(), app(app(tree(), bv(0)), nat())),
            TREE,
            1,
            0,
            1,
            0,
            "(A) -> Tree A Nat (clean index)",
        ),
        // ── REJECT 1: wrong return-type head ──
        // mk : Nat -> Nat                        (returns Nat, not Tree)
        (
            pi(nat(), nat()),
            TREE,
            0,
            0,
            1,
            1,
            "Nat -> Nat (wrong head — REJECT 1)",
        ),
        // mk : Tree -> List                      (returns List, not Tree)
        (
            pi(tree(), list()),
            TREE,
            0,
            0,
            1,
            1,
            "Tree -> List (wrong head — REJECT 1)",
        ),
        // head not a Const: mk : (A:Sort) -> (BVar 0)   (return head is a BVar)
        (
            pi(sort(), bv(0)),
            TREE,
            0,
            0,
            1,
            1,
            "(A) -> BVar 0 (non-Const head — REJECT 1)",
        ),
        // ── REJECT 2: parameter arg mismatch ──
        // 1 param A: mk : (A:Sort) -> Tree Nat   (param arg is Nat, not BVar 0)
        (
            pi(sort(), app(tree(), nat())),
            TREE,
            1,
            0,
            1,
            2,
            "(A) -> Tree Nat (param != BVar 0 — REJECT 2)",
        ),
        // 1 param: mk : (A:Sort) -> Tree (BVar 1)  (wrong de-Bruijn index)
        (
            pi(sort(), app(tree(), bv(1))),
            TREE,
            1,
            0,
            1,
            2,
            "(A) -> Tree (BVar 1) (wrong index — REJECT 2)",
        ),
        // 1 param but NO args applied: mk : (A:Sort) -> Tree   (head ok, but param arg missing)
        (
            pi(sort(), tree()),
            TREE,
            1,
            0,
            1,
            2,
            "(A) -> Tree (param arg absent — REJECT 2)",
        ),
        // ── REJECT 3: index arg mentions the inductive (lean4#2125) ──
        // 1 param A: mk : (A:Sort) -> Tree (BVar 0) (List Tree)   (index `List Tree` mentions Tree)
        (
            pi(sort(), app(app(tree(), bv(0)), app(list(), tree()))),
            TREE,
            1,
            0,
            1,
            3,
            "(A) -> Tree A (List Tree) (index mentions Tree — REJECT 3)",
        ),
        // 0 params: mk : Tree Tree               (the single index arg is Tree itself)
        (
            app(tree(), tree()),
            TREE,
            0,
            0,
            1,
            3,
            "Tree Tree (index = Tree — REJECT 3)",
        ),
        // MUTUAL: 0 params: mk : Tree Forest, checking Tree with Forest the sibling.
        //   index `Forest` mentions the sibling -> REJECT 3 only when sibling_count=2.
        (
            app(tree(), cn(FOREST)),
            TREE,
            0,
            FOREST,
            2,
            3,
            "Tree Forest, mutual: index mentions sibling — REJECT 3",
        ),
    ];

    let mut pass = 0usize;
    for (e, ind, np, sib, sibc, expect, label) in &cases {
        let native = cr_native_root(*ind, e, *np, *sib, *sibc);
        let jit = f(CTORNM, *ind, e as *const CwExpr, *np, *sib, *sibc);
        assert_eq!(
            native, *expect,
            "native oracle wrong on `{label}` (native={native}, expect={expect})"
        );
        assert_eq!(
            native, jit,
            "MIR-emitted ctor-return JIT disagrees with native on `{label}`: native={native} jit={jit}"
        );
        pass += 1;
    }
    assert_eq!(
        pass,
        cases.len(),
        "all ctor-return cases must agree native == JIT"
    );

    // The MUTUAL-sibling distinction (Check 3), checked directly at the JIT:
    // `Tree Forest` (0 params, index arg = Forest) is ACCEPTED when Forest is NOT a
    // sibling (count=1, only Tree checked) but REJECTED (code 3) when Forest IS a
    // sibling (count=2) — the lean4#2125 mutual-block index rule.
    let mutual_ctor = app(tree(), cn(FOREST));
    let without_sibling = f(CTORNM, TREE, &mutual_ctor as *const CwExpr, 0, FOREST, 1);
    let with_sibling = f(CTORNM, TREE, &mutual_ctor as *const CwExpr, 0, FOREST, 2);
    assert_eq!(
        without_sibling, 0,
        "without the mutual sibling, index `Forest` is opaque (accepted)"
    );
    assert_eq!(
        with_sibling, 3,
        "WITH the mutual sibling, index `Forest` is REJECTED (lean4#2125)"
    );

    // NEGATIVE CONTROL (fail-loud): the gate MUST reject the index-self-reference ctor
    // `Tree Tree` (an index that mentions the inductive being defined). If Check 3 were
    // an Ok stub, this would (wrongly) accept and the assert fires.
    let bad_index = app(tree(), tree()); // Tree Tree
    assert_eq!(
        f(CTORNM, TREE, &bad_index as *const CwExpr, 0, 0, 1),
        3,
        "the gate MUST reject `Tree Tree` (index mentions the inductive — lean4#2125)"
    );
    let clean = pi(nat(), tree()); // Nat -> Tree
    assert_eq!(
        f(CTORNM, TREE, &clean as *const CwExpr, 0, 0, 1),
        0,
        "the gate MUST accept `Nat -> Tree` (a sound ctor)"
    );
    // A corrupt oracle that always accepts must DISAGREE with the JIT on the bad index.
    let corrupt_always_accept = 0i32;
    assert_ne!(
        corrupt_always_accept,
        f(CTORNM, TREE, &bad_index as *const CwExpr, 0, 0, 1),
        "negative control: an always-accept checker must disagree with the JIT on `Tree Tree`"
    );

    drop(buffer);
}

/// ===========================================================================
///  DECL-ADD TYPE-CORRECTNESS GATE — the UNIVERSAL gatekeeper (every decl).
/// ===========================================================================
/// When ANY declaration is added to the kernel environment
/// (`Environment::add_decl` / `check_decl_readonly` in
/// `$HOME/clean/crates/clean-kernel/src/env/decl_add.rs`), the soundness core runs
/// `check_type(value, type) = is_def_eq(infer_type(value), type)` (decl_add §7):
/// the value's INFERRED type must be DEFINITIONALLY EQUAL to the DECLARED type.
/// A bug here admits an ILL-TYPED definition — registering `thm : P := <proof of
/// R>`, i.e. "proving" P from a proof of a DIFFERENT proposition R — the kernel's
/// most fundamental unsoundness (EVERY definition/theorem/axiom passes this gate).
///
/// The FINAL accept/reject verdict — given the value's inferred-type graph and
/// the declared-type graph — is computed by the recursive definitional-equality
/// congruence engine in `cert/expr_eq.rs::def_eq_inner`: after WHNF, head-match
/// the two `Expr` sides and recurse with `def_eq` on every subterm
/// (App f/a, Pi/Lam ty/body, Sort levels, Const name+level-args, BVar index),
/// with `&&` short-circuit; a head mismatch is an immediate reject.
///
/// The embedded module below is the BYTE-VERBATIM `trust_ir_mir --mir-emit-closure
/// decl_value_ok` output of the self-contained slice
/// `frontend/dev-scratch/clean_decl_defeq_slice.rs`, whose `def_eq` is that
/// congruence engine over two ALREADY-BUILT `Expr` heap graphs (the read-only
/// position `def_eq_inner` is in AFTER its `whnf_for_eq` calls — the load-bearing
/// congruence DECISION; the orthogonal WHNF-reduction pillar supplies the
/// head-normal inputs). `decl_value_ok(value_ty, declared_ty)` returns 1 (ACCEPT:
/// value's type matches the declared type) or 0 (REJECT: the type mismatch).
