    externs.insert("_RNvMs_NtCskTzINo8ZBH9_5alloc3vecINtB4_3VecNtCs1kbsBhRuxrm_25clean_minor_premise_slice5LevelE3lenBG_".to_string(), cm_shim_vec_lvl_len as *const u8);
