// ════════════════════════════════════════════════════════════════════════════
// FULL RECURSOR-TYPE roundtrip — the SOUNDNESS-CRITICAL elimination-principle
// STATEMENT `Environment::build_recursor_type`
// (clean/crates/clean-kernel/src/env/inductive_recursor_types.rs:89), the capstone of
// the recursor picture: the just-verified `build_minor_premise_type` (per-ctor minor
// premise) and `build_recursor_rule_rhs` (iota computation rule) build the PARTS; this
// assembles the WHOLE recursor type
//   I.rec : (params) -> {motives} -> (minor_0)..(minor_{k-1}) ->
//           (indices) -> (major : I params indices) -> motive_j indices major
//
// WHY A BUG = UNSOUNDNESS. The recursor's TYPE **is** the elimination principle's
// statement. If the Pi-telescope is wrong — a motive over the wrong shape, a minor in
// the wrong slot / at the wrong de-Bruijn depth, a mis-lifted index domain, or a
// conclusion referencing the wrong motive/indices/major — then `I.rec` is TYPED at a
// principle STRONGER than justified: an eliminator whose conclusion does not follow
// from the discharged obligations, a direct route to `False`.
//
// The emitted closure carries the WHOLE construction IN-MODULE and composes the VERIFIED
// pillars over the real hashconsed CwExpr/CwExprMeta:
//   - Expr::{bvar,app,pi,sort,const_} -> from_kind -> compute_meta -> mk_app_meta /
//     mk_binder_meta / pack / mix_hash  (VERIFIED construction core; Arc::new -> heap_alloc).
//   - Expr::lift / lift_from -> lift_at  (the VERIFIED de-Bruijn lift).
//   - get_app_fn (VERIFIED App-spine head walk, via field_motive_index).
//   - has_loose_bvar_in_range (VERIFIED loose-bvar read, driving infer_implicit).
//   plus the recursor machinery: build_minor_premise_type (VERIFIED — the per-ctor
//   minor slots), count_pi_args, collect_pi_binders(_after_skip), ctor_motive_index,
//   field_motive_index, get_constructor_return_indices, count_pi_binders,
//   collect_pi_domains, remap_residual_index_bvars_for_minor, infer_implicit(_n),
//   has_loose_bvars_in_domain.
//
// Emit: EMIT-CLOSURE-OK build_rec_type_root: 297418 bytes; 74 closure members;
// validate_module = 0 errors; re-parse OK. Slice: dev-scratch/clean_recursor_type_slice.rs.
// (The slice's iterator adapters — enumerate/rev/map/collect/position — are lowered to the
// equivalent explicit index loops; de-Bruijn arithmetic + every Expr construction are
// byte-for-byte verbatim, confirmed by an identical native meta word.)
//
// MODELING BOUNDARY (documented): `InductiveType` is modeled as `{name, type_,
// constructors:[{name,type_}]}` — exactly the fields the fn reads via `all_types`
// (`.name`, `.type_` for the motive-type arity, `.constructors` for the HIT check).
// `ctor_path_data` returns None (no CubicalPath in this model; all test inductives are
// non-HIT), so the path-minor branch is provably dead. `consume_type_annotations` is a
// no-op (no synthetic domain uses a reserved wrapper Name). `BinderInfo` -> the {info,mult}
// scalar; the Const has_level_param bit is computed slice-faithfully via ct_const.
// ════════════════════════════════════════════════════════════════════════════

// Ct* mirror — reuses the Cw* Expr/Level/BinderData (byte-identical to the slice) + the
// slice-faithful cm_const (has_level_param bit) + a fresh InductiveType carrying `type_`.
#[derive(Clone, Debug)]
#[allow(dead_code)]
struct CtCtor {
    name: CwName,
    type_: CwExpr,
}

#[derive(Clone, Debug)]
#[allow(dead_code)]
struct CtInductiveType {
    name: CwName,
    type_: CwExpr,
    constructors: Vec<CtCtor>,
}

#[derive(Clone, Debug)]
#[allow(dead_code)]
struct CtCtorInfo {
    name: CwName,
    num_fields: u32,
    recursive_flags: Vec<bool>,
    field_types: Vec<CwExpr>,
    return_indices: Vec<CwExpr>,
}

const CT_IND: u32 = 1;
const CT_PARAM0: u32 = 50;
const CT_IDX_TY: u32 = 55;
const CT_CTOR_BASE: u32 = 100;
const CT_ULEVEL: u32 = 7;

#[inline]
fn ct_usize_to_u32(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}
const CT_INFO_DEFAULT: u8 = 0;

// ── recursor-type-specific pillars over CwExpr / CtInductiveType ──

fn ct_field_motive_index(field_ty: &CwExpr, all_types: &[CtInductiveType]) -> usize {
    // get_return_type + get_app_fn (both reuse the verified head walk).
    let mut ret_ty = field_ty;
    while let CwExprKind::Pi(_, _, body) = &ret_ty.kind {
        ret_ty = body;
    }
    let mut head = ret_ty;
    while let CwExprKind::App(f, _) = &head.kind {
        head = f;
    }
    if let CwExprKind::Const(name, _) = &head.kind {
        let mut idx = 0usize;
        while idx < all_types.len() {
            if &all_types[idx].name == name {
                return idx;
            }
            idx += 1;
        }
    }
    0
}

fn ct_ctor_motive_index(ctor_name: &CwName, all_types: &[CtInductiveType]) -> usize {
    let mut idx = 0usize;
    while idx < all_types.len() {
        let mut ci = 0usize;
        while ci < all_types[idx].constructors.len() {
            if &all_types[idx].constructors[ci].name == ctor_name {
                return idx;
            }
            ci += 1;
        }
        idx += 1;
    }
    0
}

// ctor_path_data always None (non-HIT model).
fn ct_ctor_path_data(
    _ctor_name: &CwName,
    _all_types: &[CtInductiveType],
) -> Option<(CwExpr, CwExpr)> {
    None
}

fn ct_count_pi_args(expr: &CwExpr) -> u32 {
    let mut count = 0u32;
    let mut current = expr;
    while let CwExprKind::Pi(_, _, body) = &current.kind {
        count = count.saturating_add(1);
        current = body;
    }
    count
}

fn ct_count_pi_binders(expr: &CwExpr) -> usize {
    let mut count = 0;
    let mut current = expr;
    while let CwExprKind::Pi(_, _, body) = &current.kind {
        count += 1;
        current = body;
    }
    count
}

fn ct_collect_pi_domains(expr: &CwExpr) -> Vec<(CwBinderData, CwExpr)> {
    let mut domains = Vec::new();
    let mut current = expr;
    while let CwExprKind::Pi(bi, domain, body) = &current.kind {
        domains.push((*bi, (**domain).clone()));
        current = body;
    }
    domains
}

// consume_type_annotations: no-op (modeled).
fn ct_consume_type_annotations(expr: &CwExpr) -> &CwExpr {
    expr
}

fn ct_collect_pi_binders(ty: &CwExpr, count: u32) -> Vec<(CwBinderData, CwExpr)> {
    let mut result = Vec::new();
    let mut current = ty.clone();
    let mut collected = 0u32;
    while collected < count {
        if let CwExprKind::Pi(bi, domain, codomain) = &current.kind {
            result.push((*bi, ct_consume_type_annotations(domain).clone()));
            current = (**codomain).clone();
            collected += 1;
        } else {
            break;
        }
    }
    result
}

fn ct_collect_pi_binders_after_skip(
    ty: &CwExpr,
    skip: u32,
    count: u32,
) -> Vec<(CwBinderData, CwExpr)> {
    let mut current = ty.clone();
    let mut s = 0u32;
    while s < skip {
        if let CwExprKind::Pi(_, _, body) = &current.kind {
            current = (**body).clone();
        }
        s += 1;
    }
    ct_collect_pi_binders(&current, count)
}

fn ct_get_constructor_return_indices(ctor_ty: &CwExpr, num_params: u32) -> Vec<CwExpr> {
    let mut current = ctor_ty.clone();
    while let CwExprKind::Pi(_, _, codomain) = &current.kind {
        current = (**codomain).clone();
    }
    let mut args: Vec<CwExpr> = Vec::new();
    while let CwExprKind::App(f, a) = &current.kind {
        args.push((**a).clone());
        current = (**f).clone();
    }
    let np = num_params as usize;
    let n = args.len();
    let mut out: Vec<CwExpr> = Vec::new();
    let mut s = 0usize;
    while s < n {
        if s >= np {
            out.push(args[n - 1 - s].clone());
        }
        s += 1;
    }
    out
}

fn ct_remap_residual_index_bvars_for_minor(
    expr: &CwExpr,
    field_idx: usize,
    nf: usize,
    ih_offset: usize,
    n_pis: usize,
) -> CwExpr {
    match &expr.kind {
        CwExprKind::BVar(k) => {
            let k = *k as usize;
            let new_k = if k < n_pis {
                k
            } else {
                let ctor_k = k - n_pis;
                if ctor_k < field_idx {
                    let field_j = field_idx - 1 - ctor_k;
                    ih_offset + nf - 1 - field_j + n_pis
                } else {
                    let param_j = ctor_k - field_idx;
                    ih_offset + nf + 1 + param_j + n_pis
                }
            };
            CwExpr::bvar(ct_usize_to_u32(new_k))
        }
        CwExprKind::App(f, a) => {
            let f2 = ct_remap_residual_index_bvars_for_minor(f, field_idx, nf, ih_offset, n_pis);
            let a2 = ct_remap_residual_index_bvars_for_minor(a, field_idx, nf, ih_offset, n_pis);
            CwExpr::app(f2, a2)
        }
        _ => expr.clone(),
    }
}

// ── has_loose_bvar reads + infer_implicit (drives the strict implicit-binder inference) ──

fn ct_bvar_in_range(idx: u32, start: u32, end: u32) -> bool {
    if end == u32::MAX {
        idx >= start
    } else {
        idx >= start && idx < end
    }
}
fn ct_shift_bvar_range(start: u32, end: u32) -> Option<(u32, u32)> {
    if end != u32::MAX && start >= end {
        return None;
    }
    if start == u32::MAX {
        return None;
    }
    let next_start = start.saturating_add(1);
    let next_end = if end == u32::MAX {
        u32::MAX
    } else {
        end.saturating_add(1)
    };
    Some((next_start, next_end))
}
fn ct_has_loose_bvar_in_range(e: &CwExpr, start: u32, end: u32) -> bool {
    if end != u32::MAX && start >= end {
        return false;
    }
    if e.loose_bvar_range() <= start {
        return false;
    }
    match &e.kind {
        CwExprKind::BVar(idx) => ct_bvar_in_range(*idx, start, end),
        CwExprKind::FVar(_)
        | CwExprKind::Sort(_)
        | CwExprKind::Const(_, _)
        | CwExprKind::Lit(_) => false,
        CwExprKind::App(f, a) => {
            ct_has_loose_bvar_in_range(f, start, end) || ct_has_loose_bvar_in_range(a, start, end)
        }
        CwExprKind::Lam(_, ty, body) | CwExprKind::Pi(_, ty, body) => {
            let body_has = match ct_shift_bvar_range(start, end) {
                Some((s, en)) => ct_has_loose_bvar_in_range(body, s, en),
                None => false,
            };
            ct_has_loose_bvar_in_range(ty, start, end) || body_has
        }
        CwExprKind::Let(_, ty, val, body, _) => {
            let body_has = match ct_shift_bvar_range(start, end) {
                Some((s, en)) => ct_has_loose_bvar_in_range(body, s, en),
                None => false,
            };
            ct_has_loose_bvar_in_range(ty, start, end)
                || ct_has_loose_bvar_in_range(val, start, end)
                || body_has
        }
        CwExprKind::Proj(_, _, ee) => ct_has_loose_bvar_in_range(ee, start, end),
        CwExprKind::MData(_, inner) => ct_has_loose_bvar_in_range(inner, start, end),
    }
}
fn ct_has_loose_bvar(e: &CwExpr, idx: u32) -> bool {
    ct_has_loose_bvar_in_range(e, idx, idx + 1)
}

fn ct_has_loose_bvars_in_domain(b: &CwExpr, vidx: u32, strict: bool) -> bool {
    match &b.kind {
        CwExprKind::Pi(bd, domain, body) => {
            if ct_has_loose_bvar(domain, vidx) {
                if bd.info == CT_INFO_DEFAULT {
                    return true;
                } else if ct_has_loose_bvars_in_domain(body, 0, strict) {
                    return true;
                }
            }
            ct_has_loose_bvars_in_domain(body, vidx + 1, strict)
        }
        _ => {
            if !strict {
                ct_has_loose_bvar(b, vidx)
            } else {
                false
            }
        }
    }
}
fn ct_infer_implicit_n(e: &CwExpr, num_params: u32, strict: bool) -> CwExpr {
    if num_params == 0 {
        return e.clone();
    }
    match &e.kind {
        CwExprKind::Pi(bd, domain, body) => {
            let new_body = ct_infer_implicit_n(body, num_params - 1, strict);
            if bd.info != CT_INFO_DEFAULT {
                CwExpr::pi(*bd, (**domain).clone(), new_body)
            } else if ct_has_loose_bvars_in_domain(&new_body, 0, strict) {
                CwExpr::pi(
                    CwBinderData {
                        info: 1,
                        mult: bd.mult,
                    },
                    (**domain).clone(),
                    new_body,
                )
            } else {
                CwExpr::pi(*bd, (**domain).clone(), new_body)
            }
        }
        _ => e.clone(),
    }
}
fn ct_infer_implicit(e: &CwExpr, strict: bool) -> CwExpr {
    ct_infer_implicit_n(e, u32::MAX, strict)
}

// ── VERIFIED PILLAR: build_minor_premise_type over CtInductiveType (verbatim mirror) ──
fn ct_build_minor_premise_type(
    ind_name: &CwName,
    ctor_name: &CwName,
    num_fields: u32,
    recursive_flags: &[bool],
    field_types: &[CwExpr],
    num_params: u32,
    ind_level_params: &[CwName],
    ctor_indices: &[CwExpr],
    num_motives: usize,
    conclusion_motive_idx: usize,
    all_types: &[CtInductiveType],
) -> CwExpr {
    let mut num_ihs: usize = 0;
    {
        let mut i = 0usize;
        while i < recursive_flags.len() {
            if recursive_flags[i] {
                num_ihs += 1;
            }
            i += 1;
        }
    }
    let num_fields = num_fields as usize;
    let conclusion_motive_bvar = num_fields + num_ihs + (num_motives - 1 - conclusion_motive_idx);

    let adjust_index_expr = |expr: CwExpr, ih_offset: usize| -> CwExpr {
        let mut adjusted = expr.lift_at(0, ct_usize_to_u32(ih_offset));
        adjusted = adjusted.lift_from(ct_usize_to_u32(ih_offset + num_fields), num_motives as u32);
        adjusted
    };

    let mut ctor_levels: Vec<CwLevel> = Vec::new();
    {
        let mut i = 0usize;
        while i < ind_level_params.len() {
            ctor_levels.push(CwLevel::Param(ind_level_params[i]));
            i += 1;
        }
    }
    let mut ctor_app = ct_const(*ctor_name, ctor_levels);
    {
        let mut i: u32 = 0;
        while i < num_params {
            let param_depth =
                num_fields + num_ihs + num_motives + (num_params as usize - 1 - i as usize);
            ctor_app = CwExpr::app(ctor_app, CwExpr::bvar(ct_usize_to_u32(param_depth)));
            i += 1;
        }
    }
    {
        let mut i: usize = 0;
        while i < num_fields {
            let field_depth = (num_fields - 1 - i) + num_ihs;
            ctor_app = CwExpr::app(ctor_app, CwExpr::bvar(ct_usize_to_u32(field_depth)));
            i += 1;
        }
    }

    let mut result = CwExpr::bvar(ct_usize_to_u32(conclusion_motive_bvar));
    {
        let mut i = 0usize;
        while i < ctor_indices.len() {
            let adjusted = adjust_index_expr(ctor_indices[i].clone(), num_ihs);
            result = CwExpr::app(result, adjusted);
            i += 1;
        }
    }
    result = CwExpr::app(result, ctor_app);

    let mut ih_offset = 0usize;
    let mut ri = recursive_flags.len();
    while ri > 0 {
        ri -= 1;
        let i = ri;
        if recursive_flags[i] {
            let ihs_above = num_ihs - 1 - ih_offset;
            let field_depth = (num_fields - 1 - i) + ihs_above;
            let ih_motive_idx = match field_types.get(i) {
                Some(ft) => ct_field_motive_index(ft, all_types),
                None => conclusion_motive_idx,
            };
            let motive_at_ih = num_fields + ihs_above + (num_motives - 1 - ih_motive_idx);
            let n_pis = match field_types.get(i) {
                Some(ft) => ct_count_pi_binders(ft),
                None => 0,
            };
            let ih_motive = motive_at_ih + n_pis;
            let ih_field_depth = field_depth + n_pis;
            let mut ih_type = CwExpr::bvar(ct_usize_to_u32(ih_motive));
            let field_ty = match field_types.get(i) {
                Some(ft) => ft.clone(),
                None => ct_ind_const_with_levels(ind_name, ind_level_params),
            };
            let field_indices = ct_get_constructor_return_indices(&field_ty, num_params);
            {
                let mut fi = 0usize;
                while fi < field_indices.len() {
                    let remapped = ct_remap_residual_index_bvars_for_minor(
                        &field_indices[fi],
                        i,
                        num_fields,
                        ihs_above,
                        n_pis,
                    );
                    ih_type = CwExpr::app(ih_type, remapped);
                    fi += 1;
                }
            }
            let mut major = CwExpr::bvar(ct_usize_to_u32(ih_field_depth));
            {
                let mut k = n_pis;
                while k > 0 {
                    k -= 1;
                    major = CwExpr::app(major, CwExpr::bvar(ct_usize_to_u32(k)));
                }
            }
            ih_type = CwExpr::app(ih_type, major);
            let pi_domains = match field_types.get(i) {
                Some(ft) => ct_collect_pi_domains(ft),
                None => Vec::new(),
            };
            {
                let mut pd = pi_domains.len();
                while pd > 0 {
                    pd -= 1;
                    let k = pd;
                    let (bi, domain) = &pi_domains[k];
                    let remapped = ct_remap_residual_index_bvars_for_minor(
                        domain, i, num_fields, ihs_above, k,
                    );
                    ih_type = CwExpr::pi(*bi, remapped, ih_type);
                }
            }
            result = CwExpr::pi(ct_bi_default(), ih_type, result);
            ih_offset += 1;
        }
    }

    {
        let mut fb = num_fields;
        while fb > 0 {
            fb -= 1;
            let i = fb;
            let field_ty = match field_types.get(i) {
                Some(ft) => ft.clone(),
                None => ct_ind_const_with_levels(ind_name, ind_level_params),
            };
            let lifted_field_ty = field_ty.lift_from(ct_usize_to_u32(i), num_motives as u32);
            result = CwExpr::pi(ct_bi_default(), lifted_field_ty, result);
        }
    }

    result
}

// ── THE FN: build_recursor_type over CtInductiveType/CtCtorInfo (verbatim mirror) ──
fn ct_build_recursor_type(
    ind_name: &CwName,
    ind_type: &CwExpr,
    num_params: u32,
    num_indices: u32,
    motive_univ_name: Option<&CwName>,
    ind_level_params: &[CwName],
    ctor_infos: &[CtCtorInfo],
    all_types: &[CtInductiveType],
) -> CwExpr {
    let motive_univ = match motive_univ_name {
        Some(name) => CwLevel::Param(*name),
        None => CwLevel::Zero,
    };
    let ind_const = ct_ind_const_with_levels(ind_name, ind_level_params);
    let num_motives = all_types.len();

    let param_binders = ct_collect_pi_binders(ind_type, num_params);
    let mut current = ind_type.clone();
    {
        let mut p = 0u32;
        while p < num_params {
            if let CwExprKind::Pi(_, _, body) = &current.kind {
                current = (**body).clone();
            }
            p += 1;
        }
    }
    let index_binders = ct_collect_pi_binders(&current, num_indices);
    let num_minors = ctor_infos.len();

    let build_ind_app = |param_offset: u32, index_offset: u32| -> CwExpr {
        let mut ind_app = ind_const.clone();
        {
            let mut i: u32 = 0;
            while i < num_params {
                let idx = param_offset + (num_params - 1 - i);
                ind_app = CwExpr::app(ind_app, CwExpr::bvar(idx));
                i += 1;
            }
        }
        {
            let mut i: u32 = 0;
            while i < num_indices {
                let idx = index_offset + (num_indices - 1 - i);
                ind_app = CwExpr::app(ind_app, CwExpr::bvar(idx));
                i += 1;
            }
        }
        ind_app
    };

    let mut motive_types: Vec<CwExpr> = Vec::with_capacity(num_motives);
    {
        let mut t = 0usize;
        while t < all_types.len() {
            let ti = &all_types[t];
            let t_const = ct_ind_const_with_levels(&ti.name, ind_level_params);
            let t_type_arity = ct_count_pi_args(&ti.type_);
            let t_num_indices = t_type_arity.saturating_sub(num_params);
            let t_index_binders =
                ct_collect_pi_binders_after_skip(&ti.type_, num_params, t_num_indices);
            let mut mtype = CwExpr::from_kind(CwExprKind::Sort(motive_univ.clone()));
            let mut major_ty_for_motive = t_const.clone();
            {
                let mut i: u32 = 0;
                while i < num_params {
                    let idx = t_num_indices + (num_params - 1 - i);
                    major_ty_for_motive = CwExpr::app(major_ty_for_motive, CwExpr::bvar(idx));
                    i += 1;
                }
            }
            {
                let mut i: u32 = 0;
                while i < t_num_indices {
                    let idx = t_num_indices - 1 - i;
                    major_ty_for_motive = CwExpr::app(major_ty_for_motive, CwExpr::bvar(idx));
                    i += 1;
                }
            }
            mtype = CwExpr::pi(ct_bi_default(), major_ty_for_motive, mtype);
            {
                let mut ib = t_index_binders.len();
                while ib > 0 {
                    ib -= 1;
                    let (binder_info, index_ty) = &t_index_binders[ib];
                    mtype = CwExpr::pi(*binder_info, index_ty.clone(), mtype);
                }
            }
            motive_types.push(mtype);
            t += 1;
        }
    }

    let this_motive_idx = {
        let mut found: Option<usize> = None;
        let mut i = 0usize;
        while i < all_types.len() {
            if &all_types[i].name == ind_name {
                found = Some(i);
                break;
            }
            i += 1;
        }
        found.unwrap_or_default()
    };

    let mut minor_types: Vec<(CwExpr, bool)> = Vec::new();
    {
        let mut minor_self_idx = 0usize;
        while minor_self_idx < ctor_infos.len() {
            let ci = &ctor_infos[minor_self_idx];
            let ctor_motive_idx = ct_ctor_motive_index(&ci.name, all_types);
            match ct_ctor_path_data(&ci.name, all_types) {
                Some(_lr) => {
                    minor_types.push((CwExpr::bvar(0), true));
                }
                None => {
                    let minor_ty = ct_build_minor_premise_type(
                        ind_name,
                        &ci.name,
                        ci.num_fields,
                        &ci.recursive_flags,
                        &ci.field_types,
                        num_params,
                        ind_level_params,
                        &ci.return_indices,
                        num_motives,
                        ctor_motive_idx,
                        all_types,
                    );
                    minor_types.push((minor_ty, false));
                }
            }
            minor_self_idx += 1;
        }
    }

    let this_motive_bvar = ct_usize_to_u32(
        num_minors + num_indices as usize + 1 + (num_motives - 1 - this_motive_idx),
    );
    let mut result_ty = CwExpr::bvar(this_motive_bvar);
    {
        let mut i: u32 = 0;
        while i < num_indices {
            let idx = ct_usize_to_u32(num_indices as usize - i as usize);
            result_ty = CwExpr::app(result_ty, CwExpr::bvar(idx));
            i += 1;
        }
    }
    result_ty = CwExpr::app(result_ty, CwExpr::bvar(0));

    let major_ty = build_ind_app(num_indices + num_minors as u32 + num_motives as u32, 0);
    result_ty = CwExpr::pi(ct_bi_default(), major_ty, result_ty);

    let extra = ct_usize_to_u32(num_minors + num_motives);
    {
        let mut ix = index_binders.len();
        while ix > 0 {
            ix -= 1;
            let i = ix;
            let (binder_info, index_ty) = &index_binders[i];
            let lifted_index_ty = if extra > 0 {
                index_ty.lift_from(i as u32, extra)
            } else {
                index_ty.clone()
            };
            result_ty = CwExpr::pi(*binder_info, lifted_index_ty, result_ty);
        }
    }

    {
        let mut m = minor_types.len();
        while m > 0 {
            m -= 1;
            let i = m;
            let (minor_ty, is_path) = &minor_types[i];
            let lifted_minor_ty = if *is_path || i == 0 {
                minor_ty.clone()
            } else {
                minor_ty.lift_at(0, ct_usize_to_u32(i))
            };
            result_ty = CwExpr::pi(ct_bi_default(), lifted_minor_ty, result_ty);
        }
    }

    {
        let mut mo = motive_types.len();
        while mo > 0 {
            mo -= 1;
            let i = mo;
            let mtype = &motive_types[i];
            let lifted_mtype = if i > 0 {
                mtype.lift_at(0, ct_usize_to_u32(i))
            } else {
                mtype.clone()
            };
            result_ty = CwExpr::pi(ct_bi_implicit(), lifted_mtype, result_ty);
        }
    }

    {
        let mut pb = param_binders.len();
        while pb > 0 {
            pb -= 1;
            let (binder_info, param_ty) = &param_binders[pb];
            result_ty = CwExpr::pi(*binder_info, param_ty.clone(), result_ty);
        }
    }

    result_ty = ct_infer_implicit(&result_ty, true);
    result_ty
}

// ── slice-faithful Const + helpers (has_level_param bit) ──
fn ct_const(name: CwName, levels: Vec<CwLevel>) -> CwExpr {
    let name_hash = cw_hash_to_u64(&name);
    let mut has_param = false;
    let mut i = 0usize;
    while i < levels.len() {
        if levels[i].has_params() {
            has_param = true;
        }
        i += 1;
    }
    let meta = CwExprMeta::pack(
        cw_mix_hash(5, name_hash) as u32,
        0,
        0,
        false,
        false,
        false,
        has_param,
    );
    CwExpr {
        kind: CwExprKind::Const(name, levels),
        meta,
    }
}
fn ct_ind_const_with_levels(name: &CwName, level_params: &[CwName]) -> CwExpr {
    let mut levels: Vec<CwLevel> = Vec::new();
    let mut i = 0usize;
    while i < level_params.len() {
        levels.push(CwLevel::Param(level_params[i]));
        i += 1;
    }
    ct_const(*name, levels)
}
#[inline]
fn ct_bi_default() -> CwBinderData {
    CwBinderData { info: 0, mult: 0 }
}
#[inline]
fn ct_bi_implicit() -> CwBinderData {
    CwBinderData { info: 1, mult: 0 }
}

// ── caller-side builders (mirror the slice's) ──
fn ct_build_field_ty(field_kind: u8, level_params: &[CwName]) -> CwExpr {
    match field_kind {
        0 => ct_ind_const_with_levels(&CwName(CT_IND), level_params),
        2 => {
            let head = ct_ind_const_with_levels(&CwName(CT_IND), level_params);
            CwExpr::app(head, CwExpr::bvar(0))
        }
        3 => {
            let head = ct_ind_const_with_levels(&CwName(CT_IND), level_params);
            CwExpr::pi(
                ct_bi_default(),
                ct_const(CwName(CT_PARAM0), Vec::new()),
                head,
            )
        }
        _ => ct_const(CwName(CT_PARAM0), Vec::new()),
    }
}
fn ct_build_return_indices(kinds: &[u8]) -> Vec<CwExpr> {
    let mut v: Vec<CwExpr> = Vec::new();
    let mut i = 0usize;
    while i < kinds.len() {
        if kinds[i] == 0 {
            v.push(CwExpr::bvar(0));
        } else {
            v.push(ct_const(CwName(CT_PARAM0), Vec::new()));
        }
        i += 1;
    }
    v
}
fn ct_build_ind_type(np: u32, ni: u32, level_params: &[CwName]) -> CwExpr {
    let mut ty = CwExpr::sort(CwLevel::Param(level_params[0]));
    {
        let mut i = 0u32;
        while i < ni {
            ty = CwExpr::pi(ct_bi_default(), ct_const(CwName(CT_IDX_TY), Vec::new()), ty);
            i += 1;
        }
    }
    {
        let mut i = 0u32;
        while i < np {
            ty = CwExpr::pi(ct_bi_default(), ct_const(CwName(CT_PARAM0), Vec::new()), ty);
            i += 1;
        }
    }
    ty
}

// Compact specs mirroring the slice's harness.
#[derive(Clone)]
struct CtCtorSpec {
    name_raw: u32,
    field_kinds: Vec<u8>,
    recursive_flags: Vec<bool>,
    return_index_kinds: Vec<u8>,
}
#[derive(Clone)]
struct CtIndSpec {
    num_params: u32,
    num_indices: u32,
    motive_univ_is_some: u32,
    ctors: Vec<CtCtorSpec>,
}

fn ct_assemble(spec: &CtIndSpec) -> (CwExpr, Vec<CwName>, Vec<CtInductiveType>, Vec<CtCtorInfo>) {
    let level_params = vec![CwName(CT_ULEVEL)];
    let ind_type = ct_build_ind_type(spec.num_params, spec.num_indices, &level_params);
    let mut ctors_meta: Vec<CtCtor> = Vec::new();
    for cs in &spec.ctors {
        ctors_meta.push(CtCtor {
            name: CwName(cs.name_raw),
            type_: ct_const(CwName(CT_IND), Vec::new()),
        });
    }
    let all_types = vec![CtInductiveType {
        name: CwName(CT_IND),
        type_: ind_type.clone(),
        constructors: ctors_meta,
    }];
    let mut ctor_infos: Vec<CtCtorInfo> = Vec::new();
    for cs in &spec.ctors {
        let mut ft: Vec<CwExpr> = Vec::new();
        for &k in &cs.field_kinds {
            ft.push(ct_build_field_ty(k, &level_params));
        }
        ctor_infos.push(CtCtorInfo {
            name: CwName(cs.name_raw),
            num_fields: cs.field_kinds.len() as u32,
            recursive_flags: cs.recursive_flags.clone(),
            field_types: ft,
            return_indices: ct_build_return_indices(&cs.return_index_kinds),
        });
    }
    (ind_type, level_params, all_types, ctor_infos)
}

fn ct_native_rec_type(spec: &CtIndSpec) -> CwExpr {
    let (ind_type, level_params, all_types, ctor_infos) = ct_assemble(spec);
    let ulevel = CwName(CT_ULEVEL);
    let motive_univ_name: Option<&CwName> = if spec.motive_univ_is_some != 0 {
        Some(&ulevel)
    } else {
        None
    };
    ct_build_recursor_type(
        &CwName(CT_IND),
        &ind_type,
        spec.num_params,
        spec.num_indices,
        motive_univ_name,
        &level_params,
        &ctor_infos,
        &all_types,
    )
}

fn ct_deep_eq(a: &CwExpr, b: &CwExpr) -> bool {
    if a.meta.raw() != b.meta.raw() {
        return false;
    }
    match (&a.kind, &b.kind) {
        (CwExprKind::BVar(x), CwExprKind::BVar(y)) => x == y,
        (CwExprKind::Const(n1, l1), CwExprKind::Const(n2, l2)) => n1 == n2 && l1 == l2,
        (CwExprKind::Sort(x), CwExprKind::Sort(y)) => x == y,
        (CwExprKind::App(f1, a1), CwExprKind::App(f2, a2)) => {
            ct_deep_eq(f1, f2) && ct_deep_eq(a1, a2)
        }
        (CwExprKind::Pi(b1, t1, y1), CwExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && ct_deep_eq(t1, t2) && ct_deep_eq(y1, y2)
        }
        (CwExprKind::Lam(b1, t1, y1), CwExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && ct_deep_eq(t1, t2) && ct_deep_eq(y1, y2)
        }
        _ => false,
    }
}

