    externs.insert("_RNvXs7_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecbENtNtNtCs2EYQwhfuABO_4core3ops5deref5Deref5derefCskGOzeDtWnTB_25clean_recursor_type_slice".to_string(), ct_shim_vec_bool_deref as *const u8);
