    externs.insert("_RNvXs7_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCskGOzeDtWnTB_25clean_recursor_type_slice8CtorInfoENtNtNtCs2EYQwhfuABO_4core3ops5deref5Deref5derefBH_".to_string(), ct_shim_vec_ctorinfo_deref as *const u8);
