    externs.insert("_RNvXsc_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCskGOzeDtWnTB_25clean_recursor_type_slice4ExprEINtNtNtCs2EYQwhfuABO_4core3ops5index5IndexjE5indexBH_".to_string(), cm_shim_vec_expr_index as *const u8);
    externs.insert("_RNvXsc_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecNtCskGOzeDtWnTB_25clean_recursor_type_slice5LevelEINtNtNtCs2EYQwhfuABO_4core3ops5index5IndexjE5indexBH_".to_string(), cm_shim_vec_lvl_index as *const u8);
    externs.insert("_RNvXsc_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecTNtCskGOzeDtWnTB_25clean_recursor_type_slice10BinderDataNtBI_4ExprEEINtNtNtCs2EYQwhfuABO_4core3ops5index5IndexjE5indexBI_".to_string(), cm_shim_vec_bdexpr_index as *const u8);
    externs.insert("_RNvXsc_NtCskTzINo8ZBH9_5alloc3vecINtB5_3VecTNtCskGOzeDtWnTB_25clean_recursor_type_slice4ExprbEEINtNtNtCs2EYQwhfuABO_4core3ops5index5IndexjE5indexBI_".to_string(), ct_shim_vec_exprbool_index as *const u8);
