#[inline]
fn cu_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let mut h = h ^ k;
    h = h.wrapping_mul(M);
    h
}

struct CuKaniHasher {
    state: u64,
}
impl CuKaniHasher {
    fn new() -> Self {
        CuKaniHasher { state: 0 }
    }
}
impl std::hash::Hasher for CuKaniHasher {
    fn finish(&self) -> u64 {
        self.state
    }
    fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.state = self.state.wrapping_mul(31).wrapping_add(b as u64);
        }
    }
    fn write_u8(&mut self, i: u8) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(0x517cc1b727220a95);
    }
    fn write_u16(&mut self, i: u16) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(0x517cc1b727220a95);
    }
    fn write_u32(&mut self, i: u32) {
        self.state ^= i as u64;
        self.state = self.state.wrapping_mul(0x517cc1b727220a95);
    }
    fn write_u64(&mut self, i: u64) {
        self.state ^= i;
        self.state = self.state.wrapping_mul(0x517cc1b727220a95);
    }
    fn write_u128(&mut self, i: u128) {
        self.write_u64(i as u64);
        self.write_u64((i >> 64) as u64);
    }
    fn write_usize(&mut self, i: usize) {
        self.write_u64(i as u64);
    }
}

#[inline]
fn cu_hash_to_u64<T: std::hash::Hash>(value: &T) -> u64 {
    use std::hash::Hasher;
    let mut hasher = CuKaniHasher::new();
    value.hash(&mut hasher);
    hasher.finish()
}

// ClLevel does not derive Hash (custom PartialEq); mirror the slice's derived
// Level Hash (discriminant write_u8 + recurse) so the oracle's meta-hash equals
// the JIT's <Level as Hash>::hash (a modeling boundary — the meta-hash is a fast
// path; structural_eq + level_eq do the real def-eq work).
fn cu_hash_clevel<H: std::hash::Hasher>(l: &ClLevel, state: &mut H) {
    use std::hash::Hash;
    match l {
        ClLevel::Zero => {
            state.write_u8(0);
        }
        ClLevel::Succ(x) => {
            state.write_u8(1);
            cu_hash_clevel(x, state);
        }
        ClLevel::Max(a, b) => {
            state.write_u8(2);
            cu_hash_clevel(a, state);
            cu_hash_clevel(b, state);
        }
        ClLevel::IMax(a, b) => {
            state.write_u8(3);
            cu_hash_clevel(a, state);
            cu_hash_clevel(b, state);
        }
        ClLevel::Param(n) => {
            state.write_u8(4);
            n.0.hash(state);
        }
    }
}
#[inline]
fn cu_hash_level_to_u64(l: &ClLevel) -> u64 {
    use std::hash::Hasher;
    let mut hasher = CuKaniHasher::new();
    cu_hash_clevel(l, &mut hasher);
    hasher.finish()
}

