    // <Arc<Level> as Hash>::hash (Const level-vector meta hashing).
    externs.insert("_RINvXs12_NtCskTzINo8ZBH9_5alloc4syncINtB7_3ArcNtCsdHZWxF3kolr_21def_eq_universe_slice5LevelENtNtCs2EYQwhfuABO_4core4hash4Hash4hashNtBK_10KaniHasherEBK_".to_string(), cu_shim_hash_arc_level as *const u8);
